import React, { useState, useEffect, useRef } from 'react';

// --- Badge ---
interface BadgeProps {
  children: React.ReactNode;
  variant?: 'success' | 'warning' | 'error' | 'info' | 'neutral' | 'indigo' | 'purple';
  className?: string;
}
export const Badge: React.FC<BadgeProps> = ({ children, variant = 'neutral', className = '' }) => {
  const variants = {
    success: "bg-green-100 text-green-700 border-green-200",
    warning: "bg-yellow-100 text-yellow-700 border-yellow-200",
    error: "bg-red-100 text-red-700 border-red-200",
    info: "bg-blue-100 text-blue-700 border-blue-200",
    neutral: "bg-gray-100 text-gray-700 border-gray-200",
    indigo: "bg-indigo-100 text-indigo-700 border-indigo-200",
    purple: "bg-purple-100 text-purple-700 border-purple-200"
  };
  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold uppercase border ${variants[variant]} ${className}`}>
      {children}
    </span>
  );
};

// --- Button ---
interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'outline' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
}
export const Button: React.FC<ButtonProps> = ({ variant = 'primary', size = 'md', className = '', ...props }) => {
  const baseStyle = "inline-flex items-center justify-center rounded-md font-medium transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed active:scale-95";

  const variants = {
    primary: "bg-blue-600 text-white hover:bg-blue-700 focus:ring-blue-500 shadow-sm",
    secondary: "bg-gray-100 text-gray-900 hover:bg-gray-200 focus:ring-gray-500",
    danger: "bg-red-600 text-white hover:bg-red-700 focus:ring-red-500",
    outline: "border border-gray-300 bg-transparent text-gray-700 hover:bg-gray-50 focus:ring-blue-500",
    ghost: "bg-transparent text-gray-600 hover:bg-gray-100"
  };

  const sizes = {
    sm: "px-3 py-1.5 text-xs",
    md: "px-4 py-2 text-sm",
    lg: "px-6 py-3 text-base"
  };

  return <button className={`${baseStyle} ${variants[variant]} ${sizes[size]} ${className}`} {...props} />;
};

// --- Input ---
interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  label?: string;
  error?: string;
}
export const Input: React.FC<InputProps> = ({ label, error, className = '', ...props }) => (
  <div className="w-full">
    {label && <label className="block text-sm font-semibold text-gray-700 mb-1">{label}</label>}
    <input 
      className={`block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm border p-2 transition-all ${error ? 'border-red-500' : ''} ${className}`} 
      {...props} 
    />
    {error && <p className="mt-1 text-xs text-red-600">{error}</p>}
  </div>
);

// --- Select ---
interface SelectProps extends React.SelectHTMLAttributes<HTMLSelectElement> {
  label?: string;
  options: { value: string; label: string }[];
}
export const Select: React.FC<SelectProps> = ({ label, options, className = '', ...props }) => (
  <div className="w-full">
    {label && <label className="block text-sm font-semibold text-gray-700 mb-1">{label}</label>}
    <select 
      className={`block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm border p-2 bg-white transition-all ${className}`} 
      {...props}
    >
      {options.map(opt => (
        <option key={opt.value} value={opt.value}>{opt.label}</option>
      ))}
    </select>
  </div>
);

// --- Combobox (Input with Suggestions) ---
interface ComboboxProps {
  label?: string;
  value: string;
  onChange: (value: string) => void;
  options: string[];
  placeholder?: string;
}

export const Combobox: React.FC<ComboboxProps> = ({ label, value, onChange, options, placeholder }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState(value);
  const wrapperRef = useRef<HTMLDivElement>(null);

  useEffect(() => { setQuery(value); }, [value]);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, [wrapperRef]);

  const filtered = query === '' 
    ? options 
    : options.filter(opt => opt.toLowerCase().includes(query.toLowerCase()));

  return (
    <div className="w-full relative" ref={wrapperRef}>
      {label && <label className="block text-sm font-semibold text-gray-700 mb-1">{label}</label>}
      <input
        type="text"
        className="block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm border p-2"
        placeholder={placeholder}
        value={query}
        onChange={(e) => { setQuery(e.target.value); onChange(e.target.value); setIsOpen(true); }}
        onFocus={() => setIsOpen(true)}
      />
      {isOpen && filtered.length > 0 && (
        <ul className="absolute z-10 mt-1 max-h-60 w-full overflow-auto rounded-md bg-white py-1 text-base shadow-lg ring-1 ring-black ring-opacity-5 focus:outline-none sm:text-sm border border-gray-100">
          {filtered.map((opt, idx) => (
            <li 
              key={idx} 
              className="relative cursor-pointer select-none py-2 px-3 hover:bg-blue-50 text-gray-900 transition-colors"
              onClick={() => { setQuery(opt); onChange(opt); setIsOpen(false); }}
            >
              {opt}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

// --- Modal ---
interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
  size?: 'md' | 'lg' | 'xl' | 'full';
}
export const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children, size = 'md' }) => {
  if (!isOpen) return null;

  const sizeClasses = {
      md: 'sm:max-w-lg',
      lg: 'sm:max-w-2xl',
      xl: 'sm:max-w-4xl',
      full: 'sm:max-w-[95%] sm:h-[90vh]'
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto">
      <div className="flex min-h-screen items-center justify-center p-4 text-center sm:p-0">
        <div className="fixed inset-0 bg-gray-600 bg-opacity-60 backdrop-blur-sm transition-opacity" onClick={onClose}></div>
        <div className={`relative transform overflow-hidden rounded-xl bg-white text-left shadow-2xl transition-all sm:my-8 sm:w-full ${sizeClasses[size]}`}>
          <div className="bg-white px-4 pb-4 pt-5 sm:p-6 sm:pb-4 h-full flex flex-col">
            <div className="flex justify-between items-center mb-5 border-b pb-3">
                 <h3 className="text-xl font-bold leading-6 text-gray-900">{title}</h3>
                 <button onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors text-3xl leading-none">&times;</button>
            </div>
            <div className="flex-1 overflow-y-auto max-h-[80vh]">
                {children}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

// --- Card ---
export const Card: React.FC<{children: React.ReactNode, className?: string, title?: string}> = ({children, className='', title}) => (
  <div className={`overflow-hidden rounded-xl bg-white shadow-md border border-gray-100 transition-all hover:shadow-lg ${className}`}>
    {title && <div className="px-6 py-4 border-b border-gray-100 bg-gray-50/50"><h3 className="text-sm font-bold uppercase tracking-wider text-gray-600">{title}</h3></div>}
    <div className="px-6 py-5">
      {children}
    </div>
  </div>
);

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { User, Appointment, Consultation, Revenue, RevenueType, AppointmentStatus, ConsultationType, ProjectProfile, Message, SupportType } from '../types';
import { storageService } from '../services/storageService';
import { VIETNAM_PROVINCES } from '../constants';
import { Button, Input, Select, Modal, Card, Combobox, Badge } from '../components/ui';
import { PlusCircle, DollarSign, Calendar, Phone, MapPin, ChevronDown, CheckCircle, Clock, TrendingUp, AlertCircle, Edit, Trash2, Search, FileDown, MessageSquare, Send, X, AlertTriangle, User as UserIcon, Building2, Download } from 'lucide-react';

interface Props {
  user: User;
  isViewOnly?: boolean;
}

declare const XLSX: any;

// Helper format DateVN
const formatDateVN = (isoString: string) => {
    if(!isoString) return '';
    const date = new Date(isoString);
    return `${date.getDate().toString().padStart(2, '0')}/${(date.getMonth() + 1).toString().padStart(2, '0')}/${date.getFullYear()}`;
};

const formatDateTimeVN = (isoString: string) => {
    if(!isoString) return '';
    const date = new Date(isoString);
    const time = isoString.split('T')[1];
    return `${time} - ${date.getDate().toString().padStart(2, '0')}/${(date.getMonth() + 1).toString().padStart(2, '0')}/${date.getFullYear()}`;
};

export const EmployeeDashboard: React.FC<Props> = ({ user, isViewOnly = false }) => {
  // --- STATE ---
  const [activeTab, setActiveTab] = useState<'timeline' | 'projects' | 'chat'>('timeline');
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [consultations, setConsultations] = useState<Consultation[]>([]);
  const [revenues, setRevenues] = useState<Revenue[]>([]);
  const [projects, setProjects] = useState<ProjectProfile[]>([]);

  // Messaging State
  const [messages, setMessages] = useState<Message[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Search & Filter
  const [searchTerm, setSearchTerm] = useState('');
  const [filterDate, setFilterDate] = useState(''); 

  // Modals
  const [showAppModal, setShowAppModal] = useState(false);
  const [showConsModal, setShowConsModal] = useState(false);
  const [showRevModal, setShowRevModal] = useState(false);

  // Warnings & Finders
  const [duplicateWarning, setDuplicateWarning] = useState<string | null>(null);
  const [revSearchPhone, setRevSearchPhone] = useState('');

  // Expand State
  const [expandedDates, setExpandedDates] = useState<Record<string, boolean>>({});

  // Form States
  const getNowISO = () => {
      const now = new Date();
      now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
      return now.toISOString().slice(0, 16);
  };

  const [editingId, setEditingId] = useState<string | null>(null);
  const [newApp, setNewApp] = useState<Partial<Appointment>>({ date: getNowISO(), status: AppointmentStatus.NEW, location: '' });
  const [newCons, setNewCons] = useState<Partial<Consultation>>({ date: getNowISO(), type: ConsultationType.NEW, supportType: SupportType.SOLO });

  const [newRev, setNewRev] = useState<Partial<Revenue> & { 
      customerName?: string;
      phone?: string;
      email?: string;
      companyName?: string;
      address?: string;
      region?: string;
  }>({ date: getNowISO(), type: RevenueType.NEW, isApproved: false });

  // --- LOGIC ---
  const loadData = () => {
    setAppointments(storageService.getAppointments().filter(a => a.userId === user.id));
    setConsultations(storageService.getConsultations().filter(c => c.userId === user.id));
    setRevenues(storageService.getRevenues().filter(r => r.userId === user.id));
    setProjects(storageService.getProjects().filter(p => p.userId === user.id));

    const allMsgs = storageService.getMessages();
    const myMsgs = allMsgs.filter(m => {
        if (m.senderId === user.id) return true;
        if (m.receiverId === 'ALL') return true;
        if (Array.isArray(m.receiverId)) return m.receiverId.includes(user.id);
        return m.receiverId === user.id;
    }).sort((a,b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
    setMessages(myMsgs);
  };

  useEffect(() => { loadData(); }, [user.id]);

  useEffect(() => {
      if (activeTab === 'chat') {
          chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
      }
  }, [messages, activeTab]);

  const projectTableData = useMemo(() => {
    return projects.map(proj => {
        const relatedRevs = revenues.filter(r => r.contractCode === proj.contractCode);
        const col1 = relatedRevs.filter(r => r.type === RevenueType.NEW).reduce((s, r) => s + r.amountCollected, 0);
        const col2 = relatedRevs.filter(r => r.type === RevenueType.HOSTING).reduce((s, r) => s + r.amountCollected, 0);
        const col3 = relatedRevs.filter(r => r.type === RevenueType.HANDOVER).reduce((s, r) => s + r.amountCollected, 0);
        const colUpgrade = relatedRevs.filter(r => r.type === RevenueType.UPGRADE_WEB || r.type === RevenueType.UPGRADE_HOSTING).reduce((s, r) => s + r.amountCollected, 0);
        const newRevItem = relatedRevs.find(r => r.type === RevenueType.NEW);

        let customerName = proj.customerName;
        let phone = proj.phone;
        let email = proj.email;
        let companyName = proj.companyName;
        let region = proj.region;

        if (!customerName && newRevItem) {
           const customerInfo = appointments.find(a => a.date <= newRevItem.date && (a.status === AppointmentStatus.CLOSED || a.status === AppointmentStatus.INTERESTED));
           if (customerInfo) {
               customerName = customerInfo.customerName;
               phone = customerInfo.phone;
               email = customerInfo.email;
               companyName = customerInfo.companyName;
               if (!region) region = customerInfo.location;
           }
        }

        const relatedCons = consultations.find(c => (phone && c.phone === phone) || (customerName && c.customerName === customerName));
        let jointSignerName = proj.jointSigner;
        if (!jointSignerName && relatedCons && relatedCons.supportType !== SupportType.SOLO) {
            jointSignerName = relatedCons.supportPersonName || '';
        }

        const totalVal = relatedRevs.find(r => r.type === RevenueType.NEW)?.contractValue || 0;
        const signDateDisplay = proj.signDate || (newRevItem?.date ? formatDateVN(newRevItem.date) : '');
        const handoverDateDisplay = proj.handoverDate || (relatedRevs.find(r => r.type === RevenueType.HANDOVER)?.date ? formatDateVN(relatedRevs.find(r => r.type === RevenueType.HANDOVER)!.date) : '');
        const autoStatus = (col3 > 0) ? 'Hoàn thành' : (proj.status || 'Đang chạy');

        return {
            ...proj,
            customerName: customerName || '',
            phone: phone || '',
            email: email || '',
            companyName: companyName || '',
            region: region || '',
            status: autoStatus,
            signDate: signDateDisplay,
            handoverDate: handoverDateDisplay,
            contractValue: totalVal,
            col1, col2, col3, colUpgrade,
            totalCollected: col1 + col2 + col3 + colUpgrade,
            jointSigner: jointSignerName || ''
        };
    });
  }, [projects, revenues, appointments, consultations]);

  const filteredData = useMemo(() => {
    const lowerTerm = searchTerm.toLowerCase();
    const filterFn = (item: any) => {
        const matchesTerm = (item.customerName?.toLowerCase().includes(lowerTerm)) || (item.phone?.includes(lowerTerm)) || (item.contractCode?.toLowerCase().includes(lowerTerm));
        const matchesDate = filterDate ? item.date.startsWith(filterDate) : true;
        return matchesTerm && matchesDate;
    };
    return {
        apps: appointments.filter(filterFn),
        cons: consultations.filter(filterFn),
        revs: revenues.filter(filterFn)
    };
  }, [appointments, consultations, revenues, searchTerm, filterDate]);

  const timelineData = useMemo(() => {
    const dates = new Set([
        ...filteredData.apps.map(a => a.date.split('T')[0]),
        ...filteredData.cons.map(c => c.date.split('T')[0]),
        ...filteredData.revs.map(r => r.date.split('T')[0])
    ]);
    const sortedDates = Array.from(dates).sort().reverse();
    const list = sortedDates.map(dateStr => ({
        date: dateStr,
        displayDate: formatDateVN(dateStr),
        apps: filteredData.apps.filter(a => a.date.startsWith(dateStr)),
        cons: filteredData.cons.filter(c => c.date.startsWith(dateStr)),
        revs: filteredData.revs.filter(r => r.date.startsWith(dateStr)),
    }));
    const initialExpanded: Record<string, boolean> = {};
    if (list.length > 0) initialExpanded[list[0].date] = true;
    return { list, initialExpanded };
  }, [filteredData]); 

  useEffect(() => {
     if (Object.keys(expandedDates).length === 0 && Object.keys(timelineData.initialExpanded).length > 0) {
         setExpandedDates(timelineData.initialExpanded);
     }
  }, [timelineData.initialExpanded]);

  // --- Handlers ---
  const handleExportExcel = () => {
    if (projectTableData.length === 0) return alert("Không có dữ liệu để xuất");

    const worksheet = XLSX.utils.json_to_sheet(projectTableData.map(r => ({
        "Tên Khách Hàng": r.customerName,
        "Số Điện Thoại": r.phone,
        "Công Ty": r.companyName,
        "Email": r.email,
        "Mã Hợp Đồng": r.contractCode,
        "Tỉnh/Thành": r.region,
        "Trạng Thái": r.status,
        "Gói Web": r.contractValue,
        "Thu Lần 1 (Ký Mới)": r.col1,
        "Thu Lần 2 (Hosting)": r.col2,
        "Thu Lần 3 (Bàn Giao)": r.col3,
        "Doanh Thu Nâng Cấp": r.colUpgrade,
        "Tổng Thu": r.totalCollected,
        "Ngày Ký": r.signDate,
        "Ngày Bàn Giao": r.handoverDate,
        "Người Ký Chung": r.jointSigner,
        "Link Design": r.designLink,
        "Trang Web": r.webLink,
        "Zalo Group": r.zaloGroup
    })));

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Projects");
    XLSX.writeFile(workbook, `SaleFlow_Projects_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const checkDuplicatePhone = (phone: string) => {
      if (!phone || phone.length < 9) {
          setDuplicateWarning(null);
          return;
      }
      const teamDup = storageService.findTeamDuplicate(phone, user.id);
      if (teamDup) {
           setDuplicateWarning(`Trùng với ${teamDup.name} (${teamDup.role})`);
      } else {
           setDuplicateWarning(null);
      }
  };

  const getDuplicateTag = (phone: string) => {
      const dup = storageService.findTeamDuplicate(phone, user.id);
      return dup ? `Trùng: ${dup.name}` : null;
  };

  const handlePhoneBlurForCons = () => {
    if (newCons.phone) {
      checkDuplicatePhone(newCons.phone);
      const result = storageService.findGlobalAppointmentByPhone(newCons.phone);
      if (result) {
        const app = result.appointment;
        setNewCons(prev => ({ 
            ...prev, 
            customerName: app.customerName, 
            appointmentId: app.id,
            companyName: app.companyName,
            source: app.source,
            addressDetail: `${app.addressDetail || ''} ${app.location ? '- ' + app.location : ''}`,
            notes: prev.notes || app.notes
        }));
      }
    }
  };

  const handleRevPhoneSearch = () => {
      if (!revSearchPhone) return alert("Vui lòng nhập SĐT");
      const custData = storageService.findCustomerByPhone(revSearchPhone);
      if (custData) {
          setNewRev(prev => ({
              ...prev,
              phone: revSearchPhone,
              customerName: custData.name,
              companyName: custData.company,
              address: custData.address,
              region: custData.city,
              contractCode: (custData as any).contractCode || prev.contractCode
          }));
          alert(`Đã tìm thấy thông tin khách hàng: ${custData.name}`);
      } else {
          alert("Không tìm thấy thông tin. Vui lòng nhập thủ công.");
      }
  };

  const handleEditApp = (app: Appointment) => {
      setEditingId(app.id); setNewApp(app); setDuplicateWarning(null); setShowAppModal(true);
  };
  const handleEditCons = (cons: Consultation) => {
      setEditingId(cons.id); setNewCons(cons); setDuplicateWarning(null); setShowConsModal(true);
  };
  const handleEditRev = (rev: Revenue) => {
      setEditingId(rev.id);
      const project = projects.find(p => p.contractCode === rev.contractCode);
      setNewRev({
          ...rev,
          customerName: project?.customerName || '',
          phone: project?.phone || '',
          companyName: project?.companyName || '',
          address: project?.address || '',
          region: project?.region || ''
      });
      setShowRevModal(true);
  };

  const handleSendMessage = () => {
      if (!chatMessage.trim()) return;
      storageService.sendMessage({ id: `MSG${Date.now()}`, senderId: user.id, senderName: user.name, receiverId: 'ADMIN', content: chatMessage, timestamp: new Date().toISOString(), isRead: false });
      setChatMessage(''); loadData();
  };

  const handleUpdateProject = (proj: ProjectProfile, field: keyof ProjectProfile, value: string) => {
      const updated = { ...proj, [field]: value };
      storageService.updateProject(updated);
      setProjects(prev => prev.map(p => p.contractCode === proj.contractCode ? updated : p));
  };

  const submitForm = (action: () => void, modalSetter: (v: boolean) => void) => {
    try { action(); modalSetter(false); loadData(); setFilterDate(''); } catch (e: any) { alert(e.message); }
  };

  const formatCurrency = (val: number) => new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(val);
  const toggleDate = (date: string) => setExpandedDates(prev => ({ ...prev, [date]: !prev[date] }));
  const formatTimeOnly = (isoString: string) => isoString.split('T')[1];
  const unreadCount = messages.filter(m => !m.isRead && m.senderId !== user.id).length;

  const getStatusVariant = (status: string) => {
      if (status === 'Chốt' || status === 'Hoàn thành') return 'success';
      if (status === 'Hủy') return 'error';
      if (status === 'Quan tâm') return 'indigo';
      if (status === 'Lưỡng lự') return 'warning';
      return 'info';
  };

  return (
    <div className="space-y-6 animate-fadeIn relative">

      {/* Main Tabs */}
      <div className="bg-white rounded-xl shadow-md border border-gray-100 p-1.5 flex gap-2">
          <button onClick={() => setActiveTab('timeline')} className={`flex-1 py-3 rounded-lg font-bold text-sm flex items-center justify-center gap-2 transition-all ${activeTab === 'timeline' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-50'}`}>
              <Clock size={18}/> NHẬT KÝ HOẠT ĐỘNG
          </button>
          <button onClick={() => setActiveTab('projects')} className={`flex-1 py-3 rounded-lg font-bold text-sm flex items-center justify-center gap-2 transition-all ${activeTab === 'projects' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-50'}`}>
              <FileDown size={18}/> DỮ LIỆU DỰ ÁN
          </button>
          <button onClick={() => setActiveTab('chat')} className={`flex-1 py-3 rounded-lg font-bold text-sm flex items-center justify-center gap-2 transition-all ${activeTab === 'chat' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-50'}`}>
              <MessageSquare size={18}/> TRAO ĐỔI
              {unreadCount > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full animate-bounce">{unreadCount}</span>}
          </button>
      </div>

      {activeTab === 'timeline' && (
      <>
        <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-100 flex flex-col lg:flex-row gap-4 items-center justify-between">
             <div className="flex gap-4 w-full lg:w-auto flex-1">
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={18} />
