import { User, Department, Appointment, Consultation, Revenue, RevenueType, AppointmentStatus, ProjectProfile, Message, SupportType, ConsultationType, UserRole, ROLE_RANK } from '../types';

// Changed keys to ensure we don't load old mock data from previous sessions
const KEYS = {
  USERS: 'sf_real_users',
  DEPTS: 'sf_real_depts',
  APPS: 'sf_real_appointments',
  CONSULTS: 'sf_real_consultations',
  REVENUES: 'sf_real_revenues',
  PROJECTS: 'sf_real_projects',
  MESSAGES: 'sf_real_messages',
  CURRENT_USER: 'sf_real_current_user'
};

// Initialize System: Only run if no users exist
const initializeSystem = () => {
  const usersStr = localStorage.getItem(KEYS.USERS);
  if (!usersStr || JSON.parse(usersStr).length === 0) {
    console.log("Initializing Real Data System...");

    // 1. Create Default Admin
    const admin: User = {
      id: 'ADMIN',
      name: 'Administrator',
      role: UserRole.DIRECTOR,
      password: 'admin', // Default password
      position: 'System Admin',
      joinDate: new Date().toISOString(),
      initialRevenue: 0
    };
    localStorage.setItem(KEYS.USERS, JSON.stringify([admin]));

    // 2. Create Default Department
    const hq: Department = {
      id: 'HQ',
      name: 'Trụ sở chính',
      managerName: 'Administrator'
    };
    localStorage.setItem(KEYS.DEPTS, JSON.stringify([hq]));

    // 3. Initialize empty arrays for other entities to avoid null checks later
    if(!localStorage.getItem(KEYS.APPS)) localStorage.setItem(KEYS.APPS, JSON.stringify([]));
    if(!localStorage.getItem(KEYS.CONSULTS)) localStorage.setItem(KEYS.CONSULTS, JSON.stringify([]));
    if(!localStorage.getItem(KEYS.REVENUES)) localStorage.setItem(KEYS.REVENUES, JSON.stringify([]));
    if(!localStorage.getItem(KEYS.PROJECTS)) localStorage.setItem(KEYS.PROJECTS, JSON.stringify([]));
    if(!localStorage.getItem(KEYS.MESSAGES)) localStorage.setItem(KEYS.MESSAGES, JSON.stringify([]));
  }
};

initializeSystem();

export const storageService = {
  // Auth
  login: (code: string, password?: string): User | null => {
    const users = JSON.parse(localStorage.getItem(KEYS.USERS) || '[]');
    // Simple check: match ID and Password
    return users.find((u: User) => u.id === code && (u.password === password || (!u.password && !password))) || null;
  },
  logout: () => { localStorage.removeItem(KEYS.CURRENT_USER); },

  // --- CRUD Standard ---
  getDepartments: (): Department[] => JSON.parse(localStorage.getItem(KEYS.DEPTS) || '[]'),
  addDepartment: (item: Department) => {
    const list = storageService.getDepartments(); list.push(item);
    localStorage.setItem(KEYS.DEPTS, JSON.stringify(list));
  },
  updateDepartment: (item: Department) => {
    const list = storageService.getDepartments().map(d => d.id === item.id ? item : d);
    localStorage.setItem(KEYS.DEPTS, JSON.stringify(list));
  },
  deleteDepartment: (id: string) => {
    const list = storageService.getDepartments().filter(d => d.id !== id);
    localStorage.setItem(KEYS.DEPTS, JSON.stringify(list));
  },

  getUsers: (): User[] => JSON.parse(localStorage.getItem(KEYS.USERS) || '[]'),

  // Recursively get all subordinates for a manager
  getSubordinates: (managerId: string): User[] => {
      const allUsers = storageService.getUsers();
      const result: User[] = [];

      const findDirectReports = (id: string) => {
          const directReports = allUsers.filter(u => u.managerId === id);
          for (const report of directReports) {
              result.push(report);
              findDirectReports(report.id); // Recurse
          }
      };

      findDirectReports(managerId);
      return result;
  },

  addUser: (item: User) => {
    const list = storageService.getUsers();
    if (list.find(u => u.id === item.id)) throw new Error("Mã nhân viên đã tồn tại");
    list.push(item);
    localStorage.setItem(KEYS.USERS, JSON.stringify(list));
  },
  updateUser: (item: User) => {
    const list = storageService.getUsers().map(u => u.id === item.id ? item : u);
    localStorage.setItem(KEYS.USERS, JSON.stringify(list));
  },
  deleteUser: (id: string) => {
    if (id === 'ADMIN') throw new Error("Không thể xóa Admin chính");
    const list = storageService.getUsers().filter(u => u.id !== id);
    localStorage.setItem(KEYS.USERS, JSON.stringify(list));
  },

  getAppointments: (): Appointment[] => JSON.parse(localStorage.getItem(KEYS.APPS) || '[]'),
  addAppointment: (item: Appointment) => {
    const list = storageService.getAppointments(); list.push(item);
    localStorage.setItem(KEYS.APPS, JSON.stringify(list));
  },
  updateAppointment: (item: Appointment) => {
    const list = storageService.getAppointments().map(i => i.id === item.id ? item : i);
    localStorage.setItem(KEYS.APPS, JSON.stringify(list));
  },
  deleteAppointment: (id: string) => {
    const list = storageService.getAppointments().filter(i => i.id !== id);
    localStorage.setItem(KEYS.APPS, JSON.stringify(list));
  },

  getConsultations: (): Consultation[] => JSON.parse(localStorage.getItem(KEYS.CONSULTS) || '[]'),
  addConsultation: (item: Consultation) => {
    const list = storageService.getConsultations(); list.push(item);
    localStorage.setItem(KEYS.CONSULTS, JSON.stringify(list));
  },
  updateConsultation: (item: Consultation) => {
    const list = storageService.getConsultations().map(i => i.id === item.id ? item : i);
    localStorage.setItem(KEYS.CONSULTS, JSON.stringify(list));
  },
  deleteConsultation: (id: string) => {
    const list = storageService.getConsultations().filter(i => i.id !== id);
    localStorage.setItem(KEYS.CONSULTS, JSON.stringify(list));
  },

  getRevenues: (): Revenue[] => JSON.parse(localStorage.getItem(KEYS.REVENUES) || '[]'),
  addRevenue: (item: Revenue) => {
    const list = storageService.getRevenues(); list.push(item);
    localStorage.setItem(KEYS.REVENUES, JSON.stringify(list));

    // Auto-create Project Profile if NEW contract
    if (item.type === RevenueType.NEW) {
      const projects = storageService.getProjects();
      if (!projects.find(p => p.contractCode === item.contractCode)) {
        storageService.addProject({
          contractCode: item.contractCode,
          userId: item.userId,
          status: 'Mới'
        });
      }
    }
  },
  updateRevenue: (item: Revenue) => {
    const list = storageService.getRevenues().map(i => i.id === item.id ? item : i);
    localStorage.setItem(KEYS.REVENUES, JSON.stringify(list));
  },
  deleteRevenue: (id: string) => {
    const list = storageService.getRevenues().filter(i => i.id !== id);
    localStorage.setItem(KEYS.REVENUES, JSON.stringify(list));
  },

  // --- Project Profiles ---
  getProjects: (): ProjectProfile[] => JSON.parse(localStorage.getItem(KEYS.PROJECTS) || '[]'),
  addProject: (item: ProjectProfile) => {
    const list = storageService.getProjects();
    // Check duplicate
    if (!list.find(p => p.contractCode === item.contractCode)) {
        list.push(item);
        localStorage.setItem(KEYS.PROJECTS, JSON.stringify(list));
    }
  },
  updateProject: (item: ProjectProfile) => {
    const list = storageService.getProjects().map(p => p.contractCode === item.contractCode ? item : p);
    localStorage.setItem(KEYS.PROJECTS, JSON.stringify(list));
  },

  // --- Messages ---
  getMessages: (): Message[] => JSON.parse(localStorage.getItem(KEYS.MESSAGES) || '[]'),
  sendMessage: (msg: Message) => {
    const list = storageService.getMessages(); list.push(msg);
    localStorage.setItem(KEYS.MESSAGES, JSON.stringify(list));
  },
  markMessageRead: (msgId: string) => {
    const list = storageService.getMessages().map(m => m.id === msgId ? { ...m, isRead: true } : m);
    localStorage.setItem(KEYS.MESSAGES, JSON.stringify(list));
  },

  // --- Helpers ---
  findGlobalAppointmentByPhone: (phone: string): { appointment: Appointment, creatorName: string } | null => {
    const apps = storageService.getAppointments();
    const users = storageService.getUsers();

    const found = apps.filter(a => a.phone === phone).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0];

    if (found) {
        const creator = users.find(u => u.id === found.userId);
        return { appointment: found, creatorName: creator ? creator.name : found.userId };
    }
    return null;
  },

  findTeamDuplicate: (phone: string, currentUserId: string): { name: string, role: string } | null => {
      const users = storageService.getUsers();
      const currentUser = users.find(u => u.id === currentUserId);
      if (!currentUser || !currentUser.managerId) return null;

      const teamMembers = users.filter(u => u.managerId === currentUser.managerId && u.id !== currentUserId);
      const teamIds = teamMembers.map(u => u.id);

      const apps = storageService.getAppointments().filter(a => teamIds.includes(a.userId) && a.phone === phone);
      if (apps.length > 0) {
          const owner = teamMembers.find(u => u.id === apps[0].userId);
          if (owner) return { name: owner.name, role: 'Hẹn' };
      }

      const consults = storageService.getConsultations().filter(c => teamIds.includes(c.userId) && c.phone === phone);
      if (consults.length > 0) {
           const owner = teamMembers.find(u => u.id === consults[0].userId);
           if (owner) return { name: owner.name, role: 'Tư vấn' };
      }

      return null;
  },

  findCustomerByPhone: (phone: string) => {
      const apps = storageService.getAppointments();
      const consults = storageService.getConsultations();
      const projects = storageService.getProjects();

      const proj = projects.find(p => p.phone === phone);
      if (proj) {
          return { 
              name: proj.customerName || '', 
              company: proj.companyName || '', 
              address: proj.address || '', 
              source: proj.source || '',
              contractCode: proj.contractCode, 
              city: proj.region || '' 
          };
      }

      const app = apps.find(a => a.phone === phone);
      if (app) return { 
          name: app.customerName, 
          company: app.companyName, 
          address: app.addressDetail, 
          source: app.source,
          city: app.location 
      };

      const cons = consults.find(c => c.phone === phone);
      if (cons) return { 
          name: cons.customerName, 
          company: cons.companyName, 
          address: cons.addressDetail, 
          source: cons.source,
          city: '' 
      };

      return null;
  },

  getContractCandidatesForHandover: (userId: string): Revenue[] => {
    const revs = storageService.getRevenues();
    return revs.filter(r => r.userId === userId && r.type === RevenueType.NEW);
  }
};

