  const getDuplicateTag = (phone: string) => {
      const dup = storageService.findTeamDuplicate(phone, user.id);
      return dup ? `Trùng: ${dup.name}` : null;
  };

  const handlePhoneBlurForCons = () => {
    if (newCons.phone) {
      checkDuplicatePhone(newCons.phone);
      const result = storageService.findGlobalAppointmentByPhone(newCons.phone);
      if (result) {
        const app = result.appointment;
        setNewCons(prev => ({ 
            ...prev, 
            customerName: app.customerName, 
            appointmentId: app.id,
            companyName: app.companyName,
            source: app.source,
            addressDetail: `${app.addressDetail || ''} ${app.location ? '- ' + app.location : ''}`,
            notes: prev.notes || app.notes
        }));
      }
    }
  };

  const handleRevPhoneSearch = () => {
      if (!revSearchPhone) return alert("Vui lòng nhập SĐT");
