      if (custData) {
          setNewRev(prev => ({
              ...prev,
              phone: revSearchPhone,
              customerName: custData.name,
              companyName: custData.company,
              address: custData.address,
              region: custData.city,
              contractCode: (custData as any).contractCode || prev.contractCode
          }));
          alert(`Đã tìm thấy thông tin khách hàng: ${custData.name}`);
      } else {
          alert("Không tìm thấy thông tin. Vui lòng nhập thủ công.");
      }
  };

  const handleEditApp = (app: Appointment) => {
      setEditingId(app.id); setNewApp(app); setDuplicateWarning(null); setShowAppModal(true);
  };
  const handleEditCons = (cons: Consultation) => {
      setEditingId(cons.id); setNewCons(cons); setDuplicateWarning(null); setShowConsModal(true);
  };
  const handleEditRev = (rev: Revenue) => {
      setEditingId(rev.id);
      const project = projects.find(p => p.contractCode === rev.contractCode);
      setNewRev({
          ...rev,
          customerName: project?.customerName || '',
          phone: project?.phone || '',
          companyName: project?.companyName || '',
          address: project?.address || '',
          region: project?.region || ''
      });
      setShowRevModal(true);
  };

