import { db } from './firebaseConfig';
import { collection, getDocs, doc, setDoc, updateDoc, deleteDoc, query, where, getDoc } from 'firebase/firestore';
import { User, Department, Appointment, Consultation, Revenue, RevenueType, ProjectProfile, Message, UserRole } from '../types';

// Collection Names in Firestore
const COLS = {
  USERS: 'users',
  DEPTS: 'departments',
  APPS: 'appointments',
  CONSULTS: 'consultations',
  REVENUES: 'revenues',
  PROJECTS: 'projects',
  MESSAGES: 'messages'
};

// Helper to map Firestore docs to our types
const mapDoc = (doc: any) => ({ ...doc.data(), id: doc.id });

export const storageService = {
  // --- Auth & System Init ---

  // Check and seed default admin if system is empty
  initializeSystem: async () => {
    try {
        const usersSnap = await getDocs(collection(db, COLS.USERS));
        if (usersSnap.empty) {
            console.log("System empty. Seeding default Admin...");

            const admin: User = {
                id: 'ADMIN',
                name: 'Administrator',
                role: UserRole.DIRECTOR,
                password: 'admin',
                position: 'System Admin',
                joinDate: new Date().toISOString(),
                initialRevenue: 0
            };
            await setDoc(doc(db, COLS.USERS, 'ADMIN'), admin);

            const hq: Department = {
                id: 'HQ',
                name: 'Trụ sở chính',
                managerName: 'Administrator'
            };
            await setDoc(doc(db, COLS.DEPTS, 'HQ'), hq);
        }
    } catch (error) {
        console.error("Init Error:", error);
    }
  },

  login: async (code: string, password?: string): Promise<User | null> => {
    try {
        // Ensure system is initialized
        await storageService.initializeSystem();

        const docRef = doc(db, COLS.USERS, code);
        const docSnap = await getDoc(docRef);

        if (docSnap.exists()) {
            const user = mapDoc(docSnap) as User;
            // Simple password check (In production, use Firebase Auth or Hash)
            if (user.password === password || (!user.password && !password)) {
                localStorage.setItem('sf_current_user_id', user.id); // Keep session locally
                return user;
            }
        }
        return null;
    } catch (e) {
        console.error("Login Error:", e);
        return null;
    }
  },

  logout: () => {
    localStorage.removeItem('sf_current_user_id');
  },

  getCurrentUser: async (): Promise<User | null> => {
      const id = localStorage.getItem('sf_current_user_id');
      if (!id) return null;
      const docSnap = await getDoc(doc(db, COLS.USERS, id));
      return docSnap.exists() ? (mapDoc(docSnap) as User) : null;
  },

  // --- CRUD Standard (Now Async) ---

  // DEPARTMENTS
  getDepartments: async (): Promise<Department[]> => {
      const snap = await getDocs(collection(db, COLS.DEPTS));
      return snap.docs.map(d => mapDoc(d) as Department);
  },
  addDepartment: async (item: Department) => {
      await setDoc(doc(db, COLS.DEPTS, item.id), item);
  },
  updateDepartment: async (item: Department) => {
      await updateDoc(doc(db, COLS.DEPTS, item.id), { ...item });
  },
  deleteDepartment: async (id: string) => {
      await deleteDoc(doc(db, COLS.DEPTS, id));
  },

  // USERS
  getUsers: async (): Promise<User[]> => {
      const snap = await getDocs(collection(db, COLS.USERS));
      return snap.docs.map(d => mapDoc(d) as User);
  },

  // Get Subordinates recursively (Requires fetching all users first - client side filtering for tree)
  getSubordinates: async (managerId: string): Promise<User[]> => {
      const allUsers = await storageService.getUsers();
      const result: User[] = [];

      const findDirectReports = (id: string) => {
          const directReports = allUsers.filter(u => u.managerId === id);
          for (const report of directReports) {
              result.push(report);
              findDirectReports(report.id);
          }
      };

      findDirectReports(managerId);
      return result;
  },

  addUser: async (item: User) => {
      const check = await getDoc(doc(db, COLS.USERS, item.id));
      if (check.exists()) throw new Error("Mã nhân viên đã tồn tại");
      await setDoc(doc(db, COLS.USERS, item.id), item);
  },
  updateUser: async (item: User) => {
      await updateDoc(doc(db, COLS.USERS, item.id), { ...item });
  },
  deleteUser: async (id: string) => {
      if (id === 'ADMIN') throw new Error("Không thể xóa Admin chính");
      await deleteDoc(doc(db, COLS.USERS, id));
  },

  // APPOINTMENTS
  getAppointments: async (): Promise<Appointment[]> => {
      const snap = await getDocs(collection(db, COLS.APPS));
      return snap.docs.map(d => mapDoc(d) as Appointment);
  },
  addAppointment: async (item: Appointment) => {
      await setDoc(doc(db, COLS.APPS, item.id), item);
  },
  updateAppointment: async (item: Appointment) => {
      await updateDoc(doc(db, COLS.APPS, item.id), { ...item });
  },
  deleteAppointment: async (id: string) => {
      await deleteDoc(doc(db, COLS.APPS, id));
  },

  // CONSULTATIONS
  getConsultations: async (): Promise<Consultation[]> => {
      const snap = await getDocs(collection(db, COLS.CONSULTS));
      return snap.docs.map(d => mapDoc(d) as Consultation);
  },
  addConsultation: async (item: Consultation) => {
      await setDoc(doc(db, COLS.CONSULTS, item.id), item);
  },
  updateConsultation: async (item: Consultation) => {
      await updateDoc(doc(db, COLS.CONSULTS, item.id), { ...item });
  },
  deleteConsultation: async (id: string) => {
      await deleteDoc(doc(db, COLS.CONSULTS, id));
  },

  // REVENUES
  getRevenues: async (): Promise<Revenue[]> => {
      const snap = await getDocs(collection(db, COLS.REVENUES));
      return snap.docs.map(d => mapDoc(d) as Revenue);
  },
  addRevenue: async (item: Revenue) => {
      await setDoc(doc(db, COLS.REVENUES, item.id), item);

      // Auto-create Project Profile if NEW contract
      if (item.type === RevenueType.NEW) {
          const q = query(collection(db, COLS.PROJECTS), where("contractCode", "==", item.contractCode));
          const querySnapshot = await getDocs(q);
          if (querySnapshot.empty) {
              await storageService.addProject({
                  contractCode: item.contractCode,
                  userId: item.userId,
                  status: 'Mới'
              });
          }
      }
  },
  updateRevenue: async (item: Revenue) => {
      await updateDoc(doc(db, COLS.REVENUES, item.id), { ...item });
  },
  deleteRevenue: async (id: string) => {
      await deleteDoc(doc(db, COLS.REVENUES, id));
  },

  // PROJECT PROFILES
  getProjects: async (): Promise<ProjectProfile[]> => {
      const snap = await getDocs(collection(db, COLS.PROJECTS));
      return snap.docs.map(d => mapDoc(d) as ProjectProfile);
  },
  addProject: async (item: ProjectProfile) => {
      // Use contractCode as ID for uniqueness check
      // But contractCode might change? Better to use a separate ID or ensure code is unique.
      // For now, let's query first.
      const q = query(collection(db, COLS.PROJECTS), where("contractCode", "==", item.contractCode));
      const querySnapshot = await getDocs(q);

      if (querySnapshot.empty) {
          // Create a safe ID from contract code or random
          const safeId = `PROJ_${item.contractCode.replace(/\W/g, '')}_${Date.now()}`;
          await setDoc(doc(db, COLS.PROJECTS, safeId), item);
      }
  },
  updateProject: async (item: ProjectProfile) => {
      // Need to find the doc ID by contractCode first, because we don't store doc ID in item usually
      const q = query(collection(db, COLS.PROJECTS), where("contractCode", "==", item.contractCode));
      const snap = await getDocs(q);
      if (!snap.empty) {
          const docId = snap.docs[0].id;
          await updateDoc(doc(db, COLS.PROJECTS, docId), { ...item });
      }
  },

  // MESSAGES
  getMessages: async (): Promise<Message[]> => {
      const snap = await getDocs(collection(db, COLS.MESSAGES));
      return snap.docs.map(d => mapDoc(d) as Message);
  },
  sendMessage: async (msg: Message) => {
      await setDoc(doc(db, COLS.MESSAGES, msg.id), msg);
  },
  markMessageRead: async (msgId: string) => {
      await updateDoc(doc(db, COLS.MESSAGES, msgId), { isRead: true });
  },

  // --- Helpers (Mixed Logic) ---
  findGlobalAppointmentByPhone: async (phone: string): Promise<{ appointment: Appointment, creatorName: string } | null> => {
    const q = query(collection(db, COLS.APPS), where("phone", "==", phone));
    const snap = await getDocs(q);
    const apps = snap.docs.map(d => mapDoc(d) as Appointment);

    // Sort logic client side for now
    const found = apps.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0];

    if (found) {
        const userDoc = await getDoc(doc(db, COLS.USERS, found.userId));
        const creator = userDoc.exists() ? (userDoc.data() as User) : null;
        return { appointment: found, creatorName: creator ? creator.name : found.userId };
    }
    return null;
  },

  findTeamDuplicate: async (phone: string, currentUserId: string): Promise<{ name: string, role: string } | null> => {
      const currentUserDoc = await getDoc(doc(db, COLS.USERS, currentUserId));
      if (!currentUserDoc.exists()) return null;
      const currentUser = currentUserDoc.data() as User;
      if (!currentUser.managerId) return null;

      // Get team members
      const usersQ = query(collection(db, COLS.USERS), where("managerId", "==", currentUser.managerId));
      const usersSnap = await getDocs(usersQ);
      const teamMembers = usersSnap.docs.map(d => mapDoc(d) as User).filter(u => u.id !== currentUserId);
      const teamIds = teamMembers.map(u => u.id);

      if (teamIds.length === 0) return null;

      // Check Appointments
      const appsSnap = await getDocs(query(collection(db, COLS.APPS), where("phone", "==", phone)));
      const apps = appsSnap.docs.map(d => mapDoc(d) as Appointment).filter(a => teamIds.includes(a.userId));

      if (apps.length > 0) {
          const owner = teamMembers.find(u => u.id === apps[0].userId);
          if (owner) return { name: owner.name, role: 'Hẹn' };
      }

      // Check Consultations
      const consSnap = await getDocs(query(collection(db, COLS.CONSULTS), where("phone", "==", phone)));
      const cons = consSnap.docs.map(d => mapDoc(d) as Consultation).filter(c => teamIds.includes(c.userId));

      if (cons.length > 0) {
           const owner = teamMembers.find(u => u.id === cons[0].userId);
           if (owner) return { name: owner.name, role: 'Tư vấn' };
      }

      return null;
  },

  findCustomerByPhone: async (phone: string) => {
      // Check Project Profile first
      const projSnap = await getDocs(query(collection(db, COLS.PROJECTS), where("phone", "==", phone)));
      if (!projSnap.empty) {
          const proj = mapDoc(projSnap.docs[0]) as ProjectProfile;
          return { 
              name: proj.customerName || '', 
              company: proj.companyName || '', 
              address: proj.address || '', 
              source: proj.source || '',
              contractCode: proj.contractCode, 
              city: proj.region || '' 
          };
      }

      // Check Appointments
      const appSnap = await getDocs(query(collection(db, COLS.APPS), where("phone", "==", phone)));
      if (!appSnap.empty) {
          const app = mapDoc(appSnap.docs[0]) as Appointment;
          return { 
            name: app.customerName, 
            company: app.companyName, 
            address: app.addressDetail, 
            source: app.source,
            city: app.location 
          };
      }

      // Check Consults
      const conSnap = await getDocs(query(collection(db, COLS.CONSULTS), where("phone", "==", phone)));
      if (!conSnap.empty) {
          const cons = mapDoc(conSnap.docs[0]) as Consultation;
          return { 
            name: cons.customerName, 
            company: cons.companyName, 
            address: cons.addressDetail, 
            source: cons.source,
            city: '' 
          };
      }

      return null;
  },

  getContractCandidatesForHandover: async (userId: string): Promise<Revenue[]> => {
    const q = query(collection(db, COLS.REVENUES), where("userId", "==", userId), where("type", "==", RevenueType.NEW));
    const snap = await getDocs(q);
    return snap.docs.map(d => mapDoc(d) as Revenue);
  }
};

import React, { useState } from 'react';
import { storageService } from '../services/storageService';
import { User } from '../types';
import { Button, Input } from '../components/ui';
import { LayoutDashboard, Loader2 } from 'lucide-react';

interface LoginProps {
  onLogin: (user: User) => void;
}

export const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [code, setCode] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
        const user = await storageService.login(code, password);
        if (user) {
          onLogin(user);
        } else {
          setError('Mã nhân viên hoặc mật khẩu không đúng.');
        }
    } catch (err) {
        setError('Lỗi kết nối server. Vui lòng thử lại.');
    } finally {
        setIsLoading(false);
    }
  };

  return (
    <div className="flex min-h-screen flex-col justify-center bg-gray-50 py-12 sm:px-6 lg:px-8">
      <div className="sm:mx-auto sm:w-full sm:max-w-md">
        <div className="flex justify-center">
          <div className="rounded-full bg-blue-100 p-3">
            <LayoutDashboard className="h-8 w-8 text-blue-600" />
          </div>
        </div>
        <h2 className="mt-6 text-center text-3xl font-bold tracking-tight text-gray-900">SaleFlow Pro</h2>
        <p className="mt-2 text-center text-sm text-gray-600">Hệ thống quản lý dữ liệu Online (Firebase)</p>
      </div>

      <div className="mt-8 sm:mx-auto sm:w-full sm:max-w-md">
        <div className="bg-white px-4 py-8 shadow sm:rounded-lg sm:px-10">
          <form className="space-y-6" onSubmit={handleSubmit}>
            <Input 
              label="Mã nhân viên" 
              placeholder="Nhập mã nhân viên..."
              value={code} 
              onChange={(e) => setCode(e.target.value)} 
              autoFocus
              disabled={isLoading}
            />
            <Input 
              label="Mật khẩu" 
              type="password"
              placeholder="Nhập mật khẩu"
              value={password} 
              onChange={(e) => setPassword(e.target.value)}
              disabled={isLoading} 
            />

            {error && <p className="text-sm text-red-600">{error}</p>}

            <Button type="submit" className="w-full" size="md" disabled={isLoading}>
              {isLoading ? <><Loader2 className="animate-spin mr-2" size={18}/> Đang kết nối...</> : 'Đăng nhập hệ thống'}
            </Button>
            <div className="text-xs text-gray-500 text-center mt-4">
              <span className="block text-gray-400 mb-1">Tài khoản Quản trị mặc định:</span>
              User: <b className="text-gray-700">ADMIN</b> / Pass: <b className="text-gray-700">admin</b>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { storageService } from '../services/storageService';
import { User, Department, Appointment, Revenue, Message, UserRole, ROLE_RANK, ROLE_LABELS } from '../types';
import { Button, Input, Modal, Select, Card, Badge } from '../components/ui';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { Users, TrendingUp, Calendar, Edit, Trash2, Eye, ArrowLeft, Send, MessageSquare, Search, LayoutGrid, Loader2 } from 'lucide-react';
import { EmployeeDashboard } from './EmployeeDashboard';

interface AdminDashboardProps {
    currentUser: User; 
}

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser }) => {
  const manager = currentUser;
  const [loading, setLoading] = useState(true);

  const [activeTab, setActiveTab] = useState<'dashboard' | 'staff' | 'depts' | 'chat'>('dashboard');
  const [departments, setDepartments] = useState<Department[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [allRevenues, setAllRevenues] = useState<Revenue[]>([]);
  const [allAppointments, setAllAppointments] = useState<Appointment[]>([]);

  const [dashboardScope, setDashboardScope] = useState<'ALL' | 'DEPT' | 'MANAGER' | 'USER'>('ALL');
  const [dashboardFilterId, setDashboardFilterId] = useState('');

  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [selectedChatUser, setSelectedChatUser] = useState<string | null>(null);
  const [adminChatInput, setAdminChatInput] = useState('');
  const [chatSearchTerm, setChatSearchTerm] = useState('');
  const [chatFilterRole, setChatFilterRole] = useState<string>('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const [filterDept, setFilterDept] = useState('');
  const [isMsgModalOpen, setMsgModalOpen] = useState(false);
  const [msgContent, setMsgContent] = useState('');
  const [msgTargetType, setMsgTargetType] = useState<'ALL' | 'DEPT' | 'USER'>('ALL');
  const [msgTargetId, setMsgTargetId] = useState('');

  const [isUserModalOpen, setUserModalOpen] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [formUser, setFormUser] = useState<Partial<User>>({});

  const [isDeptModalOpen, setDeptModalOpen] = useState(false);
  const [editingDeptId, setEditingDeptId] = useState<string | null>(null);
  const [formDept, setFormDept] = useState<Partial<Department>>({});

  const [viewingUser, setViewingUser] = useState<User | null>(null);

  const myRank = ROLE_RANK[manager.role];

  const refreshData = async () => {
      setLoading(true);
      try {
          const [u, d, r, a, m] = await Promise.all([
              storageService.getUsers(),
              storageService.getDepartments(),
              storageService.getRevenues(),
              storageService.getAppointments(),
              storageService.getMessages()
          ]);
          setAllUsers(u);
          setDepartments(d);
          setAllRevenues(r);
          setAllAppointments(a);
          setAllMessages(m);
      } catch (error) {
          console.error("Failed to load data", error);
      } finally {
          setLoading(false);
      }
  };

  const silentRefreshMsg = async () => {
      const m = await storageService.getMessages();
      setAllMessages(m);
  };

  useEffect(() => {
     refreshData();
     const interval = setInterval(() => {
         silentRefreshMsg();
     }, 10000); // Poll every 10s for messages
     return () => clearInterval(interval);
  }, []);

  useEffect(() => {
     if(activeTab === 'chat' && selectedChatUser) {
         chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
     }
  }, [allMessages, selectedChatUser, activeTab]);

  const getSubordinates = (managerId: string) => {
      const result: User[] = [];
      const findDirectReports = (id: string) => {
          const directReports = allUsers.filter(u => u.managerId === id);
          for (const report of directReports) {
              result.push(report);
              findDirectReports(report.id);
          }
      };
      findDirectReports(managerId);
      return result;
  };

  const mySubordinates = useMemo(() => {
      const subs = getSubordinates(manager.id);
      return [manager, ...subs];
  }, [allUsers, manager.id]);

  const displayUsers = useMemo(() => mySubordinates.filter(u => u.id !== manager.id), [mySubordinates, manager.id]);
  const availableManagers = useMemo(() => mySubordinates.filter(u => ROLE_RANK[u.role] > 1), [mySubordinates]);

  const filteredDashboardData = useMemo(() => {
      let targetUsers: User[] = [];
      if (dashboardScope === 'ALL') {
          targetUsers = mySubordinates;
      } else if (dashboardScope === 'DEPT' && dashboardFilterId) {
          targetUsers = mySubordinates.filter(u => u.departmentId === dashboardFilterId);
      } else if (dashboardScope === 'MANAGER' && dashboardFilterId) {
          const subTree = getSubordinates(dashboardFilterId);
          const mgr = mySubordinates.find(u => u.id === dashboardFilterId);
          targetUsers = mgr ? [mgr, ...subTree] : subTree;
      } else if (dashboardScope === 'USER' && dashboardFilterId) {
          const u = mySubordinates.find(u => u.id === dashboardFilterId);
          targetUsers = u ? [u] : [];
      } else {
          targetUsers = mySubordinates;
      }
      const targetIds = targetUsers.map(u => u.id);
      const revs = allRevenues.filter(r => targetIds.includes(r.userId));
      const apps = allAppointments.filter(a => targetIds.includes(a.userId));
      return { users: targetUsers, revenues: revs, appointments: apps };
  }, [dashboardScope, dashboardFilterId, mySubordinates, allRevenues, allAppointments]);

  const analysisData = useMemo(() => {
      const { revenues } = filteredDashboardData;
      const monthlyData: Record<string, number> = {};
      revenues.forEach(r => {
          const month = r.date.substring(0, 7);
          monthlyData[month] = (monthlyData[month] || 0) + r.amountCollected;
      });
      const chartData = Object.keys(monthlyData).sort().map(k => ({ name: k, revenue: monthlyData[k] }));
      let conclusion = "Chưa có đủ dữ liệu để đánh giá.";
      if (chartData.length >= 2) {
          const last = chartData[chartData.length - 1].revenue;
          const prev = chartData[chartData.length - 2].revenue;
          const diff = last - prev;
          const percent = prev > 0 ? ((diff / prev) * 100).toFixed(1) : 100;
          if (diff > 0) conclusion = `Tăng trưởng tích cực: Tháng ${chartData[chartData.length-1].name} tăng ${percent}% so với tháng trước.`;
          else if (diff < 0) conclusion = `Cảnh báo sụt giảm: Tháng ${chartData[chartData.length-1].name} giảm ${Math.abs(Number(percent))}% so với tháng trước.`;
          else conclusion = "Doanh thu ổn định, không có biến động.";
      }
      return { chartData, conclusion, total: revenues.reduce((s,r) => s + r.amountCollected, 0) };
  }, [filteredDashboardData]);

  const chatUsers = useMemo(() => {
      let filtered = displayUsers;
      if (chatSearchTerm) {
          const term = chatSearchTerm.toLowerCase();
          filtered = filtered.filter(u => u.name.toLowerCase().includes(term) || u.id.toLowerCase().includes(term) || (u.phone && u.phone.includes(term)));
      }
      if (chatFilterRole) filtered = filtered.filter(u => u.role === chatFilterRole);
      return filtered;
  }, [displayUsers, chatSearchTerm, chatFilterRole]);

  const currentConversation = useMemo(() => {
      if (!selectedChatUser) return [];
      return allMessages.filter(m => 
          (m.senderId === manager.id && m.receiverId === selectedChatUser) ||
          (m.senderId === selectedChatUser && m.receiverId === manager.id)
      ).sort((a,b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
  }, [allMessages, selectedChatUser, manager.id]);

  const handleAdminReply = async () => {
      if (!selectedChatUser || !adminChatInput.trim()) return;
      await storageService.sendMessage({ id: `MSG${Date.now()}`, senderId: manager.id, senderName: manager.name, receiverId: selectedChatUser, content: adminChatInput, timestamp: new Date().toISOString(), isRead: false });
      setAdminChatInput(''); 
      silentRefreshMsg();
  };

  const handleSendMessage = async () => {
      if (!msgContent) return;
      let receiver: string | string[] = 'ALL';
      if (msgTargetType === 'DEPT') receiver = displayUsers.filter(u => u.departmentId === msgTargetId).map(u => u.id);
      else if (msgTargetType === 'USER') receiver = msgTargetId;
      else receiver = displayUsers.map(u => u.id);
      await storageService.sendMessage({ id: `MSG${Date.now()}`, senderId: manager.id, senderName: manager.name, receiverId: receiver, content: msgContent, timestamp: new Date().toISOString(), isRead: false });
      alert('Đã gửi thông báo thành công!'); setMsgModalOpen(false); setMsgContent('');
  };

  const calculateTotalRevenue = (user: User) => {
      const earned = allRevenues.filter(r => r.userId === user.id).reduce((s, r) => s + r.amountCollected, 0);
      return earned + (user.initialRevenue || 0);
  };

  const openAddUser = () => { setEditingUserId(null); setFormUser({ role: UserRole.EMPLOYEE, initialRevenue: 0, managerId: manager.id }); setUserModalOpen(true); };
  const openEditUser = (user: User) => { setEditingUserId(user.id); setFormUser({ ...user }); setUserModalOpen(true); };

  const handleSubmitUser = async () => {
    if (!formUser.id || !formUser.name || !formUser.password) return alert("Vui lòng điền đủ thông tin");
    const targetRank = ROLE_RANK[formUser.role as UserRole];
    if (targetRank > myRank) return alert("Cấp bậc không hợp lệ.");
    try {
        if (editingUserId) await storageService.updateUser(formUser as User);
        else await storageService.addUser({ ...formUser, managerId: manager.id } as User);
        await refreshData(); setUserModalOpen(false);
    } catch (e: any) { alert(e.message); }
  };

  const handleDeleteUser = async (id: string) => {
      if(confirm("Xóa nhân viên này?")) { try { await storageService.deleteUser(id); await refreshData(); } catch(e: any) { alert(e.message); } }
  };
  const canManageDepts = myRank >= 5;
  const openAddDept = () => { setEditingDeptId(null); setFormDept({}); setDeptModalOpen(true); };

  const handleSubmitDept = async () => {
      if (!formDept.id || !formDept.name) return alert("Thiếu ID hoặc Tên phòng");
      try {
          if (editingDeptId) await storageService.updateDepartment(formDept as Department);
          else await storageService.addDepartment(formDept as Department);
          await refreshData(); setDeptModalOpen(false);
      } catch (e: any) { alert(e.message); }
  };
  const handleDeleteDept = async (id: string) => { if(confirm("Xóa phòng này?")) { try { await storageService.deleteDepartment(id); await refreshData(); } catch(e: any) { alert(e.message); } } };

  if (viewingUser) {
    return (
        <div className="space-y-6 animate-fadeIn">
            <div className="flex items-center gap-6 bg-white p-6 rounded-2xl shadow-lg">
                <Button onClick={() => setViewingUser(null)} variant="secondary" className="rounded-xl border border-gray-200">
                    <ArrowLeft size={18} className="mr-2"/> QUAY LẠI
                </Button>
                <div>
                    <h2 className="text-2xl font-black text-gray-800 uppercase">Hồ sơ: {viewingUser.name}</h2>
                    <div className="flex gap-3 mt-1">
                        <Badge variant="indigo">{ROLE_LABELS[viewingUser.role]}</Badge>
                        <span className="text-sm font-bold text-green-600 tracking-tight">DOANH THU: {new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(calculateTotalRevenue(viewingUser))}</span>
                    </div>
                </div>
            </div>
            <EmployeeDashboard user={viewingUser} isViewOnly={true} />
        </div>
    );
  }

  const allowedRoles = Object.values(UserRole).filter(r => ROLE_RANK[r] <= myRank);

  if (loading) {
      return <div className="min-h-screen flex items-center justify-center"><Loader2 className="animate-spin text-blue-600" size={40}/></div>;
  }

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* (Rest of the JSX remains largely the same, just removing synchronous calls if any) */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <div>
            <h1 className="text-3xl font-black text-gray-900 uppercase tracking-tight leading-none">
                BẢNG ĐIỀU KHIỂN <span className="text-blue-600">QUẢN LÝ</span>
            </h1>
            <p className="text-sm text-gray-400 font-bold uppercase mt-1">Phạm vi: {ROLE_LABELS[manager.role]}</p>
        </div>
        <div className="flex flex-wrap gap-2">
            <Button onClick={() => setMsgModalOpen(true)} className="bg-indigo-600 hover:bg-indigo-700 shadow-indigo-100 shadow-lg rounded-xl">
                <Send size={18} className="mr-2"/> THÔNG BÁO NHÓM
            </Button>
            <div className="flex bg-gray-100 p-1.5 rounded-xl border border-gray-200">
                <button onClick={() => setActiveTab('dashboard')} className={`px-5 py-2 text-xs font-black uppercase rounded-lg transition-all ${activeTab === 'dashboard' ? 'bg-white shadow-md text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}>Tổng quan</button>
                <button onClick={() => setActiveTab('chat')} className={`px-5 py-2 text-xs font-black uppercase rounded-lg transition-all ${activeTab === 'chat' ? 'bg-white shadow-md text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}>Hộp thư</button>
                <button onClick={() => setActiveTab('staff')} className={`px-5 py-2 text-xs font-black uppercase rounded-lg transition-all ${activeTab === 'staff' ? 'bg-white shadow-md text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}>Nhân sự</button>
                {canManageDepts && <button onClick={() => setActiveTab('depts')} className={`px-5 py-2 text-xs font-black uppercase rounded-lg transition-all ${activeTab === 'depts' ? 'bg-white shadow-md text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}>Phòng ban</button>}
            </div>
        </div>
      </div>

      {activeTab === 'dashboard' && (
          <div className="space-y-6">
             <div className="bg-white p-5 rounded-2xl shadow-md border border-gray-100 grid grid-cols-1 md:grid-cols-4 gap-4">
                <div className="col-span-1 border-r border-gray-100 pr-4">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1 block">Lọc theo phạm vi</label>
                    <select className="w-full bg-gray-50 border-none rounded-xl p-2.5 text-sm font-bold focus:ring-2 focus:ring-blue-500" value={dashboardScope} onChange={(e: any) => { setDashboardScope(e.target.value); setDashboardFilterId(''); }}>
                        <option value="ALL">Toàn bộ Team</option>
                        <option value="DEPT">Phòng ban</option>
                        <option value="MANAGER">Nhóm/Quản lý</option>
                        <option value="USER">Cá nhân</option>
                    </select>
                </div>
                <div className="col-span-3 flex items-end gap-3">
                    {dashboardScope === 'DEPT' && <div className="flex-1 animate-fadeIn"><Select label="Chọn phòng" options={departments.map(d => ({value: d.id, label: d.name}))} value={dashboardFilterId} onChange={(e) => setDashboardFilterId(e.target.value)} /></div>}
                    {dashboardScope === 'MANAGER' && <div className="flex-1 animate-fadeIn"><Select label="Chọn Quản lý" options={availableManagers.map(u => ({value: u.id, label: `${u.name} (${ROLE_LABELS[u.role]})`}))} value={dashboardFilterId} onChange={(e) => setDashboardFilterId(e.target.value)} /></div>}
                    {dashboardScope === 'USER' && <div className="flex-1 animate-fadeIn"><Select label="Chọn Nhân viên" options={displayUsers.map(u => ({value: u.id, label: u.name}))} value={dashboardFilterId} onChange={(e) => setDashboardFilterId(e.target.value)} /></div>}
                    {dashboardScope === 'ALL' && <div className="flex-1 text-gray-400 italic text-sm py-2">Đang hiển thị dữ liệu tổng hợp toàn hệ thống bạn quản lý.</div>}
