      {/* Main Tabs */}
      <div className="bg-white rounded-xl shadow-md border border-gray-100 p-1.5 flex gap-2">
          <button onClick={() => setActiveTab('timeline')} className={`flex-1 py-3 rounded-lg font-bold text-sm flex items-center justify-center gap-2 transition-all ${activeTab === 'timeline' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-50'}`}>
              <Clock size={18}/> NHẬT KÝ HOẠT ĐỘNG
          </button>
          <button onClick={() => setActiveTab('projects')} className={`flex-1 py-3 rounded-lg font-bold text-sm flex items-center justify-center gap-2 transition-all ${activeTab === 'projects' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-50'}`}>
              <FileDown size={18}/> DỮ LIỆU DỰ ÁN
          </button>
          <button onClick={() => setActiveTab('chat')} className={`flex-1 py-3 rounded-lg font-bold text-sm flex items-center justify-center gap-2 transition-all ${activeTab === 'chat' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-50'}`}>
              <MessageSquare size={18}/> TRAO ĐỔI
              {unreadCount > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full animate-bounce">{unreadCount}</span>}
          </button>
      </div>

      {activeTab === 'timeline' && (
      <>
        {/* Timeline Content - Same UI, but wrapped in fragment */}
        <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-100 flex flex-col lg:flex-row gap-4 items-center justify-between">
             <div className="flex gap-4 w-full lg:w-auto flex-1">
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={18} />
                    <input type="text" placeholder="Tìm tên, số điện thoại, mã hợp đồng..." className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
                </div>
                <div className="flex items-center gap-2 shrink-0">
                    <input type="date" className="border border-gray-200 rounded-xl px-4 py-2.5 outline-none text-sm bg-gray-50 focus:bg-white transition-colors" value={filterDate} onChange={(e) => setFilterDate(e.target.value)} />
                    {filterDate && <button onClick={() => setFilterDate('')} className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors"><X size={16}/></button>}
                </div>
             </div>
             {!isViewOnly && (
                <div className="flex gap-2 shrink-0">
                    <Button onClick={() => { setEditingId(null); setNewApp({ date: getNowISO(), status: AppointmentStatus.NEW, location: '' }); setDuplicateWarning(null); setShowAppModal(true); }} size="md" className="rounded-xl"><PlusCircle size={18} className="mr-2"/> Hẹn mới</Button>
                    <Button onClick={() => { setEditingId(null); setNewCons({ date: getNowISO(), type: ConsultationType.NEW, supportType: SupportType.SOLO }); setShowConsModal(true); }} size="md" variant="outline" className="rounded-xl border-green-200 text-green-700 hover:bg-green-50"><PlusCircle size={18} className="mr-2"/> Tư vấn</Button>
                    <Button onClick={() => { setEditingId(null); setNewRev({ date: getNowISO(), type: RevenueType.NEW, isApproved: false, customerName: '', phone: '', companyName: '', address: '', region: '' }); setRevSearchPhone(''); setShowRevModal(true); }} size="md" variant="outline" className="rounded-xl border-orange-200 text-orange-700 hover:bg-orange-50"><DollarSign size={18} className="mr-2"/> Thu tiền</Button>
                </div>
             )}
        </div>

        <div className="bg-white rounded-xl shadow-md border border-gray-100 overflow-hidden">
            <div className="divide-y divide-gray-100">
                {timelineData.list.length === 0 ? (
                    <div className="p-12 text-center">
                        <div className="bg-gray-50 inline-flex p-4 rounded-full mb-4"><Search className="text-gray-300" size={32}/></div>
                        <p className="text-gray-400 font-medium">Không tìm thấy dữ liệu hoạt động</p>
                    </div>
                ) : (
                    timelineData.list.map((day) => (
                        <div key={day.date} className="group bg-white">
                            <div onClick={() => toggleDate(day.date)} className={`px-6 py-4 flex items-center gap-4 cursor-pointer transition-colors ${expandedDates[day.date] ? 'bg-blue-50/30' : 'hover:bg-gray-50'}`}>
                                <div className="flex flex-col items-center min-w-[6rem] border-r border-gray-100 pr-6">
                                    <span className="text-sm font-bold text-gray-400 uppercase tracking-tighter">Ngày</span>
                                    <span className="text-xl font-black text-blue-600 leading-none">{day.displayDate.split('/')[0]}</span>
                                    <span className="text-[10px] font-bold text-gray-500">THÁNG {day.displayDate.split('/')[1]}</span>
                                </div>
                                <div className="flex-1 grid grid-cols-2 md:grid-cols-3 gap-3 text-xs">
                                    {day.apps.length > 0 && <span className="font-semibold text-purple-600 bg-purple-50 px-2 py-1 rounded-md inline-flex items-center w-fit"><Calendar size={12} className="mr-1"/>{day.apps.length} Hẹn</span>}
                                    {day.cons.length > 0 && <span className="font-semibold text-green-600 bg-green-50 px-2 py-1 rounded-md inline-flex items-center w-fit"><MessageSquare size={12} className="mr-1"/>{day.cons.length} Tư vấn</span>}
                                    {day.revs.length > 0 && <span className="font-black text-orange-600 bg-orange-50 px-2 py-1 rounded-md inline-flex items-center w-fit col-span-2 md:col-span-1"><DollarSign size={12} className="mr-1"/>{formatCurrency(day.revs.reduce((s, r) => s + r.amountCollected, 0))}</span>}
                                </div>
                                <ChevronDown size={20} className={`text-gray-300 transition-transform duration-300 ${expandedDates[day.date] ? 'rotate-180 text-blue-500' : ''}`}/>
                            </div>
                            {expandedDates[day.date] && (
                                <div className="bg-gray-50/40 px-6 py-6 border-t border-gray-100 pl-4 lg:pl-32 space-y-4 animate-fadeIn">
                                    {day.revs.map(rev => {
                                        const proj = projects.find(p => p.contractCode === rev.contractCode);
                                        return (
                                            <div key={rev.id} className="bg-white p-4 rounded-xl border-l-4 border-l-orange-500 shadow-sm transition-all hover:shadow-md">
                                                <div className="flex justify-between items-start mb-3">
                                                    <div>
                                                        <div className="flex items-center gap-2 mb-1">
                                                            <span className="text-[10px] font-bold text-orange-500 bg-orange-50 px-1.5 py-0.5 rounded uppercase tracking-widest">{formatTimeOnly(rev.date)}</span>
                                                            <Badge variant="warning">{rev.type}</Badge>
                                                        </div>
                                                        <h4 className="font-black text-gray-800 text-lg leading-tight">{proj?.customerName || 'Khách hàng'}</h4>
                                                        <p className="text-xs font-bold text-gray-400 mt-0.5">HỢP ĐỒNG: <span className="text-blue-600 uppercase">{rev.contractCode}</span></p>
                                                    </div>
                                                    <div className="flex items-center gap-2">
                                                        {!isViewOnly && <button onClick={() => handleEditRev(rev)} className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"><Edit size={16}/></button>}
                                                    </div>
                                                </div>
                                                <div className="grid grid-cols-2 gap-4">
                                                    <div className="text-[11px] text-gray-500 flex flex-col gap-1">
                                                        {proj?.phone && <span className="flex items-center font-medium"><Phone size={12} className="mr-1.5 text-gray-400"/>{proj.phone}</span>}
                                                        {proj?.companyName && <span className="flex items-center font-medium"><Building2 size={12} className="mr-1.5 text-gray-400"/>{proj.companyName}</span>}
                                                    </div>
                                                    <div className="text-right">
                                                        <p className="text-[10px] font-bold text-gray-400 uppercase mb-0.5">Số tiền đã thu</p>
                                                        <p className="text-xl font-black text-orange-600">{formatCurrency(rev.amountCollected)}</p>
                                                    </div>
                                                </div>
                                            </div>
                                        );
                                    })}

                                    {day.apps.map(app => (
                                        <div key={app.id} className="bg-white p-4 rounded-xl border-l-4 border-l-purple-500 shadow-sm transition-all hover:shadow-md">
                                            <div className="flex justify-between items-start mb-3">
                                                <div>
                                                    <div className="flex items-center gap-2 mb-1">
                                                        <span className="text-[10px] font-bold text-purple-500 bg-purple-50 px-1.5 py-0.5 rounded uppercase tracking-widest">{formatTimeOnly(app.date)}</span>
                                                        <Badge variant={getStatusVariant(app.status)}>{app.status}</Badge>
                                                    </div>
                                                    <h4 className="font-black text-gray-800 text-lg leading-tight">{app.customerName}</h4>
                                                    {getDuplicateTag(app.phone) && <Badge variant="error" className="mt-1">TRÙNG LẶP</Badge>}
                                                </div>
                                                <div className="flex items-center gap-2">
                                                    {!isViewOnly && <button onClick={() => handleEditApp(app)} className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"><Edit size={16}/></button>}
                                                </div>
                                            </div>
                                            <div className="text-[11px] text-gray-500 flex flex-wrap gap-x-5 gap-y-2 border-t pt-3 border-gray-50">
                                                <span className="flex items-center font-medium"><Phone size={12} className="mr-1.5 text-blue-500"/>{app.phone}</span>
                                                <span className="flex items-center font-medium"><Building2 size={12} className="mr-1.5 text-indigo-500"/>{app.companyName}</span>
                                                <span className="flex items-center font-medium"><MapPin size={12} className="mr-1.5 text-red-500"/>{app.location}</span>
                                            </div>
                                        </div>
                                    ))}

                                    {day.cons.map(con => (
                                        <div key={con.id} className="bg-white p-4 rounded-xl border-l-4 border-l-green-500 shadow-sm transition-all hover:shadow-md">
                                            <div className="flex justify-between items-start mb-3">
                                                <div>
                                                    <div className="flex items-center gap-2 mb-1">
                                                        <span className="text-[10px] font-bold text-green-500 bg-green-50 px-1.5 py-0.5 rounded uppercase tracking-widest">{formatTimeOnly(con.date)}</span>
                                                        <Badge variant="indigo">{con.supportType}</Badge>
                                                        <Badge variant="success">{con.type}</Badge>
                                                    </div>
                                                    <h4 className="font-black text-gray-800 text-lg leading-tight">{con.customerName}</h4>
                                                </div>
                                                <div className="flex items-center gap-2">
                                                    {!isViewOnly && <button onClick={() => handleEditCons(con)} className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"><Edit size={16}/></button>}
                                                </div>
                                            </div>
                                            {con.supportPersonName && <div className="text-[10px] font-bold text-indigo-600 mb-2 uppercase flex items-center"><UserIcon size={12} className="mr-1"/> Hỗ trợ: {con.supportPersonName}</div>}
                                            <div className="text-[11px] text-gray-500 grid grid-cols-2 gap-2 border-t pt-3 border-gray-50">
                                                <span className="flex items-center font-medium"><Phone size={12} className="mr-1.5 text-blue-500"/>{con.phone}</span>
                                                {con.source && <span className="flex items-center font-medium overflow-hidden text-ellipsis whitespace-nowrap"><Search size={12} className="mr-1.5 text-gray-400"/>{con.source}</span>}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    ))
                )}
            </div>
        </div>
      </>
      )}

      {/* Projects and Chat tabs logic is same as before, just ensured update/add calls are awaited */}
      {activeTab === 'projects' && (
        <div className="space-y-4">
             {/* (Same Project Table Code) */}
            <div className="flex flex-col md:flex-row justify-between items-center bg-white p-4 rounded-xl shadow-sm border border-gray-100 gap-4">
                <div>
                    <h3 className="text-lg font-black text-gray-800 uppercase tracking-tight flex items-center gap-2"><Layers size={20} className="text-blue-500"/> Chi Tiết Hợp Đồng & Dự Án</h3>
                    <p className="text-xs text-gray-500 font-medium mt-1">Quản lý {projectTableData.length} dự án đang hoạt động</p>
                </div>
                <Button onClick={handleExportExcel} variant="outline" className="rounded-xl border-green-200 text-green-700 hover:bg-green-50 shadow-sm w-full md:w-auto">
                    <Download size={18} className="mr-2"/> XUẤT FILE EXCEL
                </Button>
            </div>

            <div className="bg-white rounded-xl shadow-lg border border-gray-200 overflow-hidden">
                <table className="w-full text-sm text-left border-collapse">
                    <thead className="bg-gray-50 text-gray-500 uppercase font-bold text-xs sticky top-0 z-10 shadow-sm">
                        <tr>
                            <th className="px-6 py-4">Khách Hàng</th>
                            <th className="px-6 py-4">Dự Án & Hợp Đồng</th>
                            <th className="px-6 py-4 text-center">Trạng Thái</th>
                            <th className="px-6 py-4 text-right">Tài Chính</th>
                            <th className="px-6 py-4 text-center w-20">Chi Tiết</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {projectTableData.map((row) => (
                            <React.Fragment key={row.contractCode}>
                                <tr className={`group hover:bg-blue-50/40 transition-all duration-200 ${expandedProjects[row.contractCode] ? 'bg-blue-50/50' : ''}`}>
                                    <td className="px-6 py-4 align-top">
