                                  <div className="text-sm leading-relaxed whitespace-pre-wrap font-medium">{msg.content}</div>
                                  <div className={`text-[9px] mt-2 font-bold uppercase tracking-tighter ${isMe ? 'text-blue-200' : 'text-gray-400'}`}>{formatDateTimeVN(msg.timestamp)}</div>
                              </div>
