                    <Input label="Tên Khách Hàng" placeholder="VD: Anh Minh" value={newApp.customerName || ''} onChange={e => setNewApp({...newApp, customerName: e.target.value})} />
                    <Input label="Công Ty" placeholder="Tên doanh nghiệp..." value={newApp.companyName || ''} onChange={e => setNewApp({...newApp, companyName: e.target.value})} />
