      <Modal isOpen={isDeptModalOpen} onClose={() => setDeptModalOpen(false)} title={editingDeptId ? "SỬA ĐƠN VỊ" : "THÀNH LẬP ĐƠN VỊ MỚI"}>
          <div className="space-y-4 p-1">
              <Input label="Mã Đơn vị" value={formDept.id || ''} onChange={e => setFormDept({...formDept, id: e.target.value.toUpperCase()})} disabled={!!editingDeptId} placeholder="VD: KV01, GRP02..." />
              <Input label="Tên Đơn vị" value={formDept.name || ''} onChange={e => setFormDept({...formDept, name: e.target.value})} placeholder="Tên hiển thị..." />

              <Select 
                  label="Cấp bậc" 
                  value={formDept.level} 
                  onChange={e => {
                      const newLevel = e.target.value as DepartmentLevel;
                      setFormDept({...formDept, level: newLevel, parentId: ''}); // Reset parent when level changes
                  }} 
                  options={Object.values(DepartmentLevel).map(v => ({value: v, label: v}))} 
              />

              {formDept.level && formDept.level !== DepartmentLevel.HQ && (
                  <Select 
                      label={`Trực thuộc đơn vị (${getAvailableParents(formDept.level).length > 0 ? 'Chọn bên dưới' : 'Chưa có cấp trên phù hợp'})`}
                      value={formDept.parentId || ''} 
                      onChange={e => setFormDept({...formDept, parentId: e.target.value})} 
                      options={[
                          {value: '', label: '-- Chọn đơn vị cấp trên --'},
                          ...getAvailableParents(formDept.level).map(d => ({value: d.id, label: d.name}))
                      ]} 
                  />
              )}

              <Input label="Tên Người đứng đầu" value={formDept.managerName || ''} onChange={e => setFormDept({...formDept, managerName: e.target.value})} placeholder="Nhập tên quản lý..." />

              <div className="flex justify-end gap-3 pt-6 border-t mt-4">
                 <Button variant="ghost" onClick={() => setDeptModalOpen(false)}>HỦY</Button>
                 <Button onClick={handleSubmitDept} className="px-8 font-black uppercase">LƯU CẤU TRÚC</Button>
            </div>
          </div>
      </Modal>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { storageService } from '../services/storageService';
import { User, Department, Appointment, Revenue, Message, UserRole, ROLE_RANK, ROLE_LABELS, DepartmentLevel } from '../types';
import { Button, Input, Modal, Select, Card, Badge } from '../components/ui';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { Users, TrendingUp, Calendar, Edit, Trash2, Eye, ArrowLeft, Send, MessageSquare, Search, LayoutGrid, Loader2, GitMerge, ChevronRight, CornerDownRight } from 'lucide-react';
import { EmployeeDashboard } from './EmployeeDashboard';

interface AdminDashboardProps {
    currentUser: User; 
}

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser }) => {
  const manager = currentUser;
  const [loading, setLoading] = useState(true);

  const [activeTab, setActiveTab] = useState<'dashboard' | 'staff' | 'depts' | 'chat'>('dashboard');
  const [departments, setDepartments] = useState<Department[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [allRevenues, setAllRevenues] = useState<Revenue[]>([]);
  const [allAppointments, setAllAppointments] = useState<Appointment[]>([]);

  const [dashboardScope, setDashboardScope] = useState<'ALL' | 'DEPT' | 'MANAGER' | 'USER'>('ALL');
  const [dashboardFilterId, setDashboardFilterId] = useState('');

  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [selectedChatUser, setSelectedChatUser] = useState<string | null>(null);
  const [adminChatInput, setAdminChatInput] = useState('');
  const [chatSearchTerm, setChatSearchTerm] = useState('');
  const [chatFilterRole, setChatFilterRole] = useState<string>('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const [filterDept, setFilterDept] = useState('');
  const [isMsgModalOpen, setMsgModalOpen] = useState(false);
  const [msgContent, setMsgContent] = useState('');
  const [msgTargetType, setMsgTargetType] = useState<'ALL' | 'DEPT' | 'USER'>('ALL');
  const [msgTargetId, setMsgTargetId] = useState('');

  const [isUserModalOpen, setUserModalOpen] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [formUser, setFormUser] = useState<Partial<User>>({});

  const [isDeptModalOpen, setDeptModalOpen] = useState(false);
  const [editingDeptId, setEditingDeptId] = useState<string | null>(null);
  const [formDept, setFormDept] = useState<Partial<Department>>({ level: DepartmentLevel.DEPARTMENT });

  const [viewingUser, setViewingUser] = useState<User | null>(null);

  const myRank = ROLE_RANK[manager.role];

  const refreshData = async () => {
      setLoading(true);
      try {
          const [u, d, r, a, m] = await Promise.all([
              storageService.getUsers(),
              storageService.getDepartments(),
              storageService.getRevenues(),
              storageService.getAppointments(),
              storageService.getMessages()
          ]);
          setAllUsers(u);
          setDepartments(d);
          setAllRevenues(r);
          setAllAppointments(a);
          setAllMessages(m);
      } catch (error) {
          console.error("Failed to load data", error);
      } finally {
          setLoading(false);
      }
  };

  const silentRefreshMsg = async () => {
      const m = await storageService.getMessages();
      setAllMessages(m);
  };

  useEffect(() => {
     refreshData();
     const interval = setInterval(() => {
         silentRefreshMsg();
     }, 10000); // Poll every 10s for messages
     return () => clearInterval(interval);
  }, []);

  useEffect(() => {
     if(activeTab === 'chat' && selectedChatUser) {
         chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
     }
  }, [allMessages, selectedChatUser, activeTab]);

  // Logic to determine valid parents based on the selected level for a new department
  const getAvailableParents = (currentLevel?: DepartmentLevel) => {
     if (!currentLevel || currentLevel === DepartmentLevel.HQ) return [];

     let targetParentLevel: DepartmentLevel | null = null;
     switch (currentLevel) {
         case DepartmentLevel.REGION: targetParentLevel = DepartmentLevel.HQ; break;
         case DepartmentLevel.GROUP: targetParentLevel = DepartmentLevel.REGION; break;
         case DepartmentLevel.DEPARTMENT: targetParentLevel = DepartmentLevel.GROUP; break;
         case DepartmentLevel.TEAM: targetParentLevel = DepartmentLevel.DEPARTMENT; break;
     }

     if (!targetParentLevel) return [];
     return departments.filter(d => d.level === targetParentLevel);
  };

  const getSubordinates = (managerId: string) => {
      const result: User[] = [];
      const findDirectReports = (id: string) => {
          const directReports = allUsers.filter(u => u.managerId === id);
          for (const report of directReports) {
              result.push(report);
              findDirectReports(report.id);
          }
      };
      findDirectReports(managerId);
      return result;
  };

  const mySubordinates = useMemo(() => {
      const subs = getSubordinates(manager.id);
      return [manager, ...subs];
  }, [allUsers, manager.id]);

  const displayUsers = useMemo(() => mySubordinates.filter(u => u.id !== manager.id), [mySubordinates, manager.id]);
  const availableManagers = useMemo(() => mySubordinates.filter(u => ROLE_RANK[u.role] > 1), [mySubordinates]);

  // --- RECURSIVE LOGIC FOR PERSONNEL COUNT ---
  const getCumulativeHeadcount = (deptId: string): number => {
      // 1. Find all descendant department IDs (children, grandchildren, etc.)
      const descendantIds: string[] = [];

      const findChildren = (parentId: string) => {
          const children = departments.filter(d => d.parentId === parentId);
          children.forEach(child => {
              descendantIds.push(child.id);
              findChildren(child.id); // Recursion
          });
      };

      findChildren(deptId);

      // 2. Count users belonging to (current Dept + any Descendant Depts)
      const targetDeptIds = [deptId, ...descendantIds];
      return allUsers.filter(u => u.departmentId && targetDeptIds.includes(u.departmentId)).length;
  };

  const filteredDashboardData = useMemo(() => {
      let targetUsers: User[] = [];
      if (dashboardScope === 'ALL') {
          targetUsers = mySubordinates;
      } else if (dashboardScope === 'DEPT' && dashboardFilterId) {
          // For dashboard filter, we also want cumulative users
          const descendantIds: string[] = [];
          const findChildren = (pid: string) => {
             departments.filter(d => d.parentId === pid).forEach(c => {
                 descendantIds.push(c.id);
                 findChildren(c.id);
             });
          };
          findChildren(dashboardFilterId);
          const targetDeptIds = [dashboardFilterId, ...descendantIds];
          targetUsers = mySubordinates.filter(u => u.departmentId && targetDeptIds.includes(u.departmentId));

      } else if (dashboardScope === 'MANAGER' && dashboardFilterId) {
          const subTree = getSubordinates(dashboardFilterId);
          const mgr = mySubordinates.find(u => u.id === dashboardFilterId);
          targetUsers = mgr ? [mgr, ...subTree] : subTree;
      } else if (dashboardScope === 'USER' && dashboardFilterId) {
          const u = mySubordinates.find(u => u.id === dashboardFilterId);
          targetUsers = u ? [u] : [];
      } else {
          targetUsers = mySubordinates;
      }
      const targetIds = targetUsers.map(u => u.id);
      const revs = allRevenues.filter(r => targetIds.includes(r.userId));
      const apps = allAppointments.filter(a => targetIds.includes(a.userId));
      return { users: targetUsers, revenues: revs, appointments: apps };
  }, [dashboardScope, dashboardFilterId, mySubordinates, allRevenues, allAppointments, departments]);

  const analysisData = useMemo(() => {
      const { revenues } = filteredDashboardData;
      const monthlyData: Record<string, number> = {};
      revenues.forEach(r => {
          const month = r.date.substring(0, 7);
          monthlyData[month] = (monthlyData[month] || 0) + r.amountCollected;
      });
      const chartData = Object.keys(monthlyData).sort().map(k => ({ name: k, revenue: monthlyData[k] }));
      let conclusion = "Chưa có đủ dữ liệu để đánh giá.";
      if (chartData.length >= 2) {
          const last = chartData[chartData.length - 1].revenue;
          const prev = chartData[chartData.length - 2].revenue;
          const diff = last - prev;
          const percent = prev > 0 ? ((diff / prev) * 100).toFixed(1) : 100;
          if (diff > 0) conclusion = `Tăng trưởng tích cực: Tháng ${chartData[chartData.length-1].name} tăng ${percent}% so với tháng trước.`;
          else if (diff < 0) conclusion = `Cảnh báo sụt giảm: Tháng ${chartData[chartData.length-1].name} giảm ${Math.abs(Number(percent))}% so với tháng trước.`;
          else conclusion = "Doanh thu ổn định, không có biến động.";
      }
      return { chartData, conclusion, total: revenues.reduce((s,r) => s + r.amountCollected, 0) };
  }, [filteredDashboardData]);

  const chatUsers = useMemo(() => {
      let filtered = displayUsers;
      if (chatSearchTerm) {
          const term = chatSearchTerm.toLowerCase();
          filtered = filtered.filter(u => u.name.toLowerCase().includes(term) || u.id.toLowerCase().includes(term) || (u.phone && u.phone.includes(term)));
      }
      if (chatFilterRole) filtered = filtered.filter(u => u.role === chatFilterRole);
      return filtered;
  }, [displayUsers, chatSearchTerm, chatFilterRole]);

  const currentConversation = useMemo(() => {
      if (!selectedChatUser) return [];
      return allMessages.filter(m => 
          (m.senderId === manager.id && m.receiverId === selectedChatUser) ||
          (m.senderId === selectedChatUser && m.receiverId === manager.id)
      ).sort((a,b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
  }, [allMessages, selectedChatUser, manager.id]);

  const handleAdminReply = async () => {
      if (!selectedChatUser || !adminChatInput.trim()) return;
      await storageService.sendMessage({ id: `MSG${Date.now()}`, senderId: manager.id, senderName: manager.name, receiverId: selectedChatUser, content: adminChatInput, timestamp: new Date().toISOString(), isRead: false });
      setAdminChatInput(''); 
      silentRefreshMsg();
  };

  const handleSendMessage = async () => {
      if (!msgContent) return;
      let receiver: string | string[] = 'ALL';
      if (msgTargetType === 'DEPT') receiver = displayUsers.filter(u => u.departmentId === msgTargetId).map(u => u.id);
      else if (msgTargetType === 'USER') receiver = msgTargetId;
      else receiver = displayUsers.map(u => u.id);
      await storageService.sendMessage({ id: `MSG${Date.now()}`, senderId: manager.id, senderName: manager.name, receiverId: receiver, content: msgContent, timestamp: new Date().toISOString(), isRead: false });
      alert('Đã gửi thông báo thành công!'); setMsgModalOpen(false); setMsgContent('');
  };

  const calculateTotalRevenue = (user: User) => {
      const earned = allRevenues.filter(r => r.userId === user.id).reduce((s, r) => s + r.amountCollected, 0);
      return earned + (user.initialRevenue || 0);
  };

  const openAddUser = () => { setEditingUserId(null); setFormUser({ role: UserRole.EMPLOYEE, initialRevenue: 0, managerId: manager.id }); setUserModalOpen(true); };
  const openEditUser = (user: User) => { setEditingUserId(user.id); setFormUser({ ...user }); setUserModalOpen(true); };

  const handleSubmitUser = async () => {
    if (!formUser.id || !formUser.name || !formUser.password) return alert("Vui lòng điền đủ thông tin");
    const targetRank = ROLE_RANK[formUser.role as UserRole];
    if (targetRank > myRank) return alert("Cấp bậc không hợp lệ.");
    try {
        if (editingUserId) await storageService.updateUser(formUser as User);
        else await storageService.addUser({ ...formUser, managerId: manager.id } as User);
        await refreshData(); setUserModalOpen(false);
    } catch (e: any) { alert(e.message); }
  };

  const handleDeleteUser = async (id: string) => {
      if(confirm("Xóa nhân viên này?")) { try { await storageService.deleteUser(id); await refreshData(); } catch(e: any) { alert(e.message); } }
  };
  const canManageDepts = myRank >= 5;
  const openAddDept = () => { setEditingDeptId(null); setFormDept({ level: DepartmentLevel.DEPARTMENT }); setDeptModalOpen(true); };

  const handleSubmitDept = async () => {
      if (!formDept.id || !formDept.name) return alert("Thiếu ID hoặc Tên phòng");
      if (!formDept.level) return alert("Chưa chọn cấp bậc");
      if (formDept.level !== DepartmentLevel.HQ && !formDept.parentId) return alert("Cần chọn đơn vị cấp trên trực thuộc");

      try {
          if (editingDeptId) await storageService.updateDepartment(formDept as Department);
          else await storageService.addDepartment(formDept as Department);
          await refreshData(); setDeptModalOpen(false);
      } catch (e: any) { alert(e.message); }
  };
  const handleDeleteDept = async (id: string) => { if(confirm("Xóa phòng này?")) { try { await storageService.deleteDepartment(id); await refreshData(); } catch(e: any) { alert(e.message); } } };

  // --- Recursive Tree Renderer for Org Chart ---
  const renderDepartmentTree = (parentId: string | null = null, depth: number = 0) => {
     // Find departments that belong to this parent. 
     // Handle root case: parentId is null OR departments with level HQ
     let children: Department[] = [];
     if (parentId === null) {
         children = departments.filter(d => !d.parentId || d.level === DepartmentLevel.HQ);
     } else {
         children = departments.filter(d => d.parentId === parentId);
     }

     if (children.length === 0) return null;

     return (
        <div className={`flex flex-col gap-4 ${depth > 0 ? 'ml-8 pl-6 border-l-2 border-dashed border-gray-300 relative' : ''}`}>
            {children.map(dept => {
                const cumulativeCount = getCumulativeHeadcount(dept.id);
                const directCount = allUsers.filter(u => u.departmentId === dept.id).length;

                let levelColor = 'bg-gray-100 text-gray-700 border-gray-200';
                if (dept.level === DepartmentLevel.HQ) levelColor = 'bg-red-50 text-red-700 border-red-200';
                else if (dept.level === DepartmentLevel.REGION) levelColor = 'bg-purple-50 text-purple-700 border-purple-200';
                else if (dept.level === DepartmentLevel.GROUP) levelColor = 'bg-indigo-50 text-indigo-700 border-indigo-200';
                else if (dept.level === DepartmentLevel.DEPARTMENT) levelColor = 'bg-blue-50 text-blue-700 border-blue-200';

                return (
                    <div key={dept.id} className="relative">
                        {/* Connecting Line for tree nodes */}
                        {depth > 0 && <div className="absolute top-6 -left-6 w-6 h-px border-b-2 border-dashed border-gray-300"></div>}

                        <div className="bg-white border border-gray-200 rounded-xl p-4 shadow-sm hover:shadow-md transition-all group relative overflow-hidden">
                             {/* Level Badge */}
                             <div className={`absolute top-0 right-0 px-3 py-1 rounded-bl-lg text-[10px] font-bold uppercase border-l border-b ${levelColor}`}>
                                 {dept.level}
                             </div>

                             <div className="flex items-start gap-3">
                                 <div className={`w-10 h-10 rounded-lg flex items-center justify-center font-bold text-lg uppercase shrink-0 ${levelColor}`}>
                                     {dept.name.substring(0,1)}
                                 </div>
                                 <div className="flex-1">
                                     <h4 className="font-bold text-gray-900 leading-tight uppercase text-sm pr-16">{dept.name}</h4>
                                     <div className="text-[11px] text-gray-500 mt-1 font-medium flex items-center gap-1">
                                         <Users size={12}/> Quản lý: <span className="text-gray-800 font-bold">{dept.managerName || 'Trống'}</span>
                                     </div>

                                     <div className="mt-3 flex items-center gap-4 text-xs">
                                         <div className="flex flex-col">
                                            <span className="text-[10px] text-gray-400 font-bold uppercase">Tổng nhân sự</span>
                                            <span className="font-black text-blue-600 text-lg">{cumulativeCount}</span>
                                         </div>
                                         <div className="h-6 w-px bg-gray-200"></div>
                                         <div className="flex flex-col">
                                            <span className="text-[10px] text-gray-400 font-bold uppercase">Trực thuộc</span>
                                            <span className="font-bold text-gray-600">{directCount}</span>
                                         </div>
                                     </div>
                                 </div>
                                 <div className="flex flex-col gap-1 opacity-10 group-hover:opacity-100 transition-opacity absolute bottom-3 right-3">
                                     <button onClick={() => { setEditingDeptId(dept.id); setFormDept(dept); setDeptModalOpen(true); }} className="p-1.5 bg-blue-50 text-blue-600 rounded-md hover:bg-blue-100"><Edit size={14}/></button>
                                     {dept.level !== DepartmentLevel.HQ && <button onClick={() => handleDeleteDept(dept.id)} className="p-1.5 bg-red-50 text-red-600 rounded-md hover:bg-red-100"><Trash2 size={14}/></button>}
                                 </div>
                             </div>
                        </div>

                        {/* Render Children Recursively */}
                        {renderDepartmentTree(dept.id, depth + 1)}
                    </div>
                );
            })}
        </div>
     );
  };

  if (viewingUser) {
    return (
        <div className="space-y-6 animate-fadeIn">
            <div className="flex items-center gap-6 bg-white p-6 rounded-2xl shadow-lg">
                <Button onClick={() => setViewingUser(null)} variant="secondary" className="rounded-xl border border-gray-200">
                    <ArrowLeft size={18} className="mr-2"/> QUAY LẠI
                </Button>
                <div>
                    <h2 className="text-2xl font-black text-gray-800 uppercase">Hồ sơ: {viewingUser.name}</h2>
                    <div className="flex gap-3 mt-1">
                        <Badge variant="indigo">{ROLE_LABELS[viewingUser.role]}</Badge>
                        <span className="text-sm font-bold text-green-600 tracking-tight">DOANH THU: {new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(calculateTotalRevenue(viewingUser))}</span>
                    </div>
                </div>
            </div>
            <EmployeeDashboard user={viewingUser} isViewOnly={true} />
        </div>
    );
  }

  const allowedRoles = Object.values(UserRole).filter(r => ROLE_RANK[r] <= myRank);

  if (loading) {
      return <div className="min-h-screen flex items-center justify-center"><Loader2 className="animate-spin text-blue-600" size={40}/></div>;
  }

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* (Rest of the JSX remains largely the same, just removing synchronous calls if any) */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <div>
            <h1 className="text-3xl font-black text-gray-900 uppercase tracking-tight leading-none">
                BẢNG ĐIỀU KHIỂN <span className="text-blue-600">QUẢN LÝ</span>
            </h1>
            <p className="text-sm text-gray-400 font-bold uppercase mt-1">Phạm vi: {ROLE_LABELS[manager.role]}</p>
        </div>
        <div className="flex flex-wrap gap-2">
            <Button onClick={() => setMsgModalOpen(true)} className="bg-indigo-600 hover:bg-indigo-700 shadow-indigo-100 shadow-lg rounded-xl">
                <Send size={18} className="mr-2"/> THÔNG BÁO NHÓM
            </Button>
            <div className="flex bg-gray-100 p-1.5 rounded-xl border border-gray-200">
                <button onClick={() => setActiveTab('dashboard')} className={`px-5 py-2 text-xs font-black uppercase rounded-lg transition-all ${activeTab === 'dashboard' ? 'bg-white shadow-md text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}>Tổng quan</button>
                <button onClick={() => setActiveTab('chat')} className={`px-5 py-2 text-xs font-black uppercase rounded-lg transition-all ${activeTab === 'chat' ? 'bg-white shadow-md text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}>Hộp thư</button>
                <button onClick={() => setActiveTab('staff')} className={`px-5 py-2 text-xs font-black uppercase rounded-lg transition-all ${activeTab === 'staff' ? 'bg-white shadow-md text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}>Nhân sự</button>
                {canManageDepts && <button onClick={() => setActiveTab('depts')} className={`px-5 py-2 text-xs font-black uppercase rounded-lg transition-all ${activeTab === 'depts' ? 'bg-white shadow-md text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}>Phòng ban</button>}
            </div>
        </div>
      </div>

      {activeTab === 'dashboard' && (
          <div className="space-y-6">
             <div className="bg-white p-5 rounded-2xl shadow-md border border-gray-100 grid grid-cols-1 md:grid-cols-4 gap-4">
                <div className="col-span-1 border-r border-gray-100 pr-4">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1 block">Lọc theo phạm vi</label>
                    <select className="w-full bg-gray-50 border-none rounded-xl p-2.5 text-sm font-bold focus:ring-2 focus:ring-blue-500" value={dashboardScope} onChange={(e: any) => { setDashboardScope(e.target.value); setDashboardFilterId(''); }}>
                        <option value="ALL">Toàn bộ Team</option>
                        <option value="DEPT">Phòng ban</option>
                        <option value="MANAGER">Nhóm/Quản lý</option>
                        <option value="USER">Cá nhân</option>
                    </select>
                </div>
                <div className="col-span-3 flex items-end gap-3">
                    {dashboardScope === 'DEPT' && <div className="flex-1 animate-fadeIn"><Select label="Chọn phòng" options={departments.map(d => ({value: d.id, label: d.name}))} value={dashboardFilterId} onChange={(e) => setDashboardFilterId(e.target.value)} /></div>}
                    {dashboardScope === 'MANAGER' && <div className="flex-1 animate-fadeIn"><Select label="Chọn Quản lý" options={availableManagers.map(u => ({value: u.id, label: `${u.name} (${ROLE_LABELS[u.role]})`}))} value={dashboardFilterId} onChange={(e) => setDashboardFilterId(e.target.value)} /></div>}
                    {dashboardScope === 'USER' && <div className="flex-1 animate-fadeIn"><Select label="Chọn Nhân viên" options={displayUsers.map(u => ({value: u.id, label: u.name}))} value={dashboardFilterId} onChange={(e) => setDashboardFilterId(e.target.value)} /></div>}
                    {dashboardScope === 'ALL' && <div className="flex-1 text-gray-400 italic text-sm py-2">Đang hiển thị dữ liệu tổng hợp toàn hệ thống bạn quản lý.</div>}
                </div>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <Card className="border-t-4 border-t-blue-500">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Tổng nhân sự</p>
                            <h3 className="text-4xl font-black text-gray-800">{filteredDashboardData.users.length}</h3>
                        </div>
                        <div className="bg-blue-50 p-3 rounded-2xl text-blue-600"><Users size={28}/></div>
                    </div>
                </Card>
                <Card className="border-t-4 border-t-green-500">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Tổng doanh thu</p>
                            <h3 className="text-2xl font-black text-green-600">{new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(analysisData.total)}</h3>
                        </div>
                        <div className="bg-green-50 p-3 rounded-2xl text-green-600"><TrendingUp size={28}/></div>
                    </div>
                </Card>
                <Card className="border-t-4 border-t-purple-500">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Cuộc hẹn đã lên</p>
                            <h3 className="text-4xl font-black text-gray-800">{filteredDashboardData.appointments.length}</h3>
                        </div>
                        <div className="bg-purple-50 p-3 rounded-2xl text-purple-600"><Calendar size={28}/></div>
                    </div>
                </Card>
             </div>

             <Card title="Phân tích tăng trưởng & Xu hướng">
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    <div className="lg:col-span-2 bg-gray-50/50 p-6 rounded-2xl border border-gray-100">
                        <div className="h-72">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={analysisData.chartData}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                                    <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700}} />
                                    <YAxis axisLine={false} tickLine={false} tickFormatter={(v) => `${v/1000000}M`} tick={{fontSize: 10}} />
                                    <Tooltip cursor={{fill: '#f1f5f9'}} formatter={(v: any) => [new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(v), 'Doanh thu']} />
                                    <Bar dataKey="revenue" radius={[6, 6, 0, 0]}>
                                        {analysisData.chartData.map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={index === analysisData.chartData.length - 1 ? '#3b82f6' : '#94a3b8'} />
                                        ))}
                                    </Bar>
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                    </div>
                    <div className="flex flex-col justify-center">
                        <div className="bg-blue-900 text-white p-6 rounded-2xl shadow-xl space-y-4">
                                <div className="flex items-center gap-2"><LayoutGrid size={18} className="text-blue-400"/><span className="text-xs font-black uppercase tracking-widest">Báo cáo tự động</span></div>
                                <p className="text-sm font-medium italic opacity-90 leading-relaxed text-blue-50">
                                    "{analysisData.conclusion}"
                                </p>
                                <div className="pt-4 border-t border-blue-800 flex items-center justify-between">
                                    <span className="text-[10px] font-bold uppercase tracking-widest text-blue-300">Độ tin cậy</span>
                                    <span className="text-xs font-black text-green-400">98% AI Analyzed</span>
                                </div>
                        </div>
                    </div>
                </div>
             </Card>
          </div>
      )}

      {/* Rest of the Tabs (Chat, Staff, Depts) follow the same pattern - just ensure handlers use async/await */}
      {activeTab === 'chat' && (
          <div className="bg-white rounded-2xl shadow-xl border border-gray-100 h-[700px] flex overflow-hidden">
              <div className="w-1/3 border-r border-gray-100 bg-gray-50 flex flex-col">
                  <div className="p-4 font-black text-gray-800 border-b uppercase text-sm tracking-tight flex items-center gap-2"><MessageSquare size={16} className="text-blue-500"/> Danh sách tin nhắn</div>
                  <div className="p-4 border-b bg-white space-y-3">
                      <div className="relative">
                          <input className="w-full border-gray-200 rounded-xl pl-10 pr-4 py-2 text-sm focus:ring-2 focus:ring-blue-500 transition-all" placeholder="Tìm nhân viên..." value={chatSearchTerm} onChange={e => setChatSearchTerm(e.target.value)} />
                          <Search size={16} className="absolute left-3.5 top-2.5 text-gray-400" />
                      </div>
                      <select className="w-full border-gray-200 rounded-xl p-2 text-xs font-bold text-gray-600 bg-gray-50" value={chatFilterRole} onChange={e => setChatFilterRole(e.target.value)}>
                          <option value="">-- Tất cả chức vụ --</option>
                          {Object.values(UserRole).map(r => (<option key={r} value={r}>{ROLE_LABELS[r]}</option>))}
                      </select>
                  </div>
                  <div className="flex-1 overflow-y-auto">
                      {chatUsers.length === 0 && <div className="p-10 text-center"><p className="text-xs font-bold text-gray-400 uppercase">Trống</p></div>}
                      {chatUsers.map(u => (
                          <div key={u.id} onClick={() => setSelectedChatUser(u.id)} className={`p-4 cursor-pointer border-b border-gray-100 hover:bg-white transition-all flex items-center gap-3 ${selectedChatUser === u.id ? 'bg-white border-l-4 border-l-blue-600' : ''}`}>
                              <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold text-xs">{u.name.substring(0, 1)}</div>
                              <div className="flex-1 overflow-hidden">
                                  <div className="font-black text-sm text-gray-800 truncate uppercase">{u.name}</div>
                                  <div className="text-[10px] text-gray-400 font-bold uppercase">{ROLE_LABELS[u.role]}</div>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>
              <div className="w-2/3 flex flex-col bg-[#f8fafc]">
                  {selectedChatUser ? (
                      <>
                        <div className="p-4 border-b flex justify-between items-center bg-white shadow-sm z-10">
                            <span className="font-black text-gray-800 uppercase tracking-tight">Hội thoại: {allUsers.find(u => u.id === selectedChatUser)?.name}</span>
                            <div className="w-3 h-3 rounded-full bg-green-500 animate-pulse"></div>
                        </div>
                        <div className="flex-1 overflow-y-auto p-6 space-y-6">
                            {currentConversation.map(msg => {
                                const isMe = msg.senderId === manager.id;
                                return (
                                    <div key={msg.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                                        <div className={`max-w-[80%] rounded-2xl p-4 shadow-sm ${isMe ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'}`}>
                                            <div className="text-sm font-medium leading-relaxed whitespace-pre-wrap">{msg.content}</div>
                                            <div className={`text-[9px] mt-2 font-black uppercase tracking-widest ${isMe ? 'text-blue-200 text-right' : 'text-gray-400'}`}>{new Date(msg.timestamp).toLocaleString('vi-VN')}</div>
                                        </div>
                                    </div>
                                );
                            })}
                            <div ref={chatEndRef}></div>
                        </div>
                        <div className="p-4 bg-white border-t border-gray-100">
                             <div className="flex gap-2 bg-gray-50 p-2 rounded-2xl border border-gray-100">
                                  <input className="flex-1 bg-transparent border-none px-4 py-2 outline-none text-sm font-medium" placeholder="Nhập tin nhắn trả lời..." value={adminChatInput} onChange={e => setAdminChatInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleAdminReply()} />
                                  <button onClick={handleAdminReply} className="bg-blue-600 text-white p-3 rounded-xl hover:bg-blue-700 active:scale-95 transition-all shadow-lg"><Send size={18}/></button>
                             </div>
                        </div>
                      </>
                  ) : (
                      <div className="flex-1 flex flex-col items-center justify-center text-gray-300">
                          <MessageSquare size={64} className="mb-4 opacity-10"/>
                          <p className="font-black text-xs uppercase tracking-widest">Chọn nhân sự để bắt đầu trao đổi</p>
                      </div>
                  )}
              </div>
          </div>
      )}

      {activeTab === 'staff' && (
        <Card title="Quản lý đội ngũ nhân sự">
          <div className="mb-6 flex flex-col md:flex-row gap-4 justify-between items-center bg-gray-50 p-4 rounded-xl border border-gray-100">
             <div className="w-full md:w-64">
                 <Select value={filterDept} onChange={e => setFilterDept(e.target.value)} options={[{value: '', label: '-- Tất cả phòng ban --'}, ...departments.map(d => ({value: d.id, label: d.name}))]} />
             </div>
             <Button onClick={openAddUser} className="rounded-xl w-full md:w-auto px-6 font-black uppercase tracking-tight shadow-md">+ Tạo tài khoản mới</Button>
          </div>
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-100 text-xs">
              <thead>
                <tr className="bg-gray-50 text-gray-400 font-black uppercase tracking-widest">
                  <th className="px-6 py-4 text-left">Mã NV</th>
                  <th className="px-6 py-4 text-left">Họ tên & Vai trò</th>
                  <th className="px-6 py-4 text-left">Phòng ban</th>
                  <th className="px-6 py-4 text-right">Doanh thu tích lũy</th>
                  <th className="px-6 py-4 text-right">Thao tác</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-50">
                {displayUsers.filter(u => filterDept ? u.departmentId === filterDept : true).map(user => {
                  const dept = departments.find(d => d.id === user.departmentId);
                  return (
                  <tr key={user.id} className="hover:bg-blue-50/20 transition-colors">
                    <td className="px-6 py-4 font-black text-gray-900 uppercase tracking-tight">{user.id}</td>
                    <td className="px-6 py-4">
                        <div className="font-black text-gray-800 uppercase leading-none">{user.name}</div>
                        <div className="text-[10px] text-gray-400 font-bold uppercase mt-1">{ROLE_LABELS[user.role]} {user.phone ? `• ${user.phone}` : ''}</div>
                    </td>
                    <td className="px-6 py-4">
                        {dept ? (
                            <div className="flex flex-col">
                                <Badge variant="indigo" className="w-fit">{dept.name}</Badge>
                                <span className="text-[9px] uppercase font-bold text-gray-400 mt-0.5">{dept.level}</span>
                            </div>
                        ) : <span className="text-gray-400 text-[10px] italic">Chưa phân bổ</span>}
                    </td>
                    <td className="px-6 py-4 text-right font-black text-green-600 text-sm">
                        {new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(calculateTotalRevenue(user))}
                    </td>
                    <td className="px-6 py-4 text-right">
                       <div className="flex justify-end gap-2">
                           <button onClick={() => setViewingUser(user)} className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" title="Xem báo cáo"><Eye size={20}/></button>
                           <button onClick={() => openEditUser(user)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"><Edit size={20}/></button>
                           <button onClick={() => handleDeleteUser(user.id)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"><Trash2 size={20}/></button>
                       </div>
                    </td>
                  </tr>
                )})}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {activeTab === 'depts' && canManageDepts && (
          <Card title="Sơ đồ tổ chức & Cấu trúc nhân sự">
             <div className="mb-6 flex justify-between items-center bg-gray-50 p-4 rounded-xl border border-gray-100">
                 <div className="text-xs text-gray-500 italic flex items-center gap-2">
                    <CornerDownRight size={14}/>
                    Sơ đồ hiển thị theo cấp bậc phân nhánh: Trụ sở > Khu vực > Group > Phòng > Nhóm
                 </div>
                 <Button onClick={openAddDept} className="rounded-xl shadow-lg font-black uppercase px-6">+ Thành lập đơn vị mới</Button>
             </div>

             {/* Tree View Container */}
             <div className="bg-white p-4 rounded-xl overflow-x-auto min-h-[500px]">
                {renderDepartmentTree()}
                {departments.length === 0 && (
                    <div className="text-center py-10 text-gray-400 italic">Chưa có dữ liệu phòng ban. Hãy khởi tạo từ Trụ sở chính.</div>
                )}
             </div>
          </Card>
      )}

      {/* Modals */}
      <Modal isOpen={isMsgModalOpen} onClose={() => setMsgModalOpen(false)} title="GỬI THÔNG BÁO TỚI ĐỘI NGŨ">
          <div className="space-y-4 p-1">
              <Select label="Đối tượng nhận tin" options={[{value: 'ALL', label: 'Tất cả nhân viên'}, {value: 'DEPT', label: 'Theo phòng ban'}, {value: 'USER', label: 'Cá nhân cụ thể'}]} value={msgTargetType} onChange={(e: any) => setMsgTargetType(e.target.value)} />
              {msgTargetType === 'DEPT' && <Select label="Chọn phòng ban" options={departments.map(d => ({value: d.id, label: d.name}))} value={msgTargetId} onChange={e => setMsgTargetId(e.target.value)} />}
              {msgTargetType === 'USER' && <Select label="Chọn nhân viên" options={displayUsers.map(u => ({value: u.id, label: u.name}))} value={msgTargetId} onChange={e => setMsgTargetId(e.target.value)} />}
              <div className="w-full">
                <label className="block text-sm font-black uppercase tracking-widest text-gray-500 mb-1">Nội dung thông báo</label>
                <textarea className="w-full border border-gray-200 rounded-xl p-4 h-40 focus:ring-2 focus:ring-blue-500 transition-all font-medium text-sm" value={msgContent} onChange={e => setMsgContent(e.target.value)} placeholder="Nhập chỉ thị hoặc thông báo tại đây..."></textarea>
              </div>
              <div className="flex justify-end gap-3 pt-4 border-t mt-6">
                  <Button variant="ghost" onClick={() => setMsgModalOpen(false)}>HỦY BỎ</Button>
                  <Button onClick={handleSendMessage} className="px-8 shadow-lg shadow-blue-100 uppercase font-black">XÁC NHẬN GỬI</Button>
              </div>
          </div>
      </Modal>

      <Modal isOpen={isUserModalOpen} onClose={() => setUserModalOpen(false)} title={editingUserId ? "CẬP NHẬT TÀI KHOẢN" : "CẤP TÀI KHOẢN MỚI"}>
        <div className="space-y-4 p-1">
            <div className="grid grid-cols-2 gap-4">
                 <Input label="Mã nhân viên" value={formUser.id || ''} onChange={e => setFormUser({...formUser, id: e.target.value.toUpperCase()})} disabled={!!editingUserId} placeholder="NV..." />
                 <Input label="Họ và tên" value={formUser.name || ''} onChange={e => setFormUser({...formUser, name: e.target.value})} placeholder="Nguyễn Văn A" />
            </div>
            <div className="grid grid-cols-2 gap-4">
                 <Input label="Mật khẩu" value={formUser.password || ''} onChange={e => setFormUser({...formUser, password: e.target.value})} />
                 <Input label="Số điện thoại" value={formUser.phone || ''} onChange={e => setFormUser({...formUser, phone: e.target.value})} />
            </div>
            <div className="grid grid-cols-2 gap-4">
                 <Input label="Chức vụ hiển thị" value={formUser.position || ''} onChange={e => setFormUser({...formUser, position: e.target.value})} placeholder="VD: Senior Sale" />
                 <Select label="Vai trò hệ thống" value={formUser.role} onChange={e => setFormUser({...formUser, role: e.target.value as UserRole})} options={allowedRoles.map(role => ({value: role, label: ROLE_LABELS[role]}))} />
            </div>
            <div className="grid grid-cols-2 gap-4">
                 <Input label="Ngày gia nhập" type="date" value={formUser.joinDate || ''} onChange={e => setFormUser({...formUser, joinDate: e.target.value})} />
                 <Input label="Doanh thu ban đầu" type="number" value={formUser.initialRevenue || 0} onChange={e => setFormUser({...formUser, initialRevenue: Number(e.target.value)})} />
            </div>
            <Select label="Trực thuộc đơn vị" value={formUser.departmentId || ''} onChange={e => setFormUser({...formUser, departmentId: e.target.value})} options={[{value: '', label: '-- Không thuộc phòng nào --'}, ...departments.map(d => ({value: d.id, label: `${d.name} (${d.level})`}))]} />
            <div className="flex justify-end gap-3 pt-6 border-t mt-4">
                 <Button variant="ghost" onClick={() => setUserModalOpen(false)}>HỦY</Button>
                 <Button onClick={handleSubmitUser} className="px-8 font-black uppercase">LƯU THÔNG TIN</Button>
            </div>
        </div>
      </Modal>

      <Modal isOpen={isDeptModalOpen} onClose={() => setDeptModalOpen(false)} title={editingDeptId ? "SỬA ĐƠN VỊ" : "THÀNH LẬP ĐƠN VỊ MỚI"}>
          <div className="space-y-4 p-1">
              <Input label="Mã Đơn vị" value={formDept.id || ''} onChange={e => setFormDept({...formDept, id: e.target.value.toUpperCase()})} disabled={!!editingDeptId} placeholder="VD: KV01, GRP02..." />
              <Input label="Tên Đơn vị" value={formDept.name || ''} onChange={e => setFormDept({...formDept, name: e.target.value})} placeholder="Tên hiển thị..." />

              <Select 
                  label="Cấp bậc" 
                  value={formDept.level} 
                  onChange={e => {
                      const newLevel = e.target.value as DepartmentLevel;
                      setFormDept({...formDept, level: newLevel, parentId: ''}); // Reset parent when level changes
                  }} 
                  options={Object.values(DepartmentLevel).map(v => ({value: v, label: v}))} 
              />

              {formDept.level && formDept.level !== DepartmentLevel.HQ && (
                  <Select 
                      label={`Trực thuộc đơn vị (${getAvailableParents(formDept.level).length > 0 ? 'Chọn bên dưới' : 'Chưa có cấp trên phù hợp'})`}
                      value={formDept.parentId || ''} 
                      onChange={e => setFormDept({...formDept, parentId: e.target.value})} 
                      options={[
                          {value: '', label: '-- Chọn đơn vị cấp trên --'},
                          ...getAvailableParents(formDept.level).map(d => ({value: d.id, label: d.name}))
                      ]} 
                  />
              )}

              <Input label="Tên Người đứng đầu" value={formDept.managerName || ''} onChange={e => setFormDept({...formDept, managerName: e.target.value})} placeholder="Nhập tên quản lý..." />

              <div className="flex justify-end gap-3 pt-6 border-t mt-4">
                 <Button variant="ghost" onClick={() => setDeptModalOpen(false)}>HỦY</Button>
                 <Button onClick={handleSubmitDept} className="px-8 font-black uppercase">LƯU CẤU TRÚC</Button>
            </div>
          </div>
      </Modal>
    </div>
  );
};

export enum RevenueType {
  NEW = 'Ký mới',
  HOSTING = 'Hosting',
  HANDOVER = 'Bàn giao',
  UPGRADE_WEB = 'Nâng cấp Web',
  UPGRADE_HOSTING = 'Nâng cấp Hosting'
}

export enum ConsultationType {
  NEW = 'Tư vấn mới',
  OLD = 'Tư vấn cũ',
  DESIGN_REVIEW = 'Duyệt Design',
  HANDOVER = 'Bàn giao',
  UPGRADE = 'Nâng cấp',
  RESTORE = 'Khôi phục Web',
  SUPPORT = 'Hỗ trợ khách hàng',
}

export enum SupportType {
  SOLO = 'Solo',
  COMBINED = 'Kết hợp',
  SUPPORT = 'Hỗ trợ',
  REQUEST_SUPPORT = 'Nhờ hỗ trợ'
}

export enum AppointmentStatus {
  NEW = 'Mới',
  PENDING = 'Lưỡng lự',
  INTERESTED = 'Quan tâm',
  CLOSED = 'Chốt',
  CANCELLED = 'Hủy'
}

// Hierarchy Roles
export enum UserRole {
  DIRECTOR = 'director',             // Giám đốc kinh doanh (Admin cũ)
  REGIONAL_MANAGER = 'regional_manager', // Trưởng khu vực
  GROUP_MANAGER = 'group_manager',       // Trưởng group
  MANAGER = 'manager',                   // Quản lý
  TEAM_LEADER = 'team_leader',           // Trưởng nhóm
  EMPLOYEE = 'employee'                  // Nhân viên
}

export const ROLE_RANK = {
  [UserRole.DIRECTOR]: 6,
  [UserRole.REGIONAL_MANAGER]: 5,
  [UserRole.GROUP_MANAGER]: 4,
  [UserRole.MANAGER]: 3,
  [UserRole.TEAM_LEADER]: 2,
  [UserRole.EMPLOYEE]: 1,
};

export const ROLE_LABELS = {
  [UserRole.DIRECTOR]: 'Giám đốc Kinh Doanh',
  [UserRole.REGIONAL_MANAGER]: 'Trưởng Khu Vực',
  [UserRole.GROUP_MANAGER]: 'Trưởng Group',
  [UserRole.MANAGER]: 'Quản Lý',
  [UserRole.TEAM_LEADER]: 'Trưởng Nhóm',
  [UserRole.EMPLOYEE]: 'Nhân viên'
};

// --- Updated Department Structure ---
export enum DepartmentLevel {
  HQ = 'Trụ sở',
  REGION = 'Khu vực',
  GROUP = 'Group',
  DEPARTMENT = 'Phòng',
  TEAM = 'Nhóm'
}

export interface Department {
  id: string;
  name: string;
  managerName: string;
  managerId?: string; // Added field for linking
  level: DepartmentLevel; 
  parentId?: string | null; // ID of the parent unit (e.g., Group belongs to Region)
}

export interface User {
  id: string; // Employee Code
  name: string;
  role: UserRole; 
  managerId?: string; // ID của người quản lý trực tiếp (người tạo ra account này)
  departmentId?: string;
  password?: string;
  position?: string; // Chức vụ hiển thị (text tự do hoặc map từ role)
  phone?: string; // Số điện thoại
  joinDate?: string; 
  initialRevenue?: number; 
}

export interface Appointment {
  id: string;
  userId: string;
  companyName: string;
  customerName: string;
  phone: string;
  email?: string; 
  source: string;
  status: AppointmentStatus;
  date: string; 
  location: string; 
  addressDetail?: string; 
  notes?: string;
}

export interface Consultation {
  id: string;
  userId: string;
  appointmentId?: string;
  customerName: string;
