                           <button onClick={() => setViewingUser(user)} className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" title="Xem báo cáo"><Eye size={20}/></button>
                           <button onClick={() => openEditUser(user)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"><Edit size={20}/></button>
                           <button onClick={() => handleDeleteUser(user.id)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"><Trash2 size={20}/></button>
                       </div>
                    </td>
                  </tr>
                )})}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {activeTab === 'depts' && canManageDepts && (
          <Card title="Sơ đồ tổ chức & Cấu trúc nhân sự">
             <div className="mb-6 flex justify-between items-center bg-gray-50 p-4 rounded-xl border border-gray-100">
                 <div className="text-xs text-gray-500 italic flex items-center gap-2">
                    <CornerDownRight size={14}/>
                    Sơ đồ hiển thị theo cấp bậc phân nhánh: Trụ sở > Khu vực > Group > Phòng > Nhóm
                 </div>
                 <Button onClick={openAddDept} className="rounded-xl shadow-lg font-black uppercase px-6">+ Thành lập đơn vị mới</Button>
             </div>

             {/* Tree View Container */}
             <div className="bg-white p-4 rounded-xl overflow-x-auto min-h-[500px]">
                {renderDepartmentTree()}
                {departments.length === 0 && (
                    <div className="text-center py-10 text-gray-400 italic">Chưa có dữ liệu phòng ban. Hãy khởi tạo từ Trụ sở chính.</div>
                )}
             </div>
          </Card>
      )}

      {/* Modals */}
      <Modal isOpen={isMsgModalOpen} onClose={() => setMsgModalOpen(false)} title="GỬI THÔNG BÁO TỚI ĐỘI NGŨ">
          <div className="space-y-4 p-1">
              <Select label="Đối tượng nhận tin" options={[{value: 'ALL', label: 'Tất cả nhân viên'}, {value: 'DEPT', label: 'Theo phòng ban'}, {value: 'USER', label: 'Cá nhân cụ thể'}]} value={msgTargetType} onChange={(e: any) => setMsgTargetType(e.target.value)} />
              {msgTargetType === 'DEPT' && <Select label="Chọn phòng ban" options={departments.map(d => ({value: d.id, label: d.name}))} value={msgTargetId} onChange={e => setMsgTargetId(e.target.value)} />}
              {msgTargetType === 'USER' && <Select label="Chọn nhân viên" options={displayUsers.map(u => ({value: u.id, label: u.name}))} value={msgTargetId} onChange={e => setMsgTargetId(e.target.value)} />}
              <div className="w-full">
                <label className="block text-sm font-black uppercase tracking-widest text-gray-500 mb-1">Nội dung thông báo</label>
                <textarea className="w-full border border-gray-200 rounded-xl p-4 h-40 focus:ring-2 focus:ring-blue-500 transition-all font-medium text-sm" value={msgContent} onChange={e => setMsgContent(e.target.value)} placeholder="Nhập chỉ thị hoặc thông báo tại đây..."></textarea>
              </div>
              <div className="flex justify-end gap-3 pt-4 border-t mt-6">
                  <Button variant="ghost" onClick={() => setMsgModalOpen(false)}>HỦY BỎ</Button>
                  <Button onClick={handleSendMessage} className="px-8 shadow-lg shadow-blue-100 uppercase font-black">XÁC NHẬN GỬI</Button>
              </div>
          </div>
      </Modal>

      <Modal isOpen={isUserModalOpen} onClose={() => setUserModalOpen(false)} title={editingUserId ? "CẬP NHẬT TÀI KHOẢN" : "CẤP TÀI KHOẢN MỚI"}>
        <div className="space-y-4 p-1">
            <div className="grid grid-cols-2 gap-4">
                 <Input label="Mã nhân viên" value={formUser.id || ''} onChange={e => setFormUser({...formUser, id: e.target.value.toUpperCase()})} disabled={!!editingUserId} placeholder="NV..." />
                 <Input label="Họ và tên" value={formUser.name || ''} onChange={e => setFormUser({...formUser, name: e.target.value})} placeholder="Nguyễn Văn A" />
            </div>
            <div className="grid grid-cols-2 gap-4">
                 <Input label="Mật khẩu" value={formUser.password || ''} onChange={e => setFormUser({...formUser, password: e.target.value})} />
                 <Input label="Số điện thoại" value={formUser.phone || ''} onChange={e => setFormUser({...formUser, phone: e.target.value})} />
            </div>
            <div className="grid grid-cols-2 gap-4">
                 <Input label="Chức vụ hiển thị" value={formUser.position || ''} onChange={e => setFormUser({...formUser, position: e.target.value})} placeholder="VD: Senior Sale" />
                 <Select label="Vai trò hệ thống" value={formUser.role} onChange={e => setFormUser({...formUser, role: e.target.value as UserRole})} options={allowedRoles.map(role => ({value: role, label: ROLE_LABELS[role]}))} />
            </div>
            <div className="grid grid-cols-2 gap-4">
                 <Input label="Ngày gia nhập" type="date" value={formUser.joinDate || ''} onChange={e => setFormUser({...formUser, joinDate: e.target.value})} />
                 <Input label="Doanh thu ban đầu" type="number" value={formUser.initialRevenue || 0} onChange={e => setFormUser({...formUser, initialRevenue: Number(e.target.value)})} />
            </div>
            <Select label="Trực thuộc đơn vị" value={formUser.departmentId || ''} onChange={e => setFormUser({...formUser, departmentId: e.target.value})} options={[{value: '', label: '-- Không thuộc phòng nào --'}, ...departments.map(d => ({value: d.id, label: `${d.name} (${d.level})`}))]} />
            <div className="flex justify-end gap-3 pt-6 border-t mt-4">
                 <Button variant="ghost" onClick={() => setUserModalOpen(false)}>HỦY</Button>
                 <Button onClick={handleSubmitUser} className="px-8 font-black uppercase">LƯU THÔNG TIN</Button>
            </div>
        </div>
      </Modal>

      <Modal isOpen={isDeptModalOpen} onClose={() => setDeptModalOpen(false)} title={editingDeptId ? "SỬA ĐƠN VỊ" : "THÀNH LẬP ĐƠN VỊ MỚI"}>
          <div className="space-y-4 p-1">
              <Input label="Mã Đơn vị" value={formDept.id || ''} onChange={e => setFormDept({...formDept, id: e.target.value.toUpperCase()})} disabled={!!editingDeptId} placeholder="VD: KV01, GRP02..." />
              <Input label="Tên Đơn vị" value={formDept.name || ''} onChange={e => setFormDept({...formDept, name: e.target.value})} placeholder="Tên hiển thị..." />

              <Select 
                  label="Cấp bậc" 
                  value={formDept.level} 
                  onChange={e => {
                      const newLevel = e.target.value as DepartmentLevel;
                      setFormDept({...formDept, level: newLevel, parentId: ''}); // Reset parent when level changes
                  }} 
                  options={Object.values(DepartmentLevel).map(v => ({value: v, label: v}))} 
              />

              {formDept.level && formDept.level !== DepartmentLevel.HQ && (
                  <Select 
                      label={`Trực thuộc đơn vị (${getAvailableParents(formDept.level).length > 0 ? 'Chọn bên dưới' : 'Chưa có cấp trên phù hợp'})`}
                      value={formDept.parentId || ''} 
                      onChange={e => setFormDept({...formDept, parentId: e.target.value})} 
                      options={[
                          {value: '', label: '-- Chọn đơn vị cấp trên --'},
                          ...getAvailableParents(formDept.level).map(d => ({value: d.id, label: d.name}))
                      ]} 
                  />
              )}

              <div className="grid grid-cols-2 gap-4">
                  <div className="relative">
                      <Input 
                          label="Mã Quản lý (Mã NV)" 
                          value={formDept.managerId || ''} 
                          onChange={e => setFormDept({...formDept, managerId: e.target.value.toUpperCase()})}
                          onBlur={() => {
                              const user = allUsers.find(u => u.id === formDept.managerId);
                              if (user) {
                                  setFormDept(prev => ({...prev, managerName: user.name}));
                              } else if (formDept.managerId) {
                                  alert("Không tìm thấy nhân viên với mã này!");
                                  setFormDept(prev => ({...prev, managerName: ''}));
                              }
                          }}
                          placeholder="Nhập mã NV..." 
                      />
                      {formDept.managerName && <span className="absolute right-2 top-9 text-green-600"><CheckCircle size={16}/></span>}
                  </div>
                  <Input 
                      label="Tên Quản lý (Tự động)" 
                      value={formDept.managerName || ''} 
                      disabled 
                      className="bg-gray-100 text-gray-500 font-bold" 
                  />
              </div>

              <div className="flex justify-end gap-3 pt-6 border-t mt-4">
                 <Button variant="ghost" onClick={() => setDeptModalOpen(false)}>HỦY</Button>
                 <Button onClick={handleSubmitDept} className="px-8 font-black uppercase">LƯU CẤU TRÚC</Button>
            </div>
          </div>
      </Modal>
    </div>
  );
};

