interface AdminDashboardProps {
  currentUser: User;
}

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser }) => {
  const [loading, setLoading] = useState(true);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [expandedDepts, setExpandedDepts] = useState<Record<string, boolean>>({});

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [depts, users] = await Promise.all([
          storageService.getDepartments(),
          storageService.getUsers()
        ]);
        setDepartments(depts);
        setAllUsers(users);
      } catch (error) {
        console.error("Failed to load admin data", error);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  // --- RECURSIVE LOGIC FOR PERSONNEL COUNT (Cumulative) ---
  const getCumulativeHeadcount = (deptId: string): number => {
      const uniqueUserIds = new Set<string>();

      const collectUsers = (currentDeptId: string) => {
          // 1. Add Manager of this department (Trưởng cấp tính là 1)
          const currentDept = departments.find(d => d.id === currentDeptId);
          if (currentDept && currentDept.managerId) {
              uniqueUserIds.add(currentDept.managerId);
          }

          // 2. Add Users assigned to this department
          const deptUsers = allUsers.filter(u => u.departmentId === currentDeptId);
          deptUsers.forEach(u => uniqueUserIds.add(u.id));

          // 3. Recurse for children (Cấp dưới cùng nhánh - đệ quy sâu)
          const children = departments.filter(d => d.parentId === currentDeptId);
          children.forEach(child => collectUsers(child.id));
      };

      collectUsers(deptId);
      return uniqueUserIds.size;
  };

  // Helper to build department tree
  const buildDeptTree = (parentId: string | null = null): any[] => {
    return departments
      .filter(d => d.parentId === parentId || (!parentId && !d.parentId))
      .map(dept => ({
        ...dept,
        children: buildDeptTree(dept.id)
      }));
  };

  const toggleDept = (id: string) => {
    setExpandedDepts(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const renderDeptRow = (dept: any, depth = 0) => {
    const hasChildren = dept.children && dept.children.length > 0;
    const isExpanded = expandedDepts[dept.id];
    const headcount = getCumulativeHeadcount(dept.id);

    // Only show direct members in the list detail
    const directMembers = allUsers.filter(u => u.departmentId === dept.id);

    return (
      <div key={dept.id} className="animate-fadeIn">
        <div 
          className={`flex items-center p-3 hover:bg-gray-50 border-b border-gray-100 transition-colors cursor-pointer select-none`}
          style={{ paddingLeft: `${depth * 20 + 12}px` }}
          onClick={() => toggleDept(dept.id)}
        >
          <div className="mr-2 text-gray-400 w-5 flex justify-center">
             {hasChildren && (
               isExpanded ? <ChevronDown size={16}/> : <ChevronRight size={16}/>
             )}
          </div>
          <div className="flex-1">
             <div className="flex items-center gap-2">
                <span className="font-bold text-gray-800">{dept.name}</span>
                <Badge variant="info">{dept.level}</Badge>
             </div>
             <div className="text-xs text-gray-500 mt-0.5">
                Quản lý: <span className="font-medium text-blue-600">{dept.managerName}</span>
             </div>
          </div>
          <div className="text-right px-4">
             <div className="text-sm font-bold text-gray-700">{headcount} nhân sự</div>
          </div>
        </div>
        {isExpanded && (
            <div>
               {directMembers.length > 0 && (
                   <div className="bg-gray-50/50 p-2 pl-12 border-b border-gray-100">
                       <div className="text-[10px] uppercase font-bold text-gray-400 mb-1">Thành viên trực thuộc ({directMembers.length})</div>
                       <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-2">
                           {directMembers.map(u => (
                               <div key={u.id} className="bg-white border border-gray-200 p-2 rounded flex items-center gap-2">
                                   <div className="w-6 h-6 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center text-xs font-bold">
                                       {u.name.charAt(0)}
                                   </div>
                                   <div className="overflow-hidden">
                                       <div className="text-xs font-medium truncate">{u.name}</div>
                                       <div className="text-[10px] text-gray-400">{u.id}</div>
                                   </div>
                               </div>
                           ))}
                       </div>
                   </div>
               )}
               {dept.children.map((child: any) => renderDeptRow(child, depth + 1))}
            </div>
        )}
      </div>
    );
  };

  const deptTree = useMemo(() => buildDeptTree(null), [departments, allUsers]);

  if (loading) {
      return <div className="h-64 flex items-center justify-center"><Loader2 className="animate-spin text-blue-600"/></div>;
  }

  return (
    <div className="space-y-6">
       <div className="flex justify-between items-center">
           <h2 className="text-2xl font-bold text-gray-800">Quản Trị Hệ Thống</h2>
       </div>

       <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
           <Card className="md:col-span-2">
               <div className="flex items-center gap-2 mb-4">
                   <Building2 className="text-blue-600"/>
                   <h3 className="font-bold text-lg">Cơ Cấu Tổ Chức</h3>
               </div>
               <div className="border border-gray-200 rounded-lg overflow-hidden">
                   <div className="bg-gray-50 p-3 border-b border-gray-200 text-xs font-bold text-gray-500 uppercase flex">
                       <div className="w-8"></div>
                       <div className="flex-1">Tên Đơn Vị</div>
                       <div className="px-4">Tổng Nhân sự</div>
                   </div>
                   {deptTree.map(dept => renderDeptRow(dept))}
                   {departments.length === 0 && <div className="p-8 text-center text-gray-400">Chưa có dữ liệu phòng ban</div>}
               </div>
           </Card>

           <div className="space-y-6">
               <Card>
                   <div className="flex items-center gap-2 mb-4">
                       <Users className="text-green-600"/>
                       <h3 className="font-bold text-lg">Tổng Quan Nhân Sự</h3>
                   </div>
                   <div className="space-y-4">
                       <div className="bg-blue-50 p-4 rounded-xl">
                           <div className="text-sm text-blue-800 font-medium">Tổng số nhân viên</div>
                           <div className="text-3xl font-black text-blue-600">{allUsers.length}</div>
                       </div>
                       <div className="bg-purple-50 p-4 rounded-xl">
                           <div className="text-sm text-purple-800 font-medium">Phòng ban / Nhóm</div>
                           <div className="text-3xl font-black text-purple-600">{departments.length}</div>
                       </div>
                   </div>
               </Card>
           </div>
       </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
