import { Users, TrendingUp, Calendar, Edit, Trash2, Eye, ArrowLeft, Send, MessageSquare, Search, LayoutGrid, Loader2, GitMerge, ChevronRight, CornerDownRight, CheckCircle, PlusCircle, Filter } from 'lucide-react';
import { EmployeeDashboard } from './EmployeeDashboard';

interface AdminDashboardProps {
    currentUser: User; 
