               </div>

               <div className="flex justify-end gap-3 pt-4 border-t mt-6">
                 <Button variant="ghost" onClick={() => setShowRevModal(false)}>Hủy</Button>
                 <Button onClick={() => submitForm(async () => {
                    if(!newRev.amountCollected || !newRev.contractCode) throw new Error("Thiếu số tiền hoặc Mã HĐ");
                    if(newRev.type === RevenueType.NEW && !newRev.contractValue) throw new Error("Cần nhập giá trị hợp đồng");

                    const revenueData = { ...newRev, id: editingId || `R${Date.now()}`, userId: user.id } as Revenue;
                    if (editingId) await storageService.updateRevenue(revenueData);
                    else await storageService.addRevenue(revenueData);
                 }, setShowRevModal)} className="bg-orange-600 hover:bg-orange-500">{editingId ? 'CẬP NHẬT' : 'XÁC NHẬN THU'}</Button>
              </div>
             </div>
        </Modal>
        </>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer 
} from 'recharts';
import { 
  Users, 
  DollarSign, 
  TrendingUp, 
  Calendar, 
  AlertCircle 
} from 'lucide-react';
import { User, Revenue, Appointment, Consultation, Department } from '../types';
import { storageService } from '../services/storageService';
import { Card } from '../components/ui';

interface AdminDashboardProps {
  currentUser: User;
}

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser }) => {
  const [loading, setLoading] = useState(true);
  const [users, setUsers] = useState<User[]>([]);
  const [revenues, setRevenues] = useState<Revenue[]>([]);
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [consultations, setConsultations] = useState<Consultation[]>([]);
  const [departments, setDepartments] = useState<Department[]>([]);

  // Load data
  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        const [u, r, a, c, d] = await Promise.all([
          storageService.getUsers(),
          storageService.getRevenues(),
          storageService.getAppointments(),
          storageService.getConsultations(),
          storageService.getDepartments()
        ]);
        setUsers(u);
        setRevenues(r);
        setAppointments(a);
        setConsultations(c);
        setDepartments(d);
      } catch (error) {
        console.error("Error fetching admin data", error);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  // Analysis Data
  const analysisData = useMemo(() => {
    // 1. Chart Data (Revenue by Month)
    const last6Months = Array.from({ length: 6 }, (_, i) => {
      const d = new Date();
      d.setMonth(d.getMonth() - i);
      return {
        month: d.getMonth() + 1,
        year: d.getFullYear(),
        label: `T${d.getMonth() + 1}`,
        key: `${d.getFullYear()}-${(d.getMonth() + 1).toString().padStart(2, '0')}`
      };
    }).reverse();

    const chartData = last6Months.map(m => {
      const monthRevenues = revenues.filter(r => r.date.startsWith(m.key));
      return {
        name: m.label,
        revenue: monthRevenues.reduce((sum, r) => sum + r.amountCollected, 0),
        appointments: appointments.filter(a => a.date.startsWith(m.key)).length,
        consultations: consultations.filter(c => c.date.startsWith(m.key)).length
      };
    });

    // 2. Total Revenue
    const totalRevenue = revenues.reduce((sum, r) => sum + r.amountCollected, 0);

    // 3. Team Performance (Top 5)
    const userPerformance = users.map(u => {
      const userRevs = revenues.filter(r => r.userId === u.id);
      const total = userRevs.reduce((sum, r) => sum + r.amountCollected, 0);
      return { ...u, totalRevenue: total + (u.initialRevenue || 0) };
    }).sort((a, b) => b.totalRevenue - a.totalRevenue).slice(0, 5);

    return {
      chartData,
      totalRevenue,
      userPerformance,
      totalUsers: users.length,
      pendingRevenues: revenues.filter(r => !r.isApproved).length
    };
  }, [revenues, appointments, consultations, users]);

  const formatCurrency = (val: number) => new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(val);

  if (loading) return <div className="p-8 text-center">Đang tải dữ liệu quản trị...</div>;

  return (
    <div className="space-y-6 animate-fadeIn">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="bg-gradient-to-br from-blue-500 to-blue-600 text-white border-none">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-blue-100 text-sm font-medium">Tổng Doanh Thu</p>
              <h3 className="text-2xl font-bold mt-1">{formatCurrency(analysisData.totalRevenue)}</h3>
            </div>
            <div className="p-2 bg-white/20 rounded-lg">
              <DollarSign size={20} className="text-white" />
            </div>
          </div>
        </Card>

        <Card className="bg-white">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-gray-500 text-sm font-medium">Nhân sự</p>
              <h3 className="text-2xl font-bold mt-1 text-gray-800">{analysisData.totalUsers}</h3>
            </div>
            <div className="p-2 bg-blue-50 rounded-lg">
              <Users size={20} className="text-blue-600" />
            </div>
          </div>
        </Card>

        <Card className="bg-white">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-gray-500 text-sm font-medium">Doanh thu chờ duyệt</p>
              <h3 className="text-2xl font-bold mt-1 text-orange-600">{analysisData.pendingRevenues}</h3>
            </div>
            <div className="p-2 bg-orange-50 rounded-lg">
              <AlertCircle size={20} className="text-orange-600" />
            </div>
          </div>
        </Card>

        <Card className="bg-white">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-gray-500 text-sm font-medium">Tăng trưởng tháng</p>
              <div className="flex items-center gap-1 mt-1 text-green-600 font-bold text-lg">
                <TrendingUp size={16} />
                <span>+12.5%</span>
              </div>
            </div>
            <div className="p-2 bg-green-50 rounded-lg">
              <Calendar size={20} className="text-green-600" />
            </div>
          </div>
        </Card>
      </div>

      <Card title="Phân tích tăng trưởng & Xu hướng">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 bg-gray-50/50 p-6 rounded-2xl border border-gray-100 min-w-0">
                <div className="h-72">
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={analysisData.chartData}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} />
                            <XAxis dataKey="name" axisLine={false} tickLine={false} />
                            <YAxis axisLine={false} tickLine={false} tickFormatter={(value) => `${value / 1000000}M`} />
                            <Tooltip formatter={(value: number) => formatCurrency(value)} />
                            <Legend />
                            <Bar dataKey="revenue" name="Doanh thu" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={40} />
                        </BarChart>
                    </ResponsiveContainer>
                </div>
            </div>
            <div className="space-y-4">
                <h4 className="font-bold text-gray-700">Top nhân viên xuất sắc</h4>
                <div className="space-y-3">
                  {analysisData.userPerformance.map((u, idx) => (
                    <div key={u.id} className="flex items-center justify-between p-3 bg-white rounded-xl border border-gray-100 shadow-sm">
                      <div className="flex items-center gap-3">
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs ${idx === 0 ? 'bg-yellow-100 text-yellow-700' : 'bg-gray-100 text-gray-600'}`}>
                          {idx + 1}
                        </div>
                        <div>
                          <div className="font-bold text-sm text-gray-800">{u.name}</div>
                          <div className="text-xs text-gray-500">{u.id}</div>
                        </div>
                      </div>
                      <div className="font-bold text-blue-600 text-sm">{formatCurrency(u.totalRevenue || 0)}</div>
                    </div>
                  ))}
                </div>
            </div>
        </div>
      </Card>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
