             <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <Card className="border-t-4 border-t-blue-500">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Tổng nhân sự (Phạm vi lọc)</p>
                            <h3 className="text-4xl font-black text-gray-800">{filteredDashboardData.users.length}</h3>
