                                    <Bar dataKey="revenue" radius={[6, 6, 0, 0]}>
                                        {analysisData.chartData.map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={index === analysisData.chartData.length - 1 ? '#3b82f6' : '#94a3b8'} />
