                            {currentConversation.map(msg => (
                                <div key={msg.id} className={`flex ${msg.senderId === manager.id ? 'justify-end' : 'justify-start'}`}>
                                    <div className={`max-w-[80%] rounded-2xl p-4 shadow-sm ${msg.senderId === manager.id ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'}`}>
                                        <div className="text-sm font-medium leading-relaxed whitespace-pre-wrap">{msg.content}</div>
                                        <div className={`text-[9px] mt-2 font-black uppercase tracking-widest ${msg.senderId === manager.id ? 'text-blue-200 text-right' : 'text-gray-400'}`}>{new Date(msg.timestamp).toLocaleString('vi-VN')}</div>
                                    </div>
                                </div>
                            ))}
                            <div ref={chatEndRef}></div>
                        </div>
                        <div className="p-4 bg-white border-t border-gray-100">
                             <div className="flex gap-2 bg-gray-50 p-2 rounded-2xl border border-gray-100">
                                  <input className="flex-1 bg-transparent border-none px-4 py-2 outline-none text-sm font-medium" placeholder="Nhập tin nhắn trả lời..." value={adminChatInput} onChange={e => setAdminChatInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleAdminReply()} />
                                  <button onClick={handleAdminReply} className="bg-blue-600 text-white p-3 rounded-xl hover:bg-blue-700 active:scale-95 transition-all shadow-lg"><Send size={18}/></button>
                             </div>
                        </div>
                      </>
                  ) : (
                      <div className="flex-1 flex flex-col items-center justify-center text-gray-300">
                          <MessageSquare size={64} className="mb-4 opacity-10"/>
                          <p className="font-black text-xs uppercase tracking-widest">Chọn nhân sự để bắt đầu trao đổi</p>
                      </div>
                  )}
              </div>
          </div>
      )}

      {/* STAFF TAB */}
      {activeTab === 'staff' && (
        <Card title="Quản lý đội ngũ nhân sự">
          <div className="mb-6 flex flex-col md:flex-row gap-4 justify-between items-center bg-gray-50 p-4 rounded-xl border border-gray-100">
             <div className="w-full md:w-64">
                <Input placeholder="Tìm nhanh nhân viên..." value={chatSearchTerm} onChange={e => setChatSearchTerm(e.target.value)} />
             </div>
             <Button onClick={openAddUser} className="rounded-xl w-full md:w-auto px-6 font-black uppercase tracking-tight shadow-md">+ Tạo tài khoản mới</Button>
          </div>
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-100 text-xs">
              <thead>
                <tr className="bg-gray-50 text-gray-400 font-black uppercase tracking-widest">
                  <th className="px-6 py-4 text-left">Mã NV</th>
                  <th className="px-6 py-4 text-left">Họ tên & Vai trò</th>
                  <th className="px-6 py-4 text-left">Phòng ban</th>
                  <th className="px-6 py-4 text-right">Doanh thu tích lũy</th>
                  <th className="px-6 py-4 text-right">Thao tác</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-50">
                {displayUsers.filter(u => chatSearchTerm ? u.name.toLowerCase().includes(chatSearchTerm.toLowerCase()) : true).map(user => {
                  const dept = departments.find(d => d.id === user.departmentId);
                  return (
                  <tr key={user.id} className="hover:bg-blue-50/20 transition-colors">
                    <td className="px-6 py-4 font-black text-gray-900 uppercase tracking-tight">{user.id}</td>
                    <td className="px-6 py-4">
                        <div className="font-black text-gray-800 uppercase leading-none">{user.name}</div>
                        <div className="text-[10px] text-gray-400 font-bold uppercase mt-1">{ROLE_LABELS[user.role]} {user.phone ? `• ${user.phone}` : ''}</div>
                    </td>
                    <td className="px-6 py-4">
                        {dept ? (
                            <div className="flex flex-col">
                                <Badge variant="indigo" className="w-fit">{dept.name}</Badge>
                                <span className="text-[9px] uppercase font-bold text-gray-400 mt-0.5">{dept.level}</span>
                            </div>
                        ) : <span className="text-gray-400 text-[10px] italic">Chưa phân bổ</span>}
                    </td>
                    <td className="px-6 py-4 text-right font-black text-green-600 text-sm">
                        {new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(calculateTotalRevenue(user))}
                    </td>
                    <td className="px-6 py-4 text-right">
                       <div className="flex justify-end gap-2">
                           <button onClick={() => setViewingUser(user)} className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" title="Xem báo cáo"><Eye size={20}/></button>
                           <button onClick={() => openEditUser(user)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"><Edit size={20}/></button>
                           <button onClick={() => handleDeleteUser(user.id)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"><Trash2 size={20}/></button>
                       </div>
                    </td>
                  </tr>
                )})}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {/* DEPTS TAB */}
      {activeTab === 'depts' && (
          <div className="bg-gray-200/50 p-6 rounded-2xl overflow-x-auto min-h-[600px] border border-gray-200">
             <div className="mb-6 flex justify-between items-center bg-white p-4 rounded-xl shadow-sm">
                 <div className="text-xs text-gray-500 italic flex items-center gap-2">
                    <CornerDownRight size={14}/>
                    Sơ đồ tổ chức hiển thị theo cấp bậc phân nhánh
                 </div>
                 {canEditStructure && <Button onClick={openAddDept} className="rounded-xl shadow-lg font-black uppercase px-6">+ Thành lập đơn vị thủ công</Button>}
             </div>

             <div className="flex justify-center min-w-max pb-12">
                {renderTreeNodes(null)}
             </div>
          </div>
      )}

      {/* MODALS */}
      <Modal isOpen={isMsgModalOpen} onClose={() => setMsgModalOpen(false)} title="GỬI THÔNG BÁO TỚI ĐỘI NGŨ">
          <div className="space-y-4 p-1">
              <Select label="Đối tượng nhận tin" options={[{value: 'ALL', label: 'Tất cả nhân viên'}, {value: 'DEPT', label: 'Theo phòng ban'}, {value: 'USER', label: 'Cá nhân cụ thể'}]} value={msgTargetType} onChange={(e: any) => setMsgTargetType(e.target.value)} />
              {msgTargetType === 'DEPT' && <Select label="Chọn phòng ban" options={departments.map(d => ({value: d.id, label: d.name}))} value={msgTargetId} onChange={e => setMsgTargetId(e.target.value)} />}
              {msgTargetType === 'USER' && <Select label="Chọn nhân viên" options={displayUsers.map(u => ({value: u.id, label: u.name}))} value={msgTargetId} onChange={e => setMsgTargetId(e.target.value)} />}
              <div className="w-full">
                <label className="block text-sm font-black uppercase tracking-widest text-gray-500 mb-1">Nội dung thông báo</label>
                <textarea className="w-full border border-gray-200 rounded-xl p-4 h-40 focus:ring-2 focus:ring-blue-500 transition-all font-medium text-sm" value={msgContent} onChange={e => setMsgContent(e.target.value)} placeholder="Nhập chỉ thị hoặc thông báo tại đây..."></textarea>
              </div>
              <div className="flex justify-end gap-3 pt-4 border-t mt-6">
                  <Button variant="ghost" onClick={() => setMsgModalOpen(false)}>HỦY BỎ</Button>
                  <Button onClick={handleSendMessage} className="px-8 shadow-lg shadow-blue-100 uppercase font-black">XÁC NHẬN GỬI</Button>
              </div>
          </div>
      </Modal>

      <Modal isOpen={isUserModalOpen} onClose={() => setUserModalOpen(false)} title={editingUserId ? "CẬP NHẬT TÀI KHOẢN" : "CẤP TÀI KHOẢN MỚI"}>
        <div className="space-y-4 p-1">
            <div className="grid grid-cols-2 gap-4">
                 <Input label="Mã nhân viên" value={formUser.id || ''} onChange={e => setFormUser({...formUser, id: e.target.value.toUpperCase()})} disabled={!!editingUserId} placeholder="NV..." />
                 <Input label="Họ và tên" value={formUser.name || ''} onChange={e => setFormUser({...formUser, name: e.target.value})} placeholder="Nguyễn Văn A" />
            </div>
            <div className="grid grid-cols-2 gap-4">
                 <Input label="Mật khẩu" value={formUser.password || ''} onChange={e => setFormUser({...formUser, password: e.target.value})} />
                 <Input label="Số điện thoại" value={formUser.phone || ''} onChange={e => setFormUser({...formUser, phone: e.target.value})} />
            </div>

            <div className="bg-gray-50 p-4 rounded-xl border border-gray-100 space-y-4">
                <Select label="Vai trò hệ thống" value={formUser.role} onChange={e => setFormUser({...formUser, role: e.target.value as UserRole})} options={allowedRoles.map(role => ({value: role, label: ROLE_LABELS[role]}))} />

                {formUser.role === UserRole.EMPLOYEE ? (
                    <Select 
                        label="Trực thuộc đơn vị (Phòng/Nhóm)" 
                        value={formUser.departmentId || ''} 
                        onChange={e => setFormUser({...formUser, departmentId: e.target.value})} 
                        options={[{value: '', label: '-- Chọn đơn vị --'}, ...departments.map(d => ({value: d.id, label: `${d.name} (${d.level})`}))]} 
                    />
                ) : (
                    <div className="space-y-4 animate-fadeIn">
                        <div className="flex items-center gap-2 mb-2">
                            <GitMerge size={16} className="text-blue-500"/>
                            <span className="text-xs font-black uppercase text-gray-500">Cấu hình Đơn vị quản lý</span>
                        </div>

                        {!editingUserId && (
                             <>
                                <Input 
                                    label={`Tên đơn vị quản lý (Tạo mới)`} 
                                    placeholder={`Ví dụ: Team A...`}
                                    value={formUser.newDeptName || ''}
                                    onChange={e => setFormUser({...formUser, newDeptName: e.target.value})}
                                />
                                <Select 
                                    label={`Trực thuộc đơn vị cấp trên`}
                                    value={formUser.newDeptParentId || ''} 
                                    onChange={e => setFormUser({...formUser, newDeptParentId: e.target.value})} 
                                    options={[
                                        {value: '', label: '-- Chọn cấp trên --'},
                                        ...departments.filter(d => d.level !== DepartmentLevel.TEAM).map(d => ({value: d.id, label: d.name}))
                                    ]} 
                                />
                             </>
                        )}
                         {editingUserId && (
                            <div className="p-3 bg-blue-50 rounded-lg text-xs text-blue-700">
                                <b>Lưu ý:</b> Đang chỉnh sửa tài khoản quản lý. Nếu muốn thay đổi đơn vị quản lý, vui lòng sử dụng tab "Phòng ban".
                            </div>
                        )}
                    </div>
                )}
            </div>

            <div className="grid grid-cols-2 gap-4">
                 <Input label="Ngày gia nhập" type="date" value={formUser.joinDate || ''} onChange={e => setFormUser({...formUser, joinDate: e.target.value})} />
                 <Input label="Doanh thu ban đầu" type="number" value={formUser.initialRevenue || 0} onChange={e => setFormUser({...formUser, initialRevenue: Number(e.target.value)})} />
            </div>

            <div className="flex justify-end gap-3 pt-6 border-t mt-4">
                 <Button variant="ghost" onClick={() => setUserModalOpen(false)}>HỦY</Button>
                 <Button onClick={handleSubmitUser} className="px-8 font-black uppercase">LƯU THÔNG TIN</Button>
            </div>
        </div>
      </Modal>

      <Modal isOpen={isDeptModalOpen} onClose={() => setDeptModalOpen(false)} title={editingDeptId ? "SỬA ĐƠN VỊ" : "THÀNH LẬP ĐƠN VỊ MỚI"}>
          <div className="space-y-4 p-1">
              <Input label="Mã Đơn vị" value={formDept.id || ''} onChange={e => setFormDept({...formDept, id: e.target.value.toUpperCase()})} disabled={!!editingDeptId} placeholder="VD: KV01, GRP02..." />
              <Input label="Tên Đơn vị" value={formDept.name || ''} onChange={e => setFormDept({...formDept, name: e.target.value})} placeholder="Tên hiển thị..." />

              <Select 
                  label="Cấp bậc" 
                  value={formDept.level} 
                  onChange={e => {
                      const newLevel = e.target.value as DepartmentLevel;
                      setFormDept({...formDept, level: newLevel, parentId: ''}); 
                  }} 
                  options={Object.values(DepartmentLevel).map(v => ({value: v, label: v}))} 
              />

              {formDept.level && formDept.level !== DepartmentLevel.HQ && (
                  <Select 
                      label={`Trực thuộc đơn vị (${getAvailableParents(formDept.level).length > 0 ? 'Chọn bên dưới' : 'Chưa có cấp trên phù hợp'})`}
                      value={formDept.parentId || ''} 
                      onChange={e => setFormDept({...formDept, parentId: e.target.value})} 
                      options={[
                          {value: '', label: '-- Chọn đơn vị cấp trên --'},
                          ...getAvailableParents(formDept.level).map(d => ({value: d.id, label: d.name}))
                      ]} 
                  />
              )}

              <div className="grid grid-cols-2 gap-4">
                  <div className="relative">
                      <Input 
                          label="Mã Quản lý (Mã NV)" 
                          value={formDept.managerId || ''} 
                          onChange={e => setFormDept({...formDept, managerId: e.target.value.toUpperCase()})}
                          onBlur={() => {
                              const user = allUsers.find(u => u.id === formDept.managerId);
                              if (user) {
                                  setFormDept(prev => ({...prev, managerName: user.name}));
                              } else if (formDept.managerId) {
                                  alert("Không tìm thấy nhân viên với mã này!");
                                  setFormDept(prev => ({...prev, managerName: ''}));
                              }
                          }}
                          placeholder="Nhập mã NV..." 
                      />
                      {formDept.managerName && <span className="absolute right-2 top-9 text-green-600"><CheckCircle size={16}/></span>}
                  </div>
                  <Input 
                      label="Tên Quản lý (Tự động)" 
                      value={formDept.managerName || ''} 
                      disabled 
                      className="bg-gray-100 text-gray-500 font-bold" 
                  />
              </div>

              <div className="flex justify-end gap-3 pt-6 border-t mt-4">
                 <Button variant="ghost" onClick={() => setDeptModalOpen(false)}>HỦY</Button>
                 <Button onClick={handleSubmitDept} className="px-8 font-black uppercase">LƯU CẤU TRÚC</Button>
            </div>
          </div>
      </Modal>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { storageService } from '../services/storageService';
import { User, Department, Appointment, Revenue, Message, UserRole, ROLE_RANK, ROLE_LABELS, DepartmentLevel, ProjectProfile } from '../types';
import { Button, Input, Modal, Select, Card, Badge } from '../components/ui';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { Users, TrendingUp, Calendar, Edit, Trash2, Eye, ArrowLeft, Send, MessageSquare, Search, LayoutGrid, Loader2, GitMerge, CornerDownRight, CheckCircle, Filter, Briefcase, Building2, Crown, UserCircle, Users as UsersIcon } from 'lucide-react';
import { EmployeeDashboard } from './EmployeeDashboard';

interface AdminDashboardProps {
    currentUser: User; 
}

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser }) => {
  const manager = currentUser;
  const [loading, setLoading] = useState(true);

  // Tabs state
  const [activeTab, setActiveTab] = useState<'personal' | 'dashboard' | 'staff' | 'depts' | 'chat'>('dashboard');

  const [departments, setDepartments] = useState<Department[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [allRevenues, setAllRevenues] = useState<Revenue[]>([]);
  const [allAppointments, setAllAppointments] = useState<Appointment[]>([]);
  const [allProjects, setAllProjects] = useState<ProjectProfile[]>([]);

  // --- MULTI-LEVEL FILTER STATE ---
  const [filterRegion, setFilterRegion] = useState('');
  const [filterGroup, setFilterGroup] = useState('');
  const [filterDept, setFilterDept] = useState('');
  const [filterTeam, setFilterTeam] = useState('');
  const [filterUser, setFilterUser] = useState('');

  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [selectedChatUser, setSelectedChatUser] = useState<string | null>(null);
  const [adminChatInput, setAdminChatInput] = useState('');
  const [chatSearchTerm, setChatSearchTerm] = useState('');
  const [chatFilterRole, setChatFilterRole] = useState<string>('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const [isMsgModalOpen, setMsgModalOpen] = useState(false);
  const [msgContent, setMsgContent] = useState('');
  const [msgTargetType, setMsgTargetType] = useState<'ALL' | 'DEPT' | 'USER'>('ALL');
  const [msgTargetId, setMsgTargetId] = useState('');

  const [isUserModalOpen, setUserModalOpen] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [formUser, setFormUser] = useState<Partial<User> & { 
      newDeptName?: string, 
      newDeptParentId?: string 
  }>({});

  const [isDeptModalOpen, setDeptModalOpen] = useState(false);
  const [editingDeptId, setEditingDeptId] = useState<string | null>(null);
  const [formDept, setFormDept] = useState<Partial<Department>>({ level: DepartmentLevel.DEPARTMENT });

  const [viewingUser, setViewingUser] = useState<User | null>(null);

  const myRank = ROLE_RANK[manager.role];

  // Quyền chỉnh sửa cấu trúc (Sơ đồ): Chỉ Admin (6), Trưởng Khu vực (5), Trưởng Group (4)
  const canEditStructure = myRank >= 4;

  const refreshData = async () => {
      setLoading(true);
      try {
          const [u, d, r, a, m, p] = await Promise.all([
              storageService.getUsers(),
              storageService.getDepartments(),
              storageService.getRevenues(),
              storageService.getAppointments(),
              storageService.getMessages(),
              storageService.getProjects()
          ]);
          setAllUsers(u);
          setDepartments(d);
          setAllRevenues(r);
          setAllAppointments(a);
          setAllMessages(m);
          setAllProjects(p);
      } catch (error) {
          console.error("Failed to load data", error);
      } finally {
          setLoading(false);
      }
  };

  const silentRefreshMsg = async () => {
      const m = await storageService.getMessages();
      setAllMessages(m);
  };

  useEffect(() => {
     refreshData();
     const interval = setInterval(() => {
         silentRefreshMsg();
     }, 10000); 
     return () => clearInterval(interval);
  }, []);

  useEffect(() => {
     if(activeTab === 'chat' && selectedChatUser) {
         chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
     }
  }, [allMessages, selectedChatUser, activeTab]);

  // --- LOGIC TÌM NHÂN SỰ CẤP DƯỚI (QUAN TRỌNG) ---
  // Kết hợp cả: 
  // 1. Cây thư mục Manager (managerId recursive)
  // 2. Cây thư mục Phòng ban (Nếu tôi là Manager phòng A, tôi thấy hết nhân sự phòng A và con của A)
  const mySubordinates = useMemo(() => {
      const subordinateIds = new Set<string>();

      // Cách 1: Tìm theo dây chuyền ManagerId (Recursive)
      const traverseManager = (mgrId: string) => {
          allUsers.filter(u => u.managerId === mgrId).forEach(u => {
              subordinateIds.add(u.id);
              traverseManager(u.id);
          });
      };
      traverseManager(manager.id);

      // Cách 2: Tìm theo quyền quản lý Phòng ban (Department Hierarchy)
      // Tìm tất cả phòng ban mà user hiện tại đang làm Quản lý (managerId khớp trong Dept)
      const myManagedDepts = departments.filter(d => d.managerId === manager.id);

      const managedDeptIds = new Set<string>();
      const traverseDept = (deptId: string) => {
          managedDeptIds.add(deptId);
          // Tìm các phòng con
          departments.filter(d => d.parentId === deptId).forEach(child => traverseDept(child.id));
      };
      myManagedDepts.forEach(d => traverseDept(d.id));

      // Lấy tất cả user thuộc các phòng ban này
      allUsers.filter(u => u.departmentId && managedDeptIds.has(u.departmentId)).forEach(u => {
          if (u.id !== manager.id) subordinateIds.add(u.id);
      });

      // Kết quả: List nhân viên cấp dưới + Bản thân Manager
      const result = allUsers.filter(u => subordinateIds.has(u.id));
      return [manager, ...result];
  }, [allUsers, departments, manager]);

  const displayUsers = useMemo(() => mySubordinates.filter(u => u.id !== manager.id), [mySubordinates, manager.id]);

  // --- HIERARCHY FILTER LOGIC ---
  const regionOptions = useMemo(() => departments.filter(d => d.level === DepartmentLevel.REGION), [departments]);

  const groupOptions = useMemo(() => {
      if (!filterRegion) return [];
      return departments.filter(d => d.level === DepartmentLevel.GROUP && d.parentId === filterRegion);
  }, [departments, filterRegion]);

  const deptOptions = useMemo(() => {
      if (!filterGroup) return [];
      return departments.filter(d => d.level === DepartmentLevel.DEPARTMENT && d.parentId === filterGroup);
  }, [departments, filterGroup]);

  const teamOptions = useMemo(() => {
      if (!filterDept) return [];
      return departments.filter(d => d.level === DepartmentLevel.TEAM && d.parentId === filterDept);
  }, [departments, filterDept]);

  const userOptions = useMemo(() => {
      const targetDeptId = filterTeam || filterDept || filterGroup || filterRegion;

      if (!targetDeptId) return displayUsers; // Show my subordinates if no filter

      const recursiveUserIds = new Set<string>();
      const collectUsers = (deptId: string) => {
           allUsers.filter(u => u.departmentId === deptId).forEach(u => recursiveUserIds.add(u.id));
           const dept = departments.find(d => d.id === deptId);
           if (dept?.managerId) recursiveUserIds.add(dept.managerId);
           departments.filter(d => d.parentId === deptId).forEach(child => collectUsers(child.id));
      };
      collectUsers(targetDeptId);

      // Chỉ hiển thị những user thuộc phạm vi quản lý của mình
      const allowedIds = new Set(mySubordinates.map(u => u.id));
      return allUsers.filter(u => recursiveUserIds.has(u.id) && allowedIds.has(u.id) && u.id !== manager.id);

  }, [allUsers, departments, filterRegion, filterGroup, filterDept, filterTeam, manager.id, displayUsers, mySubordinates]);

  // Auto-reset filters
  useEffect(() => { setFilterGroup(''); setFilterDept(''); setFilterTeam(''); setFilterUser(''); }, [filterRegion]);
  useEffect(() => { setFilterDept(''); setFilterTeam(''); setFilterUser(''); }, [filterGroup]);
  useEffect(() => { setFilterTeam(''); setFilterUser(''); }, [filterDept]);
  useEffect(() => { setFilterUser(''); }, [filterTeam]);


  // --- DASHBOARD DATA CALCULATION (PERSONAL VS TEAM) ---
  const dashboardStats = useMemo(() => {
      // 1. Personal Stats (Manager Only)
      const myRevenues = allRevenues.filter(r => r.userId === manager.id);
      const myAppointments = allAppointments.filter(a => a.userId === manager.id);
      const myTotalRevenue = myRevenues.reduce((s, r) => s + r.amountCollected, 0) + (manager.initialRevenue || 0);

      // 2. Team Stats (Filtered Scope)
      let targetUserIds = new Set<string>();

      if (filterUser) {
          targetUserIds.add(filterUser);
      } else {
          // If filtering by Org Unit, get recursive users
          const scopeId = filterTeam || filterDept || filterGroup || filterRegion;
          if (scopeId) {
               const collect = (dId: string) => {
                   const dept = departments.find(d => d.id === dId);
                   if (dept?.managerId && dept.managerId !== manager.id) targetUserIds.add(dept.managerId);
                   allUsers.filter(u => u.departmentId === dId && u.id !== manager.id).forEach(u => targetUserIds.add(u.id));
                   departments.filter(d => d.parentId === dId).forEach(c => collect(c.id));
               };
               collect(scopeId);
          } else {
              // Default: All my subordinates (excluding me)
              displayUsers.forEach(u => targetUserIds.add(u.id));
          }
      }

      // Ensure we only calculate for users visible in displayUsers (security check)
      const validTargetIds = new Set([...targetUserIds].filter(id => displayUsers.some(u => u.id === id)));

      const teamRevenues = allRevenues.filter(r => validTargetIds.has(r.userId));
      const teamAppointments = allAppointments.filter(a => validTargetIds.has(a.userId));
      const teamTotalRevenue = teamRevenues.reduce((s, r) => s + r.amountCollected, 0);

      // 3. Chart Data (Combined or Team based on view)
      const chartRevenues = [...myRevenues, ...teamRevenues]; // Default showing overview
      const now = new Date();
      const currentMonthStr = now.toISOString().slice(0, 7);

      const monthlyData: Record<string, number> = {};
      chartRevenues.forEach(r => {
          const month = r.date.substring(0, 7);
          monthlyData[month] = (monthlyData[month] || 0) + r.amountCollected;
      });
      const chartData = Object.keys(monthlyData).sort().map(k => ({ name: k, revenue: monthlyData[k] }));

      // Analysis Text
      let conclusion = "Chưa có đủ dữ liệu để đánh giá.";
      if (chartData.length >= 2) {
          const last = chartData[chartData.length - 1].revenue;
          const prev = chartData[chartData.length - 2].revenue;
          const diff = last - prev;
          const percent = prev > 0 ? ((diff / prev) * 100).toFixed(1) : 100;
          if (diff > 0) conclusion = `Tăng trưởng tích cực: Tháng ${chartData[chartData.length-1].name} tăng ${percent}% so với tháng trước.`;
          else if (diff < 0) conclusion = `Cảnh báo sụt giảm: Tháng ${chartData[chartData.length-1].name} giảm ${Math.abs(Number(percent))}% so với tháng trước.`;
      }

      // Top Companies
      const companyRevenueMap: Record<string, number> = {};
      const currentMonthRevenues = chartRevenues.filter(r => r.date.startsWith(currentMonthStr));

      currentMonthRevenues.forEach(r => {
          let companyName = r.customerName;
          if (r.contractCode) {
              const proj = allProjects.find(p => p.contractCode === r.contractCode);
              if (proj && proj.companyName) companyName = proj.companyName;
              else if (proj && proj.customerName) companyName = proj.customerName;
          }
          if (!companyName) companyName = "Khách lẻ / Chưa cập nhật";
          companyRevenueMap[companyName] = (companyRevenueMap[companyName] || 0) + r.amountCollected;
      });

      const topCompanies = Object.entries(companyRevenueMap)
          .map(([name, value]) => ({ name, value }))
          .sort((a, b) => b.value - a.value)
          .slice(0, 10);

      return {
          personal: { revenue: myTotalRevenue, apps: myAppointments.length, user: manager },
          team: { revenue: teamTotalRevenue, apps: teamAppointments.length, count: validTargetIds.size },
          chartData,
          conclusion,
          topCompanies
      };

  }, [allRevenues, allAppointments, manager, filterUser, filterTeam, filterDept, filterGroup, filterRegion, displayUsers, allProjects]);


  // --- HELPER FOR ORG CHART (Cumulative Count) ---
  const getCumulativeHeadcount = (deptId: string): number => {
      const uniqueUserIds = new Set<string>();
      const collectUsers = (currentDeptId: string) => {
          const currentDept = departments.find(d => d.id === currentDeptId);
          if (currentDept && currentDept.managerId) uniqueUserIds.add(currentDept.managerId);
          allUsers.filter(u => u.departmentId === currentDeptId).forEach(u => uniqueUserIds.add(u.id));
          departments.filter(d => d.parentId === currentDeptId).forEach(child => collectUsers(child.id));
      };
      collectUsers(deptId);
      return uniqueUserIds.size;
  };

  // Chat Logic
  const chatUsers = useMemo(() => {
      let filtered = displayUsers;
      if (chatSearchTerm) {
          const term = chatSearchTerm.toLowerCase();
          filtered = filtered.filter(u => u.name.toLowerCase().includes(term) || u.id.toLowerCase().includes(term) || (u.phone && u.phone.includes(term)));
      }
      if (chatFilterRole) filtered = filtered.filter(u => u.role === chatFilterRole);
      return filtered;
  }, [displayUsers, chatSearchTerm, chatFilterRole]);

  const currentConversation = useMemo(() => {
      if (!selectedChatUser) return [];
      return allMessages.filter(m => 
          (m.senderId === manager.id && m.receiverId === selectedChatUser) ||
          (m.senderId === selectedChatUser && m.receiverId === manager.id)
      ).sort((a,b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
  }, [allMessages, selectedChatUser, manager.id]);

  const handleAdminReply = async () => {
      if (!selectedChatUser || !adminChatInput.trim()) return;
      await storageService.sendMessage({ id: `MSG${Date.now()}`, senderId: manager.id, senderName: manager.name, receiverId: selectedChatUser, content: adminChatInput, timestamp: new Date().toISOString(), isRead: false });
      setAdminChatInput(''); 
      silentRefreshMsg();
  };

  const handleSendMessage = async () => {
      if (!msgContent) return;

      let receiverIds: string[] = [];

      if (msgTargetType === 'ALL') {
          // Gửi cho toàn bộ nhân sự cấp dưới
          receiverIds = displayUsers.map(u => u.id);
      } 
      else if (msgTargetType === 'USER') {
          if (msgTargetId) receiverIds = [msgTargetId];
      } 
      else if (msgTargetType === 'DEPT') {
          if (msgTargetId) {
             // Logic: Tìm phòng ban này và TẤT CẢ phòng ban con
             const targetDeptIds = new Set<string>();
             const collectDepts = (dId: string) => {
                 targetDeptIds.add(dId);
                 departments.filter(d => d.parentId === dId).forEach(c => collectDepts(c.id));
             };
             collectDepts(msgTargetId);

             // Tìm tất cả user thuộc các phòng ban này (bao gồm cả trưởng phòng)
             allUsers.forEach(u => {
                 // Nếu user thuộc phòng đó HOẶC user là quản lý của phòng đó
                 if (u.departmentId && targetDeptIds.has(u.departmentId)) {
                     if (u.id !== manager.id) receiverIds.push(u.id);
                 }
                 // Check if user is manager of one of these depts
                 const managedDept = departments.find(d => d.id === u.departmentId); // Note: Logic check managerId of Dept is better
                 // Easier: Iterate departments and get managerId
             });

             // Explicitly add managers of these departments
             targetDeptIds.forEach(dId => {
                 const d = departments.find(item => item.id === dId);
                 if (d && d.managerId && d.managerId !== manager.id) receiverIds.push(d.managerId);
             });

             // Unique
             receiverIds = [...new Set(receiverIds)];
          }
      }

      if (receiverIds.length === 0) return alert("Không tìm thấy người nhận phù hợp!");

      await storageService.sendMessage({ 
          id: `MSG${Date.now()}`, 
          senderId: manager.id, 
          senderName: manager.name, 
          receiverId: receiverIds, // Send Array
          content: msgContent, 
          timestamp: new Date().toISOString(), 
          isRead: false 
      });

      alert(`Đã gửi thông báo thành công cho ${receiverIds.length} nhân sự!`); 
      setMsgModalOpen(false); 
      setMsgContent('');
      silentRefreshMsg();
  };

  const calculateTotalRevenue = (user: User) => {
      const earned = allRevenues.filter(r => r.userId === user.id).reduce((s, r) => s + r.amountCollected, 0);
      return earned + (user.initialRevenue || 0);
  };

  // User & Dept Management Logic
  const openAddUser = () => { setEditingUserId(null); setFormUser({ role: UserRole.EMPLOYEE, initialRevenue: 0, managerId: manager.id }); setUserModalOpen(true); };
  const openEditUser = (user: User) => { setEditingUserId(user.id); setFormUser({ ...user }); setUserModalOpen(true); };

  const handleSubmitUser = async () => {
    if (!formUser.id || !formUser.name || !formUser.password) return alert("Vui lòng điền đủ thông tin");
    const targetRank = ROLE_RANK[formUser.role as UserRole];
    if (targetRank > myRank) return alert("Cấp bậc không hợp lệ.");

    const isManagerRole = [UserRole.REGIONAL_MANAGER, UserRole.GROUP_MANAGER, UserRole.MANAGER, UserRole.TEAM_LEADER].includes(formUser.role as UserRole);

    try {
        let finalDeptId = formUser.departmentId;

        if (isManagerRole && formUser.newDeptName && formUser.newDeptParentId) {
             const deptLevel = (() => {
                switch(formUser.role) {
                    case UserRole.REGIONAL_MANAGER: return DepartmentLevel.REGION;
                    case UserRole.GROUP_MANAGER: return DepartmentLevel.GROUP;
                    case UserRole.MANAGER: return DepartmentLevel.DEPARTMENT;
                    case UserRole.TEAM_LEADER: return DepartmentLevel.TEAM;
                    default: return null;
                }
             })();

             const newDeptId = `${deptLevel?.substring(0,3).toUpperCase()}_${formUser.id}`; 

             await storageService.addDepartment({
                 id: newDeptId,
                 name: formUser.newDeptName,
                 level: deptLevel!,
                 managerId: formUser.id,
                 managerName: formUser.name,
                 parentId: formUser.newDeptParentId
             });
             finalDeptId = newDeptId; 
        } else if (isManagerRole && !editingUserId) {
            if (!formUser.departmentId && !formUser.newDeptName) return alert("Với vai trò quản lý, vui lòng tạo đơn vị quản lý hoặc chọn đơn vị.");
        }

        const userData = { ...formUser, departmentId: finalDeptId };
        delete userData.newDeptName;
        delete userData.newDeptParentId;

        if (editingUserId) await storageService.updateUser(userData as User);
        else await storageService.addUser({ ...userData, managerId: manager.id } as User);

        await refreshData(); setUserModalOpen(false);
    } catch (e: any) { alert(e.message); }
  };

  const handleDeleteUser = async (id: string) => { if(confirm("Xóa nhân viên này?")) { try { await storageService.deleteUser(id); await refreshData(); } catch(e: any) { alert(e.message); } } };
