                            options={[{value: '', label: '-- Tất cả --'}, ...teamOptions.map(d => ({value: d.id, label: d.name}))]} 
                            value={filterTeam} 
                            onChange={e => setFilterTeam(e.target.value)} 
                            disabled={!filterDept && teamOptions.length === 0}
                        />
                        <Select 
