                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Nhân sự cấp dưới (Lọc)</p>
                                <h3 className="text-4xl font-black text-gray-800">{dashboardStats.team.count}</h3>
                            </div>
                            <div className="bg-indigo-50 p-3 rounded-2xl text-indigo-600"><Users size={28}/></div>
                        </div>
                    </Card>
