                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <Select label="Loại hình tư vấn" value={newCons.type} onChange={e => setNewCons({...newCons, type: e.target.value as ConsultationType})} options={Object.values(ConsultationType).map(t => ({value: t, label: t}))} />
                    <Input label="Nguồn khách" placeholder="FB, Data, Google..." value={newCons.source || ''} onChange={e => setNewCons({...newCons, source: e.target.value})} />
                </div>
                <div className="grid grid-cols-1 gap-4">
                     <Input label="Địa chỉ / Khu vực" value={newCons.addressDetail || ''} onChange={e => setNewCons({...newCons, addressDetail: e.target.value})} />
                     <Input label="Nội dung chính / Ghi chú" value={newCons.notes || ''} onChange={e => setNewCons({...newCons, notes: e.target.value})} placeholder="Các yêu cầu đặc biệt của khách..." />
                </div>
                <div className="flex justify-end gap-3 pt-4 border-t mt-6">
                    <Button variant="ghost" onClick={() => setShowConsModal(false)}>Hủy bỏ</Button>
                    <Button onClick={() => submitForm(async () => {
                        if(!newCons.phone || !newCons.customerName) throw new Error("Thiếu SĐT hoặc Tên");
                        if (editingId) await storageService.updateConsultation({ ...newCons, id: editingId } as Consultation);
                        else await storageService.addConsultation({ ...newCons, id: `C${Date.now()}`, userId: user.id } as Consultation);
                    }, setShowConsModal)}>LƯU PHIẾU</Button>
                </div>
            </div>
        </Modal>

        <Modal isOpen={showRevModal} onClose={() => setShowRevModal(false)} title={editingId ? "CẬP NHẬT DOANH THU" : "PHIẾU THU DOANH THU"}>
             <div className="space-y-4 p-1">
               <div className="bg-gray-800 text-white p-4 rounded-xl shadow-inner flex items-end gap-3">
                   <div className="flex-1">
                       <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-1">Truy vấn nhanh khách hàng</label>
                       <input className="w-full bg-gray-700 border-none rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500" value={revSearchPhone} onChange={e => setRevSearchPhone(e.target.value)} placeholder="Nhập SĐT..." />
                   </div>
                   <Button size="md" onClick={handleRevPhoneSearch} className="h-[38px] bg-blue-500 hover:bg-blue-400"><Search size={18}/></Button>
               </div>
               <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <Input label="Ngày thu" type="datetime-local" value={newRev.date} onChange={e => setNewRev({...newRev, date: e.target.value})} />
                    <Select label="Khoản thu" value={newRev.type} onChange={e => setNewRev(prev => ({ ...prev, type: e.target.value as RevenueType }))} options={Object.values(RevenueType).map(t => ({value: t, label: t}))} />
               </div>
               <div className="p-4 rounded-xl bg-gray-50 border border-gray-100 space-y-3">
                    <Input label="Khách hàng" value={newRev.customerName || ''} onChange={e => setNewRev({...newRev, customerName: e.target.value})} />
                    <div className="grid grid-cols-2 gap-4">
                        <Input label="Mã Hợp Đồng" value={newRev.contractCode || ''} onChange={e => setNewRev({...newRev, contractCode: e.target.value})} className="font-bold uppercase text-blue-700" />
                        <Input label="Số điện thoại" value={newRev.phone || ''} onChange={e => setNewRev({...newRev, phone: e.target.value})} />
                    </div>
               </div>
               {newRev.type === RevenueType.NEW && (
                   <div className="animate-fadeIn p-4 bg-green-50 rounded-xl border border-green-100">
                       <Input label="Giá trị hợp đồng gốc (Gói Web)" type="number" value={newRev.contractValue || ''} onChange={e => setNewRev({...newRev, contractValue: Number(e.target.value)})} className="font-black text-green-700" />
                       <p className="text-[10px] text-green-600 mt-1 font-bold">Giá trị tổng của dự án khi bắt đầu ký</p>
                   </div>
               )}
               {newRev.type === RevenueType.HANDOVER && (
                 <div className="bg-yellow-50 p-4 rounded-xl border border-yellow-100">
                    <label className="block text-xs font-black text-yellow-700 uppercase mb-2">Liên kết hợp đồng ký mới</label>
                    <select className="w-full p-2.5 border rounded-xl bg-white text-sm" onChange={e => {
                        const val = e.target.value;
                        const parent = revenues.find(r => r.id === val);
                        if (parent) {
                            const remaining = parent.contractValue - parent.amountCollected;
                            setNewRev(prev => ({ ...prev, relatedContractId: val, contractCode: parent.contractCode, contractValue: parent.contractValue, amountCollected: remaining > 0 ? remaining : 0 }));
                        }
                    }}>
                       <option value="">-- Chọn hợp đồng --</option>
                       {revenues.filter(r => r.userId === user.id && r.type === RevenueType.NEW).map(r => (
                          <option key={r.id} value={r.id}>{r.contractCode} - Gói: {formatCurrency(r.contractValue)}</option>
                       ))}
                    </select>
                 </div>
               )}
               <div className="p-4 bg-orange-50 rounded-xl border border-orange-100">
                    <Input label="Số tiền thu thực tế" type="number" value={newRev.amountCollected || ''} onChange={e => setNewRev({...newRev, amountCollected: Number(e.target.value)})} className="font-black text-red-600 text-lg" />
                    <p className="text-[10px] text-orange-600 mt-1 font-bold uppercase tracking-widest">Kế toán sẽ căn cứ vào số này</p>
               </div>
               <div className="flex justify-end gap-3 pt-4 border-t mt-6">
                 <Button variant="ghost" onClick={() => setShowRevModal(false)}>Hủy</Button>
                 <Button onClick={() => submitForm(async () => {
                    if(!newRev.amountCollected || !newRev.contractCode) throw new Error("Thiếu số tiền hoặc Mã HĐ");
                    if(newRev.type === RevenueType.NEW && !newRev.contractValue) throw new Error("Cần nhập giá trị hợp đồng");

                    const revenueData = { ...newRev, id: editingId || `R${Date.now()}`, userId: user.id } as Revenue;
                    if (editingId) await storageService.updateRevenue(revenueData);
                    else await storageService.addRevenue(revenueData);
                 }, setShowRevModal)} className="bg-orange-600 hover:bg-orange-500">{editingId ? 'CẬP NHẬT' : 'XÁC NHẬN THU'}</Button>
              </div>
             </div>
        </Modal>
        </>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { storageService } from '../services/storageService';
import { User, Department, Appointment, Revenue, Message, UserRole, ROLE_RANK, ROLE_LABELS, DepartmentLevel, ProjectProfile } from '../types';
import { Button, Input, Modal, Select, Card, Badge } from '../components/ui';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { Users, TrendingUp, Calendar, Edit, Trash2, Eye, ArrowLeft, Send, MessageSquare, Search, LayoutGrid, Loader2, GitMerge, CornerDownRight, CheckCircle, Filter, Briefcase, Building2, Crown, UserCircle, Users as UsersIcon, X } from 'lucide-react';
import { EmployeeDashboard } from './EmployeeDashboard';

interface AdminDashboardProps {
    currentUser: User; 
}

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser }) => {
  const manager = currentUser;
  const [loading, setLoading] = useState(true);

  // Tabs state
  const [activeTab, setActiveTab] = useState<'personal' | 'dashboard' | 'staff' | 'depts' | 'chat'>('dashboard');

  const [departments, setDepartments] = useState<Department[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [allRevenues, setAllRevenues] = useState<Revenue[]>([]);
  const [allAppointments, setAllAppointments] = useState<Appointment[]>([]);
  const [allProjects, setAllProjects] = useState<ProjectProfile[]>([]);

  // --- DATE FILTER STATE (Default: Current Month) ---
  const [startDate, setStartDate] = useState(() => {
      const date = new Date();
      return new Date(date.getFullYear(), date.getMonth(), 1).toISOString().split('T')[0];
  });
  const [endDate, setEndDate] = useState(() => {
      const date = new Date();
      return new Date(date.getFullYear(), date.getMonth() + 1, 0).toISOString().split('T')[0];
  });

  // --- MULTI-LEVEL FILTER STATE ---
  const [filterRegion, setFilterRegion] = useState('');
  const [filterGroup, setFilterGroup] = useState('');
  const [filterDept, setFilterDept] = useState('');
  const [filterTeam, setFilterTeam] = useState('');
  const [filterUser, setFilterUser] = useState('');

  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [selectedChatUser, setSelectedChatUser] = useState<string | null>(null);
  const [adminChatInput, setAdminChatInput] = useState('');
  const [chatSearchTerm, setChatSearchTerm] = useState('');
  const [chatFilterRole, setChatFilterRole] = useState<string>('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const [isMsgModalOpen, setMsgModalOpen] = useState(false);
  const [msgContent, setMsgContent] = useState('');
  const [msgTargetType, setMsgTargetType] = useState<'ALL' | 'DEPT' | 'USER'>('ALL');
  const [msgTargetId, setMsgTargetId] = useState('');

  const [isUserModalOpen, setUserModalOpen] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [formUser, setFormUser] = useState<Partial<User> & { 
      newDeptName?: string, 
      newDeptParentId?: string 
  }>({});

  const [isDeptModalOpen, setDeptModalOpen] = useState(false);
  const [editingDeptId, setEditingDeptId] = useState<string | null>(null);
  const [formDept, setFormDept] = useState<Partial<Department>>({ level: DepartmentLevel.DEPARTMENT });

  const [viewingUser, setViewingUser] = useState<User | null>(null);

  const myRank = ROLE_RANK[manager.role];
  const canEditStructure = myRank >= 4;

  const refreshData = async () => {
      setLoading(true);
      try {
          const [u, d, r, a, m, p] = await Promise.all([
              storageService.getUsers(),
              storageService.getDepartments(),
              storageService.getRevenues(),
              storageService.getAppointments(),
              storageService.getMessages(),
              storageService.getProjects()
          ]);
          setAllUsers(u);
          setDepartments(d);
          setAllRevenues(r);
          setAllAppointments(a);
          setAllMessages(m);
          setAllProjects(p);
      } catch (error) {
          console.error("Failed to load data", error);
      } finally {
          setLoading(false);
      }
  };

  const silentRefreshMsg = async () => {
      const m = await storageService.getMessages();
      setAllMessages(m);
  };

  useEffect(() => {
     refreshData();
     const interval = setInterval(() => {
         silentRefreshMsg();
     }, 10000); 
     return () => clearInterval(interval);
  }, []);

  useEffect(() => {
     if(activeTab === 'chat' && selectedChatUser) {
         chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
     }
  }, [allMessages, selectedChatUser, activeTab]);

  // --- STRICT SUBORDINATE LOGIC (CORRECTED) ---
  const mySubordinates = useMemo(() => {
      // 1. If I am an Employee (Rank 1), I manage no one.
      if (myRank <= 1) return [manager];

      const visibleUserIds = new Set<string>();

      // A. HIERARCHY BASED: Get all departments I manage (directly or recursively)
      const managedDeptIds = new Set<string>();

      // A1. Departments where I am the direct manager
      const directDepts = departments.filter(d => d.managerId === manager.id);

      // A2. Recursive Sub-departments
      const deptQueue = [...directDepts];
      while (deptQueue.length > 0) {
          const curr = deptQueue.pop()!;
          managedDeptIds.add(curr.id);
          const children = departments.filter(d => d.parentId === curr.id);
          deptQueue.push(...children);
      }

      // A3. Add all users in these departments
      allUsers.forEach(u => {
          if (u.departmentId && managedDeptIds.has(u.departmentId)) {
               // Prevent adding myself if I'm technically "in" the department I manage
               if (u.id !== manager.id) visibleUserIds.add(u.id);
          }
      });

      // A4. Explicitly add managers of the sub-departments (they are subordinates too)
      departments.forEach(d => {
          if (managedDeptIds.has(d.id) && d.managerId && d.managerId !== manager.id) {
              visibleUserIds.add(d.managerId);
          }
      });

      // B. DIRECT REPORT BASED (Legacy fallback): Users who report directly to me via managerId
      // and their recursive reports.
      const directReportQueue = allUsers.filter(u => u.managerId === manager.id);
      while(directReportQueue.length > 0) {
          const curr = directReportQueue.pop()!;
          if (curr.id !== manager.id) {
              visibleUserIds.add(curr.id);
              const nextLevel = allUsers.filter(u => u.managerId === curr.id);
              directReportQueue.push(...nextLevel);
          }
      }

      const result = allUsers.filter(u => visibleUserIds.has(u.id));
      return [manager, ...result];
  }, [allUsers, departments, manager, myRank]);


  // --- HIERARCHICAL SORTING HELPERS ---
  const getDeptWeight = (level?: DepartmentLevel) => {
      switch(level) {
          case DepartmentLevel.HQ: return 5;
          case DepartmentLevel.REGION: return 4;
          case DepartmentLevel.GROUP: return 3;
          case DepartmentLevel.DEPARTMENT: return 2;
          case DepartmentLevel.TEAM: return 1;
          default: return 0;
      }
  };

  const getFullDeptPath = (deptId: string | undefined): string => {
      if (!deptId) return 'Z_Unassigned'; // Sort unassigned last
      const dept = departments.find(d => d.id === deptId);
      if (!dept) return 'Z_Unassigned';

      // Build string like: "RegionName - GroupName - DeptName" to sort alphabetically
      let path = dept.name;
      let curr = dept;
      while (curr.parentId) {
          const parent = departments.find(d => d.id === curr.parentId);
          if (parent) {
              path = `${parent.name} > ${path}`;
              curr = parent;
          } else {
              break;
          }
      }
      // Prefix with weight to group by top-level structure if needed, 
      // but alphabetical path is usually what user wants: "Khu Vực 1 > Group A..."
      return path;
  };

  const displayUsers = useMemo(() => {
      const users = mySubordinates.filter(u => u.id !== manager.id);

      // Sort: Dept Path -> Role Rank (High to Low) -> Name
      return users.sort((a, b) => {
          const pathA = getFullDeptPath(a.departmentId);
          const pathB = getFullDeptPath(b.departmentId);

          if (pathA !== pathB) return pathA.localeCompare(pathB);

          // Same dept? Sort by Rank (Manager first)
          const rankA = ROLE_RANK[a.role] || 0;
          const rankB = ROLE_RANK[b.role] || 0;
          if (rankA !== rankB) return rankB - rankA;

          return a.name.localeCompare(b.name);
      });
  }, [mySubordinates, manager.id, departments]);


  // --- HIERARCHY FILTER LOGIC ---
  const regionOptions = useMemo(() => departments.filter(d => d.level === DepartmentLevel.REGION), [departments]);

  const groupOptions = useMemo(() => {
      if (!filterRegion) return [];
      return departments.filter(d => d.level === DepartmentLevel.GROUP && d.parentId === filterRegion);
  }, [departments, filterRegion]);

  const deptOptions = useMemo(() => {
      if (!filterGroup) return [];
      return departments.filter(d => d.level === DepartmentLevel.DEPARTMENT && d.parentId === filterGroup);
  }, [departments, filterGroup]);

  const teamOptions = useMemo(() => {
      if (!filterDept) return [];
      return departments.filter(d => d.level === DepartmentLevel.TEAM && d.parentId === filterDept);
  }, [departments, filterDept]);

  const userOptions = useMemo(() => {
      const targetDeptId = filterTeam || filterDept || filterGroup || filterRegion;
      if (!targetDeptId) return displayUsers;

      // Filter visible users by selected Dept ID scope
      const targetDeptIds = new Set<string>();
      const q = [targetDeptId];
      while(q.length) {
          const curr = q.pop()!;
          targetDeptIds.add(curr);
          q.push(...departments.filter(d => d.parentId === curr).map(d => d.id));
      }

      return displayUsers.filter(u => u.departmentId && targetDeptIds.has(u.departmentId));

  }, [displayUsers, departments, filterRegion, filterGroup, filterDept, filterTeam]);

  useEffect(() => { setFilterGroup(''); setFilterDept(''); setFilterTeam(''); setFilterUser(''); }, [filterRegion]);
  useEffect(() => { setFilterDept(''); setFilterTeam(''); setFilterUser(''); }, [filterGroup]);
  useEffect(() => { setFilterTeam(''); setFilterUser(''); }, [filterDept]);
  useEffect(() => { setFilterUser(''); }, [filterTeam]);

  // --- HELPER: CHECK DATE RANGE ---
  const isInRange = (dateStr: string) => {
      if (!dateStr) return false;
      const d = dateStr.split('T')[0];
      return d >= startDate && d <= endDate;
  };

  // --- DASHBOARD DATA CALCULATION ---
  const dashboardStats = useMemo(() => {
      // 1. Personal Stats (Manager Only) - Filtered by Date
      const myRevenues = allRevenues.filter(r => r.userId === manager.id && isInRange(r.date));
      const myAppointments = allAppointments.filter(a => a.userId === manager.id && isInRange(a.date));
      const myTotalRevenue = myRevenues.reduce((s, r) => s + r.amountCollected, 0); 

      // 2. Team Stats (Filtered Scope & Date)
      let targetUserIds = new Set<string>();

      if (filterUser) {
          targetUserIds.add(filterUser);
      } else {
          // Use userOptions (which respects the filter hierarchy)
          userOptions.forEach(u => targetUserIds.add(u.id));
      }

      // Security: Only calculate for people I can see
      const validTargetIds = new Set([...targetUserIds].filter(id => displayUsers.some(u => u.id === id)));

      const teamRevenues = allRevenues.filter(r => validTargetIds.has(r.userId) && isInRange(r.date));
      const teamAppointments = allAppointments.filter(a => validTargetIds.has(a.userId) && isInRange(a.date));
      const teamTotalRevenue = teamRevenues.reduce((s, r) => s + r.amountCollected, 0);

      // 3. Chart Data
      const chartRevenues = [...myRevenues, ...teamRevenues];

      const monthlyData: Record<string, number> = {};
      chartRevenues.forEach(r => {
          const month = r.date.substring(0, 7);
          monthlyData[month] = (monthlyData[month] || 0) + r.amountCollected;
      });
      const chartData = Object.keys(monthlyData).sort().map(k => ({ name: k, revenue: monthlyData[k] }));

      // Analysis Text
      let conclusion = "Số liệu trong khoảng thời gian này.";
      if (chartData.length >= 2) {
          const last = chartData[chartData.length - 1].revenue;
          const prev = chartData[chartData.length - 2].revenue;
          const diff = last - prev;
          const percent = prev > 0 ? ((diff / prev) * 100).toFixed(1) : 100;
          if (diff > 0) conclusion = `Tháng ${chartData[chartData.length-1].name} tăng ${percent}% so với tháng trước trong phạm vi lọc.`;
          else if (diff < 0) conclusion = `Tháng ${chartData[chartData.length-1].name} giảm ${Math.abs(Number(percent))}% so với tháng trước.`;
      }

      // Top Companies
      const companyRevenueMap: Record<string, number> = {};
      chartRevenues.forEach(r => {
          let companyName = r.customerName;
          if (r.contractCode) {
              const proj = allProjects.find(p => p.contractCode === r.contractCode);
              if (proj && proj.companyName) companyName = proj.companyName;
              else if (proj && proj.customerName) companyName = proj.customerName;
          }
          if (!companyName) companyName = "Khách lẻ / Chưa cập nhật";
          companyRevenueMap[companyName] = (companyRevenueMap[companyName] || 0) + r.amountCollected;
      });

      const topCompanies = Object.entries(companyRevenueMap)
          .map(([name, value]) => ({ name, value }))
          .sort((a, b) => b.value - a.value)
          .slice(0, 10);

      return {
          personal: { revenue: myTotalRevenue, apps: myAppointments.length, user: manager },
          team: { revenue: teamTotalRevenue, apps: teamAppointments.length, count: validTargetIds.size },
          chartData,
          conclusion,
          topCompanies
      };

  }, [allRevenues, allAppointments, manager, filterUser, userOptions, displayUsers, allProjects, startDate, endDate]);

  // --- HELPER FOR ORG CHART ---
  const getCumulativeHeadcount = (deptId: string): number => {
      const uniqueUserIds = new Set<string>();
      const collectUsers = (currentDeptId: string) => {
          const currentDept = departments.find(d => d.id === currentDeptId);
          if (currentDept && currentDept.managerId) uniqueUserIds.add(currentDept.managerId);
          allUsers.filter(u => u.departmentId === currentDeptId).forEach(u => uniqueUserIds.add(u.id));
          departments.filter(d => d.parentId === currentDeptId).forEach(child => collectUsers(child.id));
      };
      collectUsers(deptId);
      return uniqueUserIds.size;
  };

  // Chat Logic (Improved Search)
  const chatUsers = useMemo(() => {
      let filtered = displayUsers;
      if (chatSearchTerm) {
          const term = chatSearchTerm.toLowerCase();
          filtered = filtered.filter(u => 
              u.name.toLowerCase().includes(term) || 
              u.id.toLowerCase().includes(term) || 
              (u.phone && u.phone.includes(term))
          );
      }
      if (chatFilterRole) filtered = filtered.filter(u => u.role === chatFilterRole);
      return filtered;
  }, [displayUsers, chatSearchTerm, chatFilterRole]);

  const currentConversation = useMemo(() => {
      if (!selectedChatUser) return [];
      return allMessages.filter(m => 
          (m.senderId === manager.id && m.receiverId === selectedChatUser) ||
          (m.senderId === selectedChatUser && m.receiverId === manager.id)
      ).sort((a,b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
  }, [allMessages, selectedChatUser, manager.id]);

  const handleAdminReply = async () => {
      if (!selectedChatUser || !adminChatInput.trim()) return;
      await storageService.sendMessage({ id: `MSG${Date.now()}`, senderId: manager.id, senderName: manager.name, receiverId: selectedChatUser, content: adminChatInput, timestamp: new Date().toISOString(), isRead: false });
      setAdminChatInput(''); 
      silentRefreshMsg();
  };

  const handleSendMessage = async () => {
      if (!msgContent) return;
      let receiverIds: string[] = [];

      if (msgTargetType === 'ALL') {
          receiverIds = displayUsers.map(u => u.id);
      } else if (msgTargetType === 'USER') {
          if (msgTargetId) receiverIds = [msgTargetId];
      } else if (msgTargetType === 'DEPT') {
          if (msgTargetId) {
             const targetDeptIds = new Set<string>();
             const collectDepts = (dId: string) => {
                 targetDeptIds.add(dId);
                 departments.filter(d => d.parentId === dId).forEach(c => collectDepts(c.id));
             };
             collectDepts(msgTargetId);

             // Reuse the displayUsers (which are already my strict subordinates)
             // to find who belongs to these depts
             displayUsers.forEach(u => {
                 if (u.departmentId && targetDeptIds.has(u.departmentId)) {
                     receiverIds.push(u.id);
                 }
                 // Add logic if manager of sub-dept is also needed, but displayUsers covers them
             });
             receiverIds = [...new Set(receiverIds)];
          }
      }

      if (receiverIds.length === 0) return alert("Không tìm thấy người nhận phù hợp!");

      await storageService.sendMessage({ 
          id: `MSG${Date.now()}`, 
          senderId: manager.id, 
          senderName: manager.name, 
          receiverId: receiverIds, 
          content: msgContent, 
          timestamp: new Date().toISOString(), 
          isRead: false 
      });

      alert(`Đã gửi thông báo thành công cho ${receiverIds.length} nhân sự!`); 
      setMsgModalOpen(false); 
      setMsgContent('');
      silentRefreshMsg();
  };

  const calculateTotalRevenue = (user: User) => {
      const earned = allRevenues.filter(r => r.userId === user.id).reduce((s, r) => s + r.amountCollected, 0);
      return earned + (user.initialRevenue || 0);
  };

  const openAddUser = () => { setEditingUserId(null); setFormUser({ role: UserRole.EMPLOYEE, initialRevenue: 0, managerId: manager.id }); setUserModalOpen(true); };
  const openEditUser = (user: User) => { setEditingUserId(user.id); setFormUser({ ...user }); setUserModalOpen(true); };
  const handleSubmitUser = async () => {
    if (!formUser.id || !formUser.name || !formUser.password) return alert("Vui lòng điền đủ thông tin");
    const targetRank = ROLE_RANK[formUser.role as UserRole];
    if (targetRank > myRank) return alert("Cấp bậc không hợp lệ.");

    const isManagerRole = [UserRole.REGIONAL_MANAGER, UserRole.GROUP_MANAGER, UserRole.MANAGER, UserRole.TEAM_LEADER].includes(formUser.role as UserRole);

    try {
        let finalDeptId = formUser.departmentId;

        if (isManagerRole && formUser.newDeptName && formUser.newDeptParentId) {
             const deptLevel = (() => {
                switch(formUser.role) {
                    case UserRole.REGIONAL_MANAGER: return DepartmentLevel.REGION;
                    case UserRole.GROUP_MANAGER: return DepartmentLevel.GROUP;
                    case UserRole.MANAGER: return DepartmentLevel.DEPARTMENT;
                    case UserRole.TEAM_LEADER: return DepartmentLevel.TEAM;
                    default: return null;
                }
             })();
             const newDeptId = `${deptLevel?.substring(0,3).toUpperCase()}_${formUser.id}`; 
             await storageService.addDepartment({
                 id: newDeptId,
                 name: formUser.newDeptName,
                 level: deptLevel!,
                 managerId: formUser.id,
                 managerName: formUser.name,
                 parentId: formUser.newDeptParentId
             });
             finalDeptId = newDeptId; 
        } else if (isManagerRole && !editingUserId) {
            if (!formUser.departmentId && !formUser.newDeptName) return alert("Với vai trò quản lý, vui lòng tạo đơn vị quản lý hoặc chọn đơn vị.");
        }

        const userData = { ...formUser, departmentId: finalDeptId };
        delete userData.newDeptName;
        delete userData.newDeptParentId;

        if (editingUserId) await storageService.updateUser(userData as User);
        else await storageService.addUser({ ...userData, managerId: manager.id } as User);

        await refreshData(); setUserModalOpen(false);
    } catch (e: any) { alert(e.message); }
