import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { Users, TrendingUp, Calendar, Edit, Trash2, Eye, ArrowLeft, Send, MessageSquare, Search, LayoutGrid, Loader2, GitMerge, CornerDownRight, CheckCircle, Filter, Briefcase, Building2, Crown, UserCircle, Users as UsersIcon, X, ChevronRight } from 'lucide-react';
