import { db } from './firebaseConfig';
import { collection, getDocs, doc, setDoc, updateDoc, deleteDoc, query, where, getDoc, writeBatch } from 'firebase/firestore';
import { User, Department, Appointment, Consultation, Revenue, RevenueType, ProjectProfile, Message, UserRole, DepartmentLevel } from '../types';

// Collection Names in Firestore
const COLS = {
  USERS: 'users',
  DEPTS: 'departments',
  APPS: 'appointments',
  CONSULTS: 'consultations',
  REVENUES: 'revenues',
  PROJECTS: 'projects',
  MESSAGES: 'messages'
};

// Helper to map Firestore docs to our types
const mapDoc = (doc: any) => ({ ...doc.data(), id: doc.id });

export const storageService = {
  // --- Auth & System Init ---

  // Check and seed default admin if system is empty
  initializeSystem: async () => {
    try {
        // Check specifically for ADMIN to ensure credentials
        const adminRef = doc(db, COLS.USERS, 'ADMIN');
        const adminSnap = await getDoc(adminRef);

        const adminData: User = {
            id: 'ADMIN',
            name: 'Administrator',
            role: UserRole.DIRECTOR,
            password: 'caofi17', // Updated Password
            joinDate: new Date().toISOString(),
            initialRevenue: 0
        };

        if (!adminSnap.exists()) {
            console.log("Seeding default Admin...");
            await setDoc(adminRef, adminData);

            const hqRef = doc(db, COLS.DEPTS, 'HQ');
            const hqSnap = await getDoc(hqRef);
            if (!hqSnap.exists()) {
                await setDoc(hqRef, {
                    id: 'HQ',
                    name: 'Trụ sở chính',
                    managerName: 'Administrator',
                    managerId: 'ADMIN',
                    level: DepartmentLevel.HQ,
                    parentId: null
                });
            }
        } else {
            // Force update password if it doesn't match the new one
            const currentData = adminSnap.data();
            if (currentData.password !== 'caofi17') {
                console.log("Updating Admin password to new policy...");
                await updateDoc(adminRef, { password: 'caofi17' });
            }

            // Ensure HQ has level info (migration for existing data)
            const hqRef = doc(db, COLS.DEPTS, 'HQ');
            const hqSnap = await getDoc(hqRef);
            if (hqSnap.exists()) {
                const hqData = hqSnap.data();
                if (!hqData.level) {
                     await updateDoc(hqRef, { level: DepartmentLevel.HQ, parentId: null, managerId: 'ADMIN' });
                }
            }
        }
    } catch (error) {
        console.error("Init Error:", error);
    }
  },

  login: async (code: string, password?: string): Promise<User | null> => {
    try {
        // Ensure system is initialized
        await storageService.initializeSystem();

        const docRef = doc(db, COLS.USERS, code);
        const docSnap = await getDoc(docRef);

        if (docSnap.exists()) {
            const user = mapDoc(docSnap) as User;
            // Simple password check (In production, use Firebase Auth or Hash)
            if (user.password === password || (!user.password && !password)) {
                localStorage.setItem('sf_current_user_id', user.id); // Keep session locally
                return user;
            }
        }
        return null;
    } catch (e) {
        console.error("Login Error:", e);
        return null;
    }
  },

  logout: () => {
    localStorage.removeItem('sf_current_user_id');
  },

  getCurrentUser: async (): Promise<User | null> => {
      const id = localStorage.getItem('sf_current_user_id');
      if (!id) return null;
      const docSnap = await getDoc(doc(db, COLS.USERS, id));
      return docSnap.exists() ? (mapDoc(docSnap) as User) : null;
  },

  // --- CRUD Standard (Now Async) ---

  // DEPARTMENTS
  getDepartments: async (): Promise<Department[]> => {
      const snap = await getDocs(collection(db, COLS.DEPTS));
      return snap.docs.map(d => mapDoc(d) as Department);
  },
  addDepartment: async (item: Department) => {
      await setDoc(doc(db, COLS.DEPTS, item.id), item);
  },
  updateDepartment: async (item: Department) => {
      await updateDoc(doc(db, COLS.DEPTS, item.id), { ...item });
  },
  // NEW: Migrate Department ID and Cascade Update Children
  migrateDepartmentId: async (oldId: string, newDeptData: Department) => {
      const batch = writeBatch(db);

      // 1. Create New Department
      const newDeptRef = doc(db, COLS.DEPTS, newDeptData.id);
      batch.set(newDeptRef, newDeptData);

      // 2. Find and Update Child Departments (where parentId == oldId)
      const childDeptQuery = query(collection(db, COLS.DEPTS), where("parentId", "==", oldId));
      const childDeptSnap = await getDocs(childDeptQuery);
      childDeptSnap.forEach((doc) => {
          batch.update(doc.ref, { parentId: newDeptData.id });
      });

      // 3. Find and Update Users (where departmentId == oldId)
      const usersQuery = query(collection(db, COLS.USERS), where("departmentId", "==", oldId));
      const usersSnap = await getDocs(usersQuery);
      usersSnap.forEach((doc) => {
          batch.update(doc.ref, { departmentId: newDeptData.id });
      });

      // 4. Delete Old Department
      const oldDeptRef = doc(db, COLS.DEPTS, oldId);
      batch.delete(oldDeptRef);

      // Commit all changes
      await batch.commit();
  },
  deleteDepartment: async (id: string) => {
      await deleteDoc(doc(db, COLS.DEPTS, id));
  },

  // USERS
  getUsers: async (): Promise<User[]> => {
      const snap = await getDocs(collection(db, COLS.USERS));
      return snap.docs.map(d => mapDoc(d) as User);
  },

  // Get Subordinates recursively (Requires fetching all users first - client side filtering for tree)
  getSubordinates: async (managerId: string): Promise<User[]> => {
      const allUsers = await storageService.getUsers();
      const result: User[] = [];

      const findDirectReports = (id: string) => {
          const directReports = allUsers.filter(u => u.managerId === id);
          for (const report of directReports) {
              result.push(report);
              findDirectReports(report.id);
          }
      };

      findDirectReports(managerId);
      return result;
  },

  addUser: async (item: User) => {
      const check = await getDoc(doc(db, COLS.USERS, item.id));
      if (check.exists()) throw new Error("Mã nhân viên đã tồn tại");
      await setDoc(doc(db, COLS.USERS, item.id), item);
  },
  updateUser: async (item: User) => {
      await updateDoc(doc(db, COLS.USERS, item.id), { ...item });
  },
  deleteUser: async (id: string) => {
      if (id === 'ADMIN') throw new Error("Không thể xóa Admin chính");
      await deleteDoc(doc(db, COLS.USERS, id));
  },

  // APPOINTMENTS
  getAppointments: async (): Promise<Appointment[]> => {
      const snap = await getDocs(collection(db, COLS.APPS));
      return snap.docs.map(d => mapDoc(d) as Appointment);
  },
  addAppointment: async (item: Appointment) => {
      await setDoc(doc(db, COLS.APPS, item.id), item);
  },
  updateAppointment: async (item: Appointment) => {
      await updateDoc(doc(db, COLS.APPS, item.id), { ...item });
  },
  deleteAppointment: async (id: string) => {
      await deleteDoc(doc(db, COLS.APPS, id));
  },

  // CONSULTATIONS
  getConsultations: async (): Promise<Consultation[]> => {
      const snap = await getDocs(collection(db, COLS.CONSULTS));
      return snap.docs.map(d => mapDoc(d) as Consultation);
  },
  addConsultation: async (item: Consultation) => {
      await setDoc(doc(db, COLS.CONSULTS, item.id), item);
  },
  updateConsultation: async (item: Consultation) => {
      await updateDoc(doc(db, COLS.CONSULTS, item.id), { ...item });
  },
  deleteConsultation: async (id: string) => {
      await deleteDoc(doc(db, COLS.CONSULTS, id));
  },

  // REVENUES
  getRevenues: async (): Promise<Revenue[]> => {
      const snap = await getDocs(collection(db, COLS.REVENUES));
      return snap.docs.map(d => mapDoc(d) as Revenue);
  },
  addRevenue: async (item: Revenue) => {
      await setDoc(doc(db, COLS.REVENUES, item.id), item);

      // Auto-create Project Profile if NEW contract
      if (item.type === RevenueType.NEW) {
          const q = query(collection(db, COLS.PROJECTS), where("contractCode", "==", item.contractCode));
          const querySnapshot = await getDocs(q);
          if (querySnapshot.empty) {
              await storageService.addProject({
                  contractCode: item.contractCode,
                  userId: item.userId,
                  status: 'Mới'
              });
          }
      }
  },
  updateRevenue: async (item: Revenue) => {
      await updateDoc(doc(db, COLS.REVENUES, item.id), { ...item });
  },
  deleteRevenue: async (id: string) => {
      await deleteDoc(doc(db, COLS.REVENUES, id));
  },

  // PROJECT PROFILES
  getProjects: async (): Promise<ProjectProfile[]> => {
      const snap = await getDocs(collection(db, COLS.PROJECTS));
      return snap.docs.map(d => mapDoc(d) as ProjectProfile);
  },
  addProject: async (item: ProjectProfile) => {
      // Use contractCode as ID for uniqueness check
      // But contractCode might change? Better to use a separate ID or ensure code is unique.
      // For now, let's query first.
      const q = query(collection(db, COLS.PROJECTS), where("contractCode", "==", item.contractCode));
      const querySnapshot = await getDocs(q);

      if (querySnapshot.empty) {
          // Create a safe ID from contract code or random
          const safeId = `PROJ_${item.contractCode.replace(/\W/g, '')}_${Date.now()}`;
          await setDoc(doc(db, COLS.PROJECTS, safeId), item);
      }
  },
  updateProject: async (item: ProjectProfile) => {
      // Need to find the doc ID by contractCode first, because we don't store doc ID in item usually
      const q = query(collection(db, COLS.PROJECTS), where("contractCode", "==", item.contractCode));
      const snap = await getDocs(q);
      if (!snap.empty) {
          const docId = snap.docs[0].id;
          await updateDoc(doc(db, COLS.PROJECTS, docId), { ...item });
      }
  },

  // MESSAGES
  getMessages: async (): Promise<Message[]> => {
      const snap = await getDocs(collection(db, COLS.MESSAGES));
      return snap.docs.map(d => mapDoc(d) as Message);
  },
  sendMessage: async (msg: Message) => {
      await setDoc(doc(db, COLS.MESSAGES, msg.id), msg);
  },
  markMessageRead: async (msgId: string) => {
      await updateDoc(doc(db, COLS.MESSAGES, msgId), { isRead: true });
  },

  // --- Helpers (Mixed Logic) ---
  findGlobalAppointmentByPhone: async (phone: string): Promise<{ appointment: Appointment, creatorName: string } | null> => {
    const q = query(collection(db, COLS.APPS), where("phone", "==", phone));
    const snap = await getDocs(q);
    const apps = snap.docs.map(d => mapDoc(d) as Appointment);

    // Sort logic client side for now
    const found = apps.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0];

    if (found) {
        const userDoc = await getDoc(doc(db, COLS.USERS, found.userId));
        const creator = userDoc.exists() ? (userDoc.data() as User) : null;
        return { appointment: found, creatorName: creator ? creator.name : found.userId };
    }
    return null;
  },

  findTeamDuplicate: async (phone: string, currentUserId: string): Promise<{ name: string, role: string } | null> => {
      const currentUserDoc = await getDoc(doc(db, COLS.USERS, currentUserId));
      if (!currentUserDoc.exists()) return null;
      const currentUser = currentUserDoc.data() as User;
      if (!currentUser.managerId) return null;

      // Get team members
      const usersQ = query(collection(db, COLS.USERS), where("managerId", "==", currentUser.managerId));
      const usersSnap = await getDocs(usersQ);
      const teamMembers = usersSnap.docs.map(d => mapDoc(d) as User).filter(u => u.id !== currentUserId);
      const teamIds = teamMembers.map(u => u.id);

      if (teamIds.length === 0) return null;

      // Check Appointments
      const appsSnap = await getDocs(query(collection(db, COLS.APPS), where("phone", "==", phone)));
      const apps = appsSnap.docs.map(d => mapDoc(d) as Appointment).filter(a => teamIds.includes(a.userId));

      if (apps.length > 0) {
          const owner = teamMembers.find(u => u.id === apps[0].userId);
          if (owner) return { name: owner.name, role: 'Hẹn' };
      }

      // Check Consultations
      const consSnap = await getDocs(query(collection(db, COLS.CONSULTS), where("phone", "==", phone)));
      const cons = consSnap.docs.map(d => mapDoc(d) as Consultation).filter(c => teamIds.includes(c.userId));

      if (cons.length > 0) {
           const owner = teamMembers.find(u => u.id === cons[0].userId);
           if (owner) return { name: owner.name, role: 'Tư vấn' };
      }

      return null;
  },

  findCustomerByPhone: async (phone: string) => {
      // Check Project Profile first
      const projSnap = await getDocs(query(collection(db, COLS.PROJECTS), where("phone", "==", phone)));
      if (!projSnap.empty) {
          const proj = mapDoc(projSnap.docs[0]) as ProjectProfile;
          return { 
              name: proj.customerName || '', 
              company: proj.companyName || '', 
              address: proj.address || '', 
              source: proj.source || '',
              contractCode: proj.contractCode, 
              city: proj.region || '' 
          };
      }

      // Check Appointments
      const appSnap = await getDocs(query(collection(db, COLS.APPS), where("phone", "==", phone)));
      if (!appSnap.empty) {
          const app = mapDoc(appSnap.docs[0]) as Appointment;
          return { 
            name: app.customerName, 
            company: app.companyName, 
            address: app.addressDetail, 
            source: app.source,
            city: app.location 
          };
      }

      // Check Consults
      const conSnap = await getDocs(query(collection(db, COLS.CONSULTS), where("phone", "==", phone)));
      if (!conSnap.empty) {
          const cons = mapDoc(conSnap.docs[0]) as Consultation;
          return { 
            name: cons.customerName, 
            company: cons.companyName, 
            address: cons.addressDetail, 
            source: cons.source,
            city: '' 
          };
      }

      return null;
  },

  getContractCandidatesForHandover: async (userId: string): Promise<Revenue[]> => {
    const q = query(collection(db, COLS.REVENUES), where("userId", "==", userId), where("type", "==", RevenueType.NEW));
    const snap = await getDocs(q);
    return snap.docs.map(d => mapDoc(d) as Revenue);
  }
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { storageService } from '../services/storageService';
import { User, Department, Appointment, Revenue, Message, UserRole, ROLE_RANK, ROLE_LABELS, DepartmentLevel, ProjectProfile } from '../types';
import { Button, Input, Modal, Select, Card, Badge, Combobox } from '../components/ui';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { Users, TrendingUp, Calendar, Edit, Trash2, Eye, ArrowLeft, Send, MessageSquare, Search, LayoutGrid, Loader2, GitMerge, CornerDownRight, CheckCircle, Filter, Briefcase, Building2, Crown, UserCircle, Users as UsersIcon, X, ChevronRight, Trophy, AlertTriangle, RotateCcw, ShieldAlert } from 'lucide-react';
import { EmployeeDashboard } from './EmployeeDashboard';

interface AdminDashboardProps {
    currentUser: User; 
}

// Helper interface for tree structure
interface StructuredUser extends User {
    _depth: number;
    _isManager?: boolean;
    _deptName?: string;
}

// Helper function moved outside component
const getDeptWeight = (level?: DepartmentLevel) => {
    switch(level) {
        case DepartmentLevel.HQ: return 5;
        case DepartmentLevel.REGION: return 4;
        case DepartmentLevel.GROUP: return 3;
        case DepartmentLevel.DEPARTMENT: return 2;
        case DepartmentLevel.TEAM: return 1;
        default: return 0;
    }
};

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser }) => {
  const manager = currentUser;
  const [loading, setLoading] = useState(true);

  // Tabs state
  const [activeTab, setActiveTab] = useState<'personal' | 'dashboard' | 'staff' | 'depts' | 'chat'>('dashboard');

  const [departments, setDepartments] = useState<Department[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [allRevenues, setAllRevenues] = useState<Revenue[]>([]);
  const [allAppointments, setAllAppointments] = useState<Appointment[]>([]);
  const [allProjects, setAllProjects] = useState<ProjectProfile[]>([]);

  // --- TOP 10 TAB STATE ---
  const [top10Tab, setTop10Tab] = useState<'COMPANY' | 'REGION'>('REGION');

  // --- DELETE UNDO STATE ---
  // Fix: Removed timerId from state as we now use useEffect for sequencing
  const [undoState, setUndoState] = useState<{ id: string } | null>(null);
  const [undoCountDown, setUndoCountDown] = useState(0);

  // --- DATE FILTER STATE (Default: Current Month) ---
  const [startDate, setStartDate] = useState(() => {
      const date = new Date();
      return new Date(date.getFullYear(), date.getMonth(), 1).toISOString().split('T')[0];
  });
  const [endDate, setEndDate] = useState(() => {
      const date = new Date();
      return new Date(date.getFullYear(), date.getMonth() + 1, 0).toISOString().split('T')[0];
  });

  // --- MULTI-LEVEL FILTER STATE ---
  const [filterRegion, setFilterRegion] = useState('');
  const [filterGroup, setFilterGroup] = useState('');
  const [filterDept, setFilterDept] = useState('');
  const [filterTeam, setFilterTeam] = useState('');
  const [filterUser, setFilterUser] = useState('');
  const [filterRole, setFilterRole] = useState(''); // NEW ROLE FILTER

  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [selectedChatUser, setSelectedChatUser] = useState<string | null>(null);
  const [adminChatInput, setAdminChatInput] = useState('');
  const [chatSearchTerm, setChatSearchTerm] = useState('');
  const [chatFilterRole, setChatFilterRole] = useState<string>('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const [isMsgModalOpen, setMsgModalOpen] = useState(false);
  const [msgContent, setMsgContent] = useState('');
  const [msgTargetType, setMsgTargetType] = useState<'ALL' | 'DEPT' | 'USER'>('ALL');
  const [msgTargetId, setMsgTargetId] = useState('');

  const [isUserModalOpen, setUserModalOpen] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [formUser, setFormUser] = useState<Partial<User> & { 
      newDeptName?: string, 
      newDeptParentId?: string 
  }>({});

  const [isDeptModalOpen, setDeptModalOpen] = useState(false);
  const [editingDeptId, setEditingDeptId] = useState<string | null>(null);
  const [formDept, setFormDept] = useState<Partial<Department>>({ level: DepartmentLevel.DEPARTMENT });

  const [viewingUser, setViewingUser] = useState<User | null>(null);

  const myRank = ROLE_RANK[manager.role];
  // Director (Rank 6) always has full edit rights. Others need Rank >= 4
  const canEditStructure = myRank >= 4;

  const refreshData = async () => {
      setLoading(true);
      try {
          const [u, d, r, a, m, p] = await Promise.all([
              storageService.getUsers(),
              storageService.getDepartments(),
              storageService.getRevenues(),
              storageService.getAppointments(),
              storageService.getMessages(),
              storageService.getProjects()
          ]);
          setAllUsers(u);
          setDepartments(d);
          setAllRevenues(r);
          setAllAppointments(a);
          setAllMessages(m);
          setAllProjects(p);
      } catch (error) {
          console.error("Failed to load data", error);
      } finally {
          setLoading(false);
      }
  };

  const silentRefreshMsg = async () => {
      const m = await storageService.getMessages();
      setAllMessages(m);
  };

  useEffect(() => {
     refreshData();
     const interval = setInterval(() => {
         silentRefreshMsg();
     }, 10000); 
     return () => clearInterval(interval);
  }, []);

  // UNDO TIMER & EXECUTION EFFECT
  useEffect(() => {
      if (!undoState) return;

      if (undoCountDown > 0) {
          const timer = setTimeout(() => setUndoCountDown(c => c - 1), 1000);
          return () => clearTimeout(timer);
      } else {
          // Fix: Execute delete strictly when countdown hits 0
          const executeDelete = async () => {
              try {
                  await storageService.deleteDepartment(undoState.id);
                  // Refresh ONLY after delete is confirmed finished
                  await refreshData();
              } catch(e: any) {
                  alert("Lỗi xóa: " + e.message);
              } finally {
                  setUndoState(null);
              }
          };
          executeDelete();
      }
  }, [undoCountDown, undoState]);

  useEffect(() => {
     if(activeTab === 'chat' && selectedChatUser) {
         chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
     }
  }, [allMessages, selectedChatUser, activeTab]);

  // --- STRICT SUBORDINATE LOGIC ---
  const mySubordinates = useMemo(() => {
      if (manager.role === UserRole.DIRECTOR) {
          return allUsers; 
      }

      if (myRank <= 1) return [manager];

      const visibleUserIds = new Set<string>();
      const managedDeptIds = new Set<string>();

      const directDepts = departments.filter(d => d.managerId === manager.id);

      const deptQueue = [...directDepts];
      while (deptQueue.length > 0) {
          const curr = deptQueue.pop()!;
          managedDeptIds.add(curr.id);
          const children = departments.filter(d => d.parentId === curr.id);
          deptQueue.push(...children);
      }

      allUsers.forEach(u => {
          if (u.departmentId && managedDeptIds.has(u.departmentId)) {
               if (u.id !== manager.id) visibleUserIds.add(u.id);
          }
      });

      departments.forEach(d => {
          if (managedDeptIds.has(d.id) && d.managerId && d.managerId !== manager.id) {
              visibleUserIds.add(d.managerId);
          }
      });

      const result = allUsers.filter(u => visibleUserIds.has(u.id));
      return [manager, ...result];
  }, [allUsers, departments, manager, myRank]);

  // --- TREE SORT LOGIC (HIERARCHICAL) ---
  const structuredUsers = useMemo(() => {
      if (mySubordinates.length <= 1) return []; 

      const result: StructuredUser[] = [];
      const processedUserIds = new Set<string>();

      const traverse = (deptId: string, depth: number) => {
          const dept = departments.find(d => d.id === deptId);
          if (!dept) return;

          if (dept.managerId && dept.managerId !== manager.id && !processedUserIds.has(dept.managerId)) {
              const mgr = mySubordinates.find(u => u.id === dept.managerId);
              if (mgr) {
                  result.push({ ...mgr, _depth: depth, _isManager: true, _deptName: dept.name });
                  processedUserIds.add(mgr.id);
              }
          }

          const employees = mySubordinates.filter(u => 
              u.departmentId === deptId && 
              u.id !== dept.managerId && 
              u.id !== manager.id &&
              !processedUserIds.has(u.id)
          ).sort((a, b) => a.name.localeCompare(b.name));

          employees.forEach(emp => {
              result.push({ ...emp, _depth: depth + 1, _isManager: false, _deptName: dept.name });
              processedUserIds.add(emp.id);
          });

          const subDepts = departments
              .filter(d => d.parentId === deptId)
              .sort((a, b) => (getDeptWeight(b.level) - getDeptWeight(a.level)) || a.name.localeCompare(b.name));

          subDepts.forEach(sub => traverse(sub.id, depth + 1));
      };

      const rootDepts = departments.filter(d => d.managerId === manager.id);

      if (rootDepts.length > 0) {
          rootDepts.forEach(d => traverse(d.id, 0));
      } else {
          if (manager.role === UserRole.DIRECTOR) {
               const hq = departments.find(d => d.level === DepartmentLevel.HQ);
               if(hq) traverse(hq.id, 0);
          }
      }

      const orphans = mySubordinates.filter(u => !processedUserIds.has(u.id) && u.id !== manager.id);
      orphans.forEach(u => result.push({ ...u, _depth: 0, _isManager: false, _deptName: 'Chưa phân bổ / Khác' }));

      return result;
  }, [mySubordinates, departments, manager]);

  // --- HIERARCHY FILTER LOGIC ---
  const regionOptions = useMemo(() => departments.filter(d => d.level === DepartmentLevel.REGION), [departments]);
  const groupOptions = useMemo(() => !filterRegion ? [] : departments.filter(d => d.level === DepartmentLevel.GROUP && d.parentId === filterRegion), [departments, filterRegion]);
  const deptOptions = useMemo(() => !filterGroup ? [] : departments.filter(d => d.level === DepartmentLevel.DEPARTMENT && d.parentId === filterGroup), [departments, filterGroup]);
  const teamOptions = useMemo(() => !filterDept ? [] : departments.filter(d => d.level === DepartmentLevel.TEAM && d.parentId === filterDept), [departments, filterDept]);

  useEffect(() => { setFilterGroup(''); setFilterDept(''); setFilterTeam(''); setFilterUser(''); }, [filterRegion]);
  useEffect(() => { setFilterDept(''); setFilterTeam(''); setFilterUser(''); }, [filterGroup]);
  useEffect(() => { setFilterTeam(''); setFilterUser(''); }, [filterDept]);
  useEffect(() => { setFilterUser(''); }, [filterTeam]);

  // --- HELPER: CHECK DATE RANGE ---
  const isInRange = (dateStr: string) => {
      if (!dateStr) return false;
      const d = dateStr.split('T')[0];
      return d >= startDate && d <= endDate;
  };

  // --- DASHBOARD DATA CALCULATION ---
  const dashboardStats = useMemo(() => {
      // 1. Personal Stats
      const myRevenues = allRevenues.filter(r => r.userId === manager.id && isInRange(r.date));
      const myAppointments = allAppointments.filter(a => a.userId === manager.id && isInRange(a.date));
      const myTotalRevenue = myRevenues.reduce((s, r) => s + r.amountCollected, 0); 

      // 2. Team Stats
      let targetUserIds = new Set<string>();
      if (filterUser) {
          targetUserIds.add(filterUser);
      } else {
          const scopeId = filterTeam || filterDept || filterGroup || filterRegion;
          if (scopeId) {
             const getRecursive = (dId: string) => {
                 const d = departments.find(x => x.id === dId);
                 if(d && d.managerId && d.managerId !== manager.id) targetUserIds.add(d.managerId);
                 allUsers.filter(u => u.departmentId === dId && u.id !== manager.id).forEach(u => targetUserIds.add(u.id));
                 departments.filter(x => x.parentId === dId).forEach(child => getRecursive(child.id));
             };
             getRecursive(scopeId);
          } else {
             mySubordinates.forEach(u => { if(u.id !== manager.id) targetUserIds.add(u.id); });
          }
      }

      const validTargetIds = new Set([...targetUserIds]); 
      const teamRevenues = allRevenues.filter(r => validTargetIds.has(r.userId) && isInRange(r.date));
      const teamAppointments = allAppointments.filter(a => validTargetIds.has(a.userId) && isInRange(a.date));
      const teamTotalRevenue = teamRevenues.reduce((s, r) => s + r.amountCollected, 0);

      // 3. Chart Data
      const chartRevenues = [...myRevenues, ...teamRevenues];
      const monthlyData: Record<string, number> = {};
      chartRevenues.forEach(r => {
          const month = r.date.substring(0, 7);
          monthlyData[month] = (monthlyData[month] || 0) + r.amountCollected;
      });
      const chartData = Object.keys(monthlyData).sort().map(k => ({ name: k, revenue: monthlyData[k] }));

      let conclusion = "Số liệu trong khoảng thời gian này.";
      if (chartData.length >= 2) {
          const last = chartData[chartData.length - 1].revenue;
          const prev = chartData[chartData.length - 2].revenue;
          const diff = last - prev;
          const percent = prev > 0 ? ((diff / prev) * 100).toFixed(1) : 100;
          if (diff > 0) conclusion = `Tháng ${chartData[chartData.length-1].name} tăng ${percent}% so với tháng trước.`;
          else if (diff < 0) conclusion = `Tháng ${chartData[chartData.length-1].name} giảm ${Math.abs(Number(percent))}% so với tháng trước.`;
      }

      const empRevMapGlobal: Record<string, number> = {};
      allRevenues.filter(r => isInRange(r.date)).forEach(r => {
          empRevMapGlobal[r.userId] = (empRevMapGlobal[r.userId] || 0) + r.amountCollected;
      });
      const topEmployeesGlobal = Object.entries(empRevMapGlobal)
        .map(([uid, val]) => ({ name: allUsers.find(u => u.id === uid)?.name || uid, value: val, id: uid }))
        .sort((a,b) => b.value - a.value)
        .slice(0, 10);

      const empRevMapLocal: Record<string, number> = {};
      teamRevenues.forEach(r => {
          empRevMapLocal[r.userId] = (empRevMapLocal[r.userId] || 0) + r.amountCollected;
      });
      if (!filterUser) {
           myRevenues.forEach(r => empRevMapLocal[r.userId] = (empRevMapLocal[r.userId] || 0) + r.amountCollected);
      }

      const topEmployeesLocal = Object.entries(empRevMapLocal)
        .map(([uid, val]) => ({ name: allUsers.find(u => u.id === uid)?.name || uid, value: val, id: uid }))
        .sort((a,b) => b.value - a.value)
        .slice(0, 10);

      return {
          personal: { revenue: myTotalRevenue, apps: myAppointments.length, user: manager },
          team: { revenue: teamTotalRevenue, apps: teamAppointments.length, count: validTargetIds.size },
          chartData, conclusion, topEmployeesGlobal, topEmployeesLocal
      };

  }, [allRevenues, allAppointments, manager, filterUser, filterTeam, filterDept, filterGroup, filterRegion, mySubordinates, startDate, endDate, allUsers]);

  const getCumulativeHeadcount = (deptId: string): number => {
      const uniqueUserIds = new Set<string>();
      const collectUsers = (currentDeptId: string) => {
          const currentDept = departments.find(d => d.id === currentDeptId);
          if (currentDept && currentDept.managerId) uniqueUserIds.add(currentDept.managerId);
          allUsers.filter(u => u.departmentId === currentDeptId).forEach(u => uniqueUserIds.add(u.id));
          departments.filter(d => d.parentId === currentDeptId).forEach(child => collectUsers(child.id));
      };
      collectUsers(deptId);
      return uniqueUserIds.size;
  };

  // Chat Logic (Enhanced Search)
  const chatUsers = useMemo(() => {
      let filtered = mySubordinates.filter(u => u.id !== manager.id);
      if (chatSearchTerm) {
          const term = chatSearchTerm.toLowerCase();
          filtered = filtered.filter(u => 
              u.name.toLowerCase().includes(term) || 
              u.id.toLowerCase().includes(term) || 
              (u.phone && u.phone.includes(term))
          );
      }
      if (chatFilterRole) filtered = filtered.filter(u => u.role === chatFilterRole);
      return filtered;
  }, [mySubordinates, chatSearchTerm, chatFilterRole, manager.id]);

  const currentConversation = useMemo(() => {
      if (!selectedChatUser) return [];

      return allMessages.filter(m => {
          // STRICT FILTER: Only show messages where I am the sender or receiver
          // AND the other party is the selected user.

          const isMeSender = m.senderId === manager.id;
          // If I am Director, I also receive messages sent to 'ADMIN'
          const isMeReceiver = m.receiverId === manager.id || (manager.role === UserRole.DIRECTOR && m.receiverId === 'ADMIN');

          const isOtherSender = m.senderId === selectedChatUser;
          const isOtherReceiver = m.receiverId === selectedChatUser;

          // Case A: I sent to Them
          if (isMeSender && isOtherReceiver) return true;
          // Case B: They sent to Me (or to ADMIN if I am Director)
          if (isOtherSender && isMeReceiver) return true;

          return false;
      }).sort((a,b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
  }, [allMessages, selectedChatUser, manager.id, manager.role]);

  const handleAdminReply = async () => {
      if (!selectedChatUser || !adminChatInput.trim()) return;

      const newMsg: Message = { 
          id: `MSG${Date.now()}`, 
          senderId: manager.id, 
          senderName: manager.name, 
          receiverId: selectedChatUser, 
          content: adminChatInput, 
          timestamp: new Date().toISOString(), 
          isRead: false 
      };

      setAllMessages(prev => [...prev, newMsg]);
      setAdminChatInput('');
      await storageService.sendMessage(newMsg);
  };

  const handleSendMessage = async () => {
      if (!msgContent) return;
      let receiverIds: string[] = [];

      if (msgTargetType === 'ALL') {
          receiverIds = mySubordinates.filter(u => u.id !== manager.id).map(u => u.id);
      } else if (msgTargetType === 'USER') {
          if (msgTargetId) receiverIds = [msgTargetId];
      } else if (msgTargetType === 'DEPT') {
          if (msgTargetId) {
             const targetDeptIds = new Set<string>();
             const collectDepts = (dId: string) => {
                 targetDeptIds.add(dId);
                 departments.filter(d => d.parentId === dId).forEach(c => collectDepts(c.id));
             };
             collectDepts(msgTargetId);
             mySubordinates.forEach(u => {
                 if (u.departmentId && targetDeptIds.has(u.departmentId) && u.id !== manager.id) {
                     receiverIds.push(u.id);
                 }
                 departments.forEach(d => { if(targetDeptIds.has(d.id) && d.managerId && d.managerId !== manager.id) receiverIds.push(d.managerId); });
             });
             receiverIds = [...new Set(receiverIds)];
          }
      }

      if (receiverIds.length === 0) return alert("Không tìm thấy người nhận phù hợp!");

      await storageService.sendMessage({ 
          id: `MSG${Date.now()}`, 
          senderId: manager.id, 
          senderName: manager.name, 
          receiverId: receiverIds, 
          content: msgContent, 
          timestamp: new Date().toISOString(), 
          isRead: false 
      });

      alert(`Đã gửi thông báo thành công cho ${receiverIds.length} nhân sự!`); 
