                        return (
                        <tr key={user.id} className={`${rowBg} hover:bg-blue-50 transition-colors`}>
                            <td className="px-6 py-4">
                                <div className="flex items-center relative" style={{ paddingLeft: `${user._depth * 28}px` }}>
                                    {/* Visual Hierarchy Lines */}
                                    {user._depth > 0 && (
                                        <div className="absolute left-0 top-1/2 -translate-y-1/2 border-l border-b border-gray-300 w-4 h-full" style={{ left: `${(user._depth - 1) * 28 + 12}px`, height: '120%', top: '-50%' }}></div>
                                    )}
                                    {user._depth > 0 && <div className="absolute border-b border-gray-300 w-4 h-0" style={{ left: `${(user._depth - 1) * 28 + 12}px` }}></div>}

                                    <div className="flex items-center gap-3 relative z-10">
                                        <div className={`w-8 h-8 rounded-full flex items-center justify-center text-[10px] font-bold shadow-sm ${user._depth === 0 ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-600'}`}>
                                            {user.name.charAt(0)}
                                        </div>
                                        <div>
                                            <div className={`font-bold uppercase leading-tight ${user._depth === 0 ? 'text-blue-800 text-sm' : 'text-gray-800'}`}>{user.name}</div>
                                            <div className="flex items-center gap-2 mt-1">
