                 <Input label="Mật khẩu" value={formUser.password || ''} onChange={e => setFormUser({...formUser, password: e.target.value})} />
                 <Input label="Số điện thoại" value={formUser.phone || ''} onChange={e => setFormUser({...formUser, phone: e.target.value})} />
            </div>
            <div className="bg-gray-50 p-4 rounded-xl border border-gray-100 space-y-4">
                <Select label="Vai trò hệ thống" value={formUser.role} onChange={e => setFormUser({...formUser, role: e.target.value as UserRole})} options={allowedRoles.map(role => ({value: role, label: ROLE_LABELS[role]}))} />
                {formUser.role === UserRole.EMPLOYEE ? (
                    <Select 
                        label="Trực thuộc đơn vị (Phòng/Nhóm)" 
                        value={formUser.departmentId || ''} 
                        onChange={e => setFormUser({...formUser, departmentId: e.target.value})} 
                        options={[{value: '', label: '-- Chọn đơn vị --'}, ...departments.map(d => ({value: d.id, label: `${d.name} (${d.level})`}))]} 
                    />
                ) : (
                    <div className="space-y-4 animate-fadeIn">
                        <div className="flex items-center gap-2 mb-2">
                            <GitMerge size={16} className="text-blue-500"/>
                            <span className="text-xs font-black uppercase text-gray-500">Cấu hình Đơn vị quản lý</span>
                        </div>
                        {!editingUserId && (
                             <>
                                <Input 
                                    label={`Tên đơn vị quản lý (Tạo mới)`} 
                                    placeholder={`Ví dụ: Team A...`}
                                    value={formUser.newDeptName || ''}
                                    onChange={e => setFormUser({...formUser, newDeptName: e.target.value})}
                                />
                                <Select 
                                    label={`Trực thuộc đơn vị cấp trên`}
                                    value={formUser.newDeptParentId || ''} 
                                    onChange={e => setFormUser({...formUser, newDeptParentId: e.target.value})} 
                                    options={[
                                        {value: '', label: '-- Chọn cấp trên --'},
                                        ...departments.filter(d => d.level !== DepartmentLevel.TEAM).map(d => ({value: d.id, label: d.name}))
