        <Modal isOpen={showConsModal} onClose={() => setShowConsModal(false)} title={editingId ? "SỬA PHIẾU TƯ VẤN" : "LẬP PHIẾU TƯ VẤN"}>
             <div className="space-y-4 p-1">
                <Input label="Thời gian tư vấn" type="datetime-local" value={newCons.date} onChange={e => setNewCons({...newCons, date: e.target.value})} />
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div className="relative">
                         <Input label="SĐT khách hàng" value={newCons.phone || ''} onChange={e => setNewCons({...newCons, phone: e.target.value})} onBlur={handlePhoneBlurForCons} />
                         {duplicateWarning && <p className="text-[10px] text-red-600 mt-1 font-bold flex items-center gap-1 uppercase"><AlertTriangle size={10}/> {duplicateWarning}</p>}
                    </div>
                    <Input label="Tên khách hàng" value={newCons.customerName || ''} onChange={e => setNewCons({...newCons, customerName: e.target.value})} />
                </div>
                <div className="bg-blue-50/50 p-4 rounded-xl border border-blue-100">
                    <Select label="Hình thức hỗ trợ" value={newCons.supportType} onChange={e => setNewCons({...newCons, supportType: e.target.value as SupportType})} options={Object.values(SupportType).map(t => ({value: t, label: t}))} />
                    {newCons.supportType !== SupportType.SOLO && (
                        <div className="mt-3 animate-fadeIn">
                            <Input label="Tên đồng nghiệp hỗ trợ (Ký chung)" value={newCons.supportPersonName || ''} onChange={e => setNewCons({...newCons, supportPersonName: e.target.value})} placeholder="Nhập tên người hỗ trợ..." />
                        </div>
                    )}
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <Select label="Loại hình tư vấn" value={newCons.type} onChange={e => setNewCons({...newCons, type: e.target.value as ConsultationType})} options={Object.values(ConsultationType).map(t => ({value: t, label: t}))} />
                    <Input label="Nguồn khách" placeholder="FB, Data, Google..." value={newCons.source || ''} onChange={e => setNewCons({...newCons, source: e.target.value})} />
                </div>
                <div className="grid grid-cols-1 gap-4">
                     <Input label="Địa chỉ / Khu vực" value={newCons.addressDetail || ''} onChange={e => setNewCons({...newCons, addressDetail: e.target.value})} />
                     <Input label="Nội dung chính / Ghi chú" value={newCons.notes || ''} onChange={e => setNewCons({...newCons, notes: e.target.value})} placeholder="Các yêu cầu đặc biệt của khách..." />
                </div>
                <div className="flex justify-end gap-3 pt-4 border-t mt-6">
                    <Button variant="ghost" onClick={() => setShowConsModal(false)}>Hủy bỏ</Button>
                    <Button onClick={() => submitForm(async () => {
                        if(!newCons.phone || !newCons.customerName) throw new Error("Thiếu SĐT hoặc Tên");
                        // SAFE GUARD: Ensure no undefined fields
                        const safeCons = {
                            ...newCons,
                            notes: newCons.notes || '',
                            source: newCons.source || '',
                            companyName: newCons.companyName || '',
                            addressDetail: newCons.addressDetail || '',
                            supportPersonName: newCons.supportPersonName || ''
                        };
                        if (editingId) await storageService.updateConsultation({ ...safeCons, id: editingId } as Consultation, user);
                        else await storageService.addConsultation({ ...safeCons, id: `C${Date.now()}`, userId: user.id } as Consultation, user);
                    }, setShowConsModal)}>LƯU PHIẾU</Button>
                </div>
            </div>
        </Modal>

        <Modal isOpen={showRevModal} onClose={() => setShowRevModal(false)} title={editingId ? "CẬP NHẬT DOANH THU" : "PHIẾU THU DOANH THU"}>
             <div className="space-y-4 p-1">
               <div className="bg-gray-800 text-white p-4 rounded-xl shadow-inner flex items-end gap-3">
                   <div className="flex-1">
                       <label className="block text-[10px] font-black uppercase tracking-widest text-gray-400 mb-1">Truy vấn nhanh khách hàng</label>
                       <input className="w-full bg-gray-700 border-none rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500" value={revSearchPhone} onChange={e => setRevSearchPhone(e.target.value)} placeholder="Nhập SĐT..." />
                   </div>
                   <Button size="md" onClick={handleRevPhoneSearch} className="h-[38px] bg-blue-500 hover:bg-blue-400"><Search size={18}/></Button>
               </div>
               <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <Input label="Ngày thu" type="datetime-local" value={newRev.date} onChange={e => setNewRev({...newRev, date: e.target.value})} />
                    <Select label="Khoản thu" value={newRev.type} onChange={e => setNewRev(prev => ({ ...prev, type: e.target.value as RevenueType }))} options={Object.values(RevenueType).map(t => ({value: t, label: t}))} />
               </div>
               <div className="p-4 rounded-xl bg-gray-50 border border-gray-100 space-y-3">
                    <Input label="Khách hàng" value={newRev.customerName || ''} onChange={e => setNewRev({...newRev, customerName: e.target.value})} />
                    <div className="grid grid-cols-2 gap-4">
                        <Input label="Mã Hợp Đồng" value={newRev.contractCode || ''} onChange={e => setNewRev({...newRev, contractCode: e.target.value})} className="font-bold uppercase text-blue-700" />
                        <Input label="Số điện thoại" value={newRev.phone || ''} onChange={e => setNewRev({...newRev, phone: e.target.value})} />
                    </div>
               </div>
               {newRev.type === RevenueType.NEW && (
                   <div className="animate-fadeIn p-4 bg-green-50 rounded-xl border border-green-100">
                       <Input label="Giá trị hợp đồng gốc (Gói Web)" type="number" value={newRev.contractValue || ''} onChange={e => setNewRev({...newRev, contractValue: Number(e.target.value)})} className="font-black text-green-700" />
                       <p className="text-[10px] text-green-600 mt-1 font-bold">Giá trị tổng của dự án khi bắt đầu ký</p>
                   </div>
               )}
               {newRev.type === RevenueType.HANDOVER && (
                 <div className="bg-yellow-50 p-4 rounded-xl border border-yellow-100">
                    <label className="block text-xs font-black text-yellow-700 uppercase mb-2">Liên kết hợp đồng ký mới</label>
                    <select className="w-full p-2.5 border rounded-xl bg-white text-sm" onChange={e => {
                        const val = e.target.value;
                        const parent = revenues.find(r => r.id === val);
                        if (parent) {
                            const remaining = parent.contractValue - parent.amountCollected;
                            setNewRev(prev => ({ ...prev, relatedContractId: val, contractCode: parent.contractCode, contractValue: parent.contractValue, amountCollected: remaining > 0 ? remaining : 0 }));
                        }
                    }}>
                       <option value="">-- Chọn hợp đồng --</option>
                       {revenues.filter(r => r.userId === user.id && r.type === RevenueType.NEW).map(r => (
                          <option key={r.id} value={r.id}>{r.contractCode} - Gói: {formatCurrency(r.contractValue)}</option>
                       ))}
                    </select>
                 </div>
               )}
               <div className="p-4 bg-orange-50 rounded-xl border border-orange-100">
                    <Input label="Số tiền thu thực tế" type="number" value={newRev.amountCollected || ''} onChange={e => setNewRev({...newRev, amountCollected: Number(e.target.value)})} className="font-black text-red-600 text-lg" />
                    <p className="text-[10px] text-orange-600 mt-1 font-bold uppercase tracking-widest">Kế toán sẽ căn cứ vào số này</p>
               </div>
               <div className="flex justify-end gap-3 pt-4 border-t mt-6">
                 <Button variant="ghost" onClick={() => setShowRevModal(false)}>Hủy</Button>
                 <Button onClick={() => submitForm(async () => {
                    if(!newRev.amountCollected || !newRev.contractCode) throw new Error("Thiếu số tiền hoặc Mã HĐ");
                    if(newRev.type === RevenueType.NEW && !newRev.contractValue) throw new Error("Cần nhập giá trị hợp đồng");

                    const revenueData = { ...newRev, id: editingId || `R${Date.now()}`, userId: user.id } as Revenue;
                    if (editingId) await storageService.updateRevenue(revenueData, user);
                    else await storageService.addRevenue(revenueData, user);
                 }, setShowRevModal)} className="bg-orange-600 hover:bg-orange-500">{editingId ? 'CẬP NHẬT' : 'XÁC NHẬN THU'}</Button>
              </div>
             </div>
        </Modal>
        </>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { User, Appointment, Consultation, Revenue, RevenueType, AppointmentStatus, ConsultationType, ProjectProfile, Message, SupportType, MonthlyTarget } from '../types';
import { storageService } from '../services/storageService';
import { VIETNAM_PROVINCES } from '../constants';
import { Button, Input, Select, Modal, Combobox, Badge } from '../components/ui';
import { PlusCircle, DollarSign, Calendar, Phone, MapPin, ChevronDown, ChevronRight, Clock, AlertTriangle, Edit, Trash2, Search, FileDown, MessageSquare, Send, X, User as UserIcon, Building2, Download, Link as LinkIcon, Globe, Database, Layers, Loader2, Wallet, TrendingUp } from 'lucide-react';

interface Props {
  user: User;
  isViewOnly?: boolean;
}

declare const XLSX: any;

const formatDateVN = (isoString: string) => {
    if(!isoString) return '';
    const date = new Date(isoString);
    return `${date.getDate().toString().padStart(2, '0')}/${(date.getMonth() + 1).toString().padStart(2, '0')}/${date.getFullYear()}`;
};

const formatDateTimeVN = (isoString: string) => {
    if(!isoString) return '';
    const date = new Date(isoString);
    const time = isoString.split('T')[1];
    return `${time} - ${date.getDate().toString().padStart(2, '0')}/${(date.getMonth() + 1).toString().padStart(2, '0')}/${date.getFullYear()}`;
};

export const EmployeeDashboard: React.FC<Props> = ({ user, isViewOnly = false }) => {
  const [loading, setLoading] = useState(!isViewOnly);
  const [activeTab, setActiveTab] = useState<'timeline' | 'projects'>('timeline');
  const [showChatModal, setShowChatModal] = useState(false);

  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [consultations, setConsultations] = useState<Consultation[]>([]);
  const [revenues, setRevenues] = useState<Revenue[]>([]);
  const [projects, setProjects] = useState<ProjectProfile[]>([]);
  const [targets, setTargets] = useState<Record<string, MonthlyTarget>>({}); // Key: YYYY-MM

  const [messages, setMessages] = useState<Message[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const [searchTerm, setSearchTerm] = useState('');

  // --- DATE RANGE STATE (Default: Current Month) ---
  const [startDate, setStartDate] = useState(() => {
      const date = new Date();
      return new Date(date.getFullYear(), date.getMonth(), 1).toISOString().split('T')[0];
  });
  const [endDate, setEndDate] = useState(() => {
      const date = new Date();
      return new Date(date.getFullYear(), date.getMonth() + 1, 0).toISOString().split('T')[0];
  });

  const [showAppModal, setShowAppModal] = useState(false);
  const [showConsModal, setShowConsModal] = useState(false);
  const [showRevModal, setShowRevModal] = useState(false);

  const [duplicateWarning, setDuplicateWarning] = useState<string | null>(null);
  const [revSearchPhone, setRevSearchPhone] = useState('');

  const [expandedDates, setExpandedDates] = useState<Record<string, boolean>>({});
  const [expandedProjects, setExpandedProjects] = useState<Record<string, boolean>>({});

  const getNowISO = () => {
      const now = new Date();
      now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
      return now.toISOString().slice(0, 16);
  };

  const [editingId, setEditingId] = useState<string | null>(null);
  const [newApp, setNewApp] = useState<Partial<Appointment>>({ 
      date: getNowISO(), 
      status: AppointmentStatus.NEW, 
      location: '',
      customerName: '',
      phone: '',
      companyName: '',
      email: '',
      addressDetail: '',
      source: '',
      notes: ''
  });
  const [newCons, setNewCons] = useState<Partial<Consultation>>({ 
      date: getNowISO(), 
      type: ConsultationType.NEW, 
      supportType: SupportType.SOLO, 
      customerName: '',
      phone: '',
      source: '',
      companyName: '',
      addressDetail: '',
      notes: ''
  });

  const [newRev, setNewRev] = useState<Partial<Revenue> & { 
      customerName?: string;
      phone?: string;
      email?: string;
      companyName?: string;
      address?: string;
      region?: string;
  }>({ 
      date: getNowISO(), 
      type: RevenueType.NEW, 
      isApproved: false,
      contractCode: '',
      amountCollected: 0,
      customerName: '',
      phone: ''
  });

  const loadData = async () => {
    setLoading(true);
    try {
        const [a, c, r, p, m, t] = await Promise.all([
            storageService.getAppointments(),
            storageService.getConsultations(),
            storageService.getRevenues(),
            storageService.getProjects(),
            storageService.getMessages(),
            storageService.getAllTargetsByUser(user.id)
        ]);

        setAppointments(a.filter(item => item.userId === user.id));
        setConsultations(c.filter(item => item.userId === user.id));
        setRevenues(r.filter(item => item.userId === user.id));
        setProjects(p.filter(item => item.userId === user.id));

        const targetMap: Record<string, MonthlyTarget> = {};
        t.forEach(tg => { targetMap[tg.monthStr] = tg; });
        setTargets(targetMap);

        const myMsgs = m.filter(msg => {
            if (msg.senderId === user.id) return true;
            if (msg.receiverId === 'ALL') return true;
            if (Array.isArray(msg.receiverId)) return msg.receiverId.includes(user.id);
            return msg.receiverId === user.id;
        }).sort((x,y) => new Date(x.timestamp).getTime() - new Date(y.timestamp).getTime());
        setMessages(myMsgs);
    } catch(err) {
        console.error(err);
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => { loadData(); }, [user.id]);

  useEffect(() => {
      if (showChatModal) {
          setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
      }
  }, [messages, showChatModal]);

  const isInRange = (dateStr: string) => {
     if (!dateStr) return false;
     const d = dateStr.split('T')[0];
     return d >= startDate && d <= endDate;
  };

  const filteredData = useMemo(() => {
    const lowerTerm = searchTerm.toLowerCase();
    const filterFn = (item: any) => {
        const matchesTerm = (item.customerName?.toLowerCase().includes(lowerTerm)) || (item.phone?.includes(lowerTerm)) || (item.contractCode?.toLowerCase().includes(lowerTerm));
        const matchesDate = isInRange(item.date);
        return matchesTerm && matchesDate;
    };
    return {
        apps: appointments.filter(filterFn),
        cons: consultations.filter(filterFn),
        revs: revenues.filter(filterFn)
    };
  }, [appointments, consultations, revenues, searchTerm, startDate, endDate]);

  const totalRevenue = useMemo(() => {
      const earned = filteredData.revs.reduce((s, r) => s + r.amountCollected, 0);
      return earned; 
  }, [filteredData.revs]);

  // --- PERFORMANCE METRICS LOGIC ---
  const performanceStats = useMemo(() => {
      // Current Month Logic: Derived from the startDate selected by user (assuming user views a month)
      const currentMonthStr = startDate.substring(0, 7); // YYYY-MM

      // Prev Month Logic
      const d = new Date(startDate);
      d.setMonth(d.getMonth() - 1);
      const prevMonthStr = d.toISOString().substring(0, 7); // YYYY-MM

      // Calculate Actuals
      const calcStats = (monthStr: string) => {
          return {
              app: appointments.filter(a => a.date.startsWith(monthStr)).length,
              cons: consultations.filter(c => c.date.startsWith(monthStr)).length,
              rev: revenues.filter(r => r.date.startsWith(monthStr)).reduce((s, r) => s + r.amountCollected, 0)
          };
      };

      const currActual = calcStats(currentMonthStr);
      const prevActual = calcStats(prevMonthStr);

      // Get Targets (Commitments)
      const currTarget = targets[currentMonthStr] || { targetAppointment: 0, targetConsultation: 0, targetRevenue: 0 };
      const prevTarget = targets[prevMonthStr] || { targetAppointment: 0, targetConsultation: 0, targetRevenue: 0 };

      return {
          current: {
              monthStr: currentMonthStr,
              actual: currActual,
              target: currTarget
          },
          prev: {
              monthStr: prevMonthStr,
              actual: prevActual,
              target: prevTarget
          }
      };
  }, [startDate, appointments, consultations, revenues, targets]);

  const handleUpdateTarget = async (field: keyof MonthlyTarget, value: number) => {
      const monthStr = performanceStats.current.monthStr;
      const existing = targets[monthStr] || { 
          id: `${user.id}_${monthStr.replace(/-/g, '_')}`, 
          userId: user.id, 
          monthStr, 
          targetAppointment: 0, 
          targetConsultation: 0, 
          targetRevenue: 0 
      };

      const updated = { ...existing, [field]: value };

      // Optimistic Update
      setTargets(prev => ({ ...prev, [monthStr]: updated }));

      // Save to DB
      await storageService.saveMonthlyTarget(updated);
  };

  const projectTableData = useMemo(() => {
    return projects.map(proj => {
        const relatedRevs = revenues.filter(r => r.contractCode === proj.contractCode);
        const col1 = relatedRevs.filter(r => r.type === RevenueType.NEW).reduce((s, r) => s + r.amountCollected, 0);
        const col2 = relatedRevs.filter(r => r.type === RevenueType.HOSTING).reduce((s, r) => s + r.amountCollected, 0);
        const col3 = relatedRevs.filter(r => r.type === RevenueType.HANDOVER).reduce((s, r) => s + r.amountCollected, 0);
        const colUpgrade = relatedRevs.filter(r => r.type === RevenueType.UPGRADE_WEB || r.type === RevenueType.UPGRADE_HOSTING).reduce((s, r) => s + r.amountCollected, 0);
        const newRevItem = relatedRevs.find(r => r.type === RevenueType.NEW);

        let customerName = proj.customerName;
        let phone = proj.phone;
        let email = proj.email;
        let companyName = proj.companyName;
        let region = proj.region;

        if (!customerName && newRevItem) {
           const customerInfo = appointments.find(a => a.date <= newRevItem.date && (a.status === AppointmentStatus.CLOSED || a.status === AppointmentStatus.INTERESTED));
           if (customerInfo) {
               customerName = customerInfo.customerName;
               phone = customerInfo.phone;
               email = customerInfo.email;
               companyName = customerInfo.companyName;
               if (!region) region = customerInfo.location;
           }
        }

        const relatedCons = consultations.find(c => (phone && c.phone === phone) || (customerName && c.customerName === customerName));
        let jointSignerName = proj.jointSigner;
        if (!jointSignerName && relatedCons && relatedCons.supportType !== SupportType.SOLO) {
            jointSignerName = relatedCons.supportPersonName || '';
        }

        const totalVal = relatedRevs.find(r => r.type === RevenueType.NEW)?.contractValue || 0;
        const signDateDisplay = proj.signDate || (newRevItem?.date ? formatDateVN(newRevItem.date) : '');
        const handoverDateDisplay = proj.handoverDate || (relatedRevs.find(r => r.type === RevenueType.HANDOVER)?.date ? formatDateVN(relatedRevs.find(r => r.type === RevenueType.HANDOVER)!.date) : '');
        const autoStatus = (col3 > 0) ? 'Hoàn thành' : (proj.status || 'Đang chạy');

        return {
            ...proj,
            customerName: customerName || '',
            phone: phone || '',
            email: email || '',
            companyName: companyName || '',
            region: region || '',
            status: autoStatus,
            signDate: signDateDisplay,
            handoverDate: handoverDateDisplay,
            contractValue: totalVal,
            col1, col2, col3, colUpgrade,
            totalCollected: col1 + col2 + col3 + colUpgrade,
            jointSigner: jointSignerName || ''
        };
    });
  }, [projects, revenues, appointments, consultations]);

  const timelineData = useMemo(() => {
    const dates = new Set([
        ...filteredData.apps.map(a => a.date.split('T')[0]),
        ...filteredData.cons.map(c => c.date.split('T')[0]),
        ...filteredData.revs.map(r => r.date.split('T')[0])
    ]);
    const sortedDates = Array.from(dates).sort().reverse();
    const list = sortedDates.map(dateStr => ({
        date: dateStr,
        displayDate: formatDateVN(dateStr),
        apps: filteredData.apps.filter(a => a.date.startsWith(dateStr)),
        cons: filteredData.cons.filter(c => c.date.startsWith(dateStr)),
        revs: filteredData.revs.filter(r => r.date.startsWith(dateStr)),
    }));
    const initialExpanded: Record<string, boolean> = {};
    if (list.length > 0) initialExpanded[list[0].date] = true;
    return { list, initialExpanded };
  }, [filteredData]); 

  useEffect(() => {
     if (Object.keys(expandedDates).length === 0 && Object.keys(timelineData.initialExpanded).length > 0) {
         setExpandedDates(timelineData.initialExpanded);
     }
  }, [timelineData.initialExpanded]);

  const toggleProject = (code: string) => {
    setExpandedProjects(prev => ({ ...prev, [code]: !prev[code] }));
  };

  const handleExportExcel = () => {
    if (projectTableData.length === 0) return alert("Không có dữ liệu để xuất");

    const worksheet = XLSX.utils.json_to_sheet(projectTableData.map(r => ({
        "Tên Khách Hàng": r.customerName,
        "Số Điện Thoại": r.phone,
        "Công Ty": r.companyName,
        "Email": r.email,
        "Mã Hợp Đồng": r.contractCode,
        "Tỉnh/Thành": r.region,
        "Trạng Thái": r.status,
        "Gói Web": r.contractValue,
        "Thu Lần 1 (Ký Mới)": r.col1,
        "Thu Lần 2 (Hosting)": r.col2,
        "Thu Lần 3 (Bàn Giao)": r.col3,
        "Doanh Thu Nâng Cấp": r.colUpgrade,
        "Tổng Thu": r.totalCollected,
        "Ngày Ký": r.signDate,
        "Ngày Bàn Giao": r.handoverDate,
        "Người Ký Chung": r.jointSigner,
        "Link Design": r.designLink,
        "Trang Web": r.webLink,
        "Zalo Group": r.zaloGroup
    })));

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Projects");
    XLSX.writeFile(workbook, `SaleFlow_Projects_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const checkDuplicatePhone = async (phone: string) => {
      if (!phone || phone.length < 9) {
          setDuplicateWarning(null);
          return;
      }
      const teamDup = await storageService.findTeamDuplicate(phone, user.id);
      if (teamDup) {
           setDuplicateWarning(`Trùng với ${teamDup.name} (${teamDup.role})`);
      } else {
           setDuplicateWarning(null);
      }
  };

  const getDuplicateTag = (phone: string) => {
     return null;
  };

  const handlePhoneBlurForCons = async () => {
    if (newCons.phone) {
      await checkDuplicatePhone(newCons.phone);
      const result = await storageService.findGlobalAppointmentByPhone(newCons.phone);
      if (result) {
        const app = result.appointment;
        setNewCons(prev => ({ 
            ...prev, 
            customerName: app.customerName, 
            appointmentId: app.id,
            companyName: app.companyName, 
            source: app.source || prev.source || '', 
            addressDetail: `${app.addressDetail || ''} ${app.location ? '- ' + app.location : ''}`,
            notes: prev.notes || app.notes || '' // Safe guard against undefined
        }));
      }
    }
  };

  const handleRevPhoneSearch = async () => {
      if (!revSearchPhone) return alert("Vui lòng nhập SĐT");
      const custData = await storageService.findCustomerByPhone(revSearchPhone);
      if (custData) {
          setNewRev(prev => ({
              ...prev,
              phone: revSearchPhone,
              customerName: custData.name,
              companyName: custData.company,
              address: custData.address,
