                            placeholder="Nhập tin nhắn..." 
                            value={chatMessage} 
                            onChange={e => setChatMessage(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && handleSendMessage()}
                            autoFocus
                        />
                        <button onClick={handleSendMessage} className="bg-blue-600 text-white p-3 rounded-xl hover:bg-blue-700 shadow-lg active:scale-95 transition-all">
                            <Send size={18} />
