                   </div>
               </div>
           </div>
       </Modal>

      {/* Modals Retained As Is ... */}
      {!isViewOnly && (
        <>
        <Modal isOpen={showAppModal} onClose={() => setShowAppModal(false)} title={editingId ? "SỬA THÔNG TIN HẸN" : "NHẬP THÔNG TIN HẸN"}>
            <div className="space-y-4 p-1">
                <Input label="Ngày hẹn" type="datetime-local" value={newApp.date} onChange={e => setNewApp({...newApp, date: e.target.value})} />
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <Input label="Tên Khách Hàng" placeholder="VD: Anh Minh" value={newApp.customerName || ''} onChange={e => setNewApp({...newApp, customerName: e.target.value})} />
                    <Input label="Công Ty" placeholder="Tên doanh nghiệp..." value={newApp.companyName || ''} onChange={e => setNewApp({...newApp, companyName: e.target.value})} />
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div>
                        <Input 
                            label="Số điện thoại" 
                            placeholder="09xx..."
                            value={newApp.phone || ''} 
                            onChange={e => {
                                setNewApp({...newApp, phone: e.target.value});
                                checkDuplicatePhone(e.target.value);
                            }}
                            onBlur={(e) => checkDuplicatePhone(e.target.value)}
                        />
                        {duplicateWarning && <p className="text-[10px] text-red-600 mt-1 font-bold flex items-center gap-1 uppercase"><AlertTriangle size={10}/> {duplicateWarning}</p>}
                    </div>
                    <Input label="Email" placeholder="khach@company.com" value={newApp.email || ''} onChange={e => setNewApp({...newApp, email: e.target.value})} />
