                    <Input label="Nguồn khách" placeholder="FB, Google, Giới thiệu..." value={newApp.source || ''} onChange={e => setNewApp({...newApp, source: e.target.value})} />
                </div>
                <div className="flex justify-end gap-3 pt-4 border-t mt-6">
                    <Button variant="ghost" onClick={() => setShowAppModal(false)}>Đóng</Button>
                    <Button onClick={() => submitForm(async () => {
                        if (!newApp.phone || !newApp.customerName) throw new Error("Vui lòng điền đủ Tên và SĐT");
                        if (editingId) await storageService.updateAppointment({ ...newApp, id: editingId } as Appointment, user);
                        else await storageService.addAppointment({ ...newApp, id: `A${Date.now()}`, userId: user.id } as Appointment, user);
                    }, setShowAppModal)}>HOÀN TẤT</Button>
                </div>
