        </Modal>

        <Modal isOpen={showConsModal} onClose={() => setShowConsModal(false)} title={editingId ? "SỬA PHIẾU TƯ VẤN" : "LẬP PHIẾU TƯ VẤN"}>
             <div className="space-y-4 p-1">
                <Input label="Thời gian tư vấn" type="datetime-local" value={newCons.date} onChange={e => setNewCons({...newCons, date: e.target.value})} />
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div className="relative">
                         <Input label="SĐT khách hàng" value={newCons.phone || ''} onChange={e => setNewCons({...newCons, phone: e.target.value})} onBlur={handlePhoneBlurForCons} />
