         case DepartmentLevel.GROUP: allowedParentLevels = [DepartmentLevel.REGION]; break;
         case DepartmentLevel.DEPARTMENT: allowedParentLevels = [DepartmentLevel.GROUP, DepartmentLevel.REGION]; break;
