                    const revenueData = { ...newRev, id: editingId || `R${Date.now()}`, userId: user.id } as Revenue;

                    // 1. Save Revenue
                    if (editingId) await storageService.updateRevenue(revenueData, user);
                    else await storageService.addRevenue(revenueData, user);

                    // 2. Project Synchronization Logic
                    const targetCode = newRev.contractCode.trim().toUpperCase();
                    const existingProj = projects.find(p => p.contractCode === targetCode);

                    if (!existingProj) {
                        // Create NEW Project automatically if code is new
                        // (Even if phone exists, new contract code = new project per requirement)
                        await storageService.addProject({
                            contractCode: targetCode,
                            userId: user.id,
                            customerName: newRev.customerName,
                            phone: newRev.phone,
                            companyName: newRev.companyName,
                            address: newRev.address,
                            region: newRev.region,
                            status: 'Đang chạy',
                            hostingSize: newRev.type === RevenueType.HOSTING ? newRev.hostingInfo : '',
                            contractValue: newRev.type === RevenueType.NEW ? newRev.contractValue : 0
                        });
                    } else if (newRev.type === RevenueType.HOSTING && newRev.hostingInfo) {
                        // Update existing project if Hosting Info provided
                        await storageService.updateProject({
                            ...existingProj,
                            hostingSize: newRev.hostingInfo
                        }, user, "Cập nhật thông tin Hosting từ phiếu thu");
                    }

                 }, setShowRevModal)} className="bg-orange-600 hover:bg-orange-500">{editingId ? 'CẬP NHẬT' : 'XÁC NHẬN THU'}</Button>
