        const col3 = relatedRevs.filter(r => r.type === RevenueType.HANDOVER).reduce((s, r) => s + r.amountCollected, 0);
        const colUpgrade = relatedRevs.filter(r => r.type === RevenueType.UPGRADE_WEB || r.type === RevenueType.UPGRADE_HOSTING).reduce((s, r) => s + r.amountCollected, 0);
        const newRevItem = relatedRevs.find(r => r.type === RevenueType.NEW);

        let customerName = proj.customerName;
        let phone = proj.phone;
        let email = proj.email;
        let companyName = proj.companyName;
        let region = proj.region;

        if (!customerName && newRevItem) {
           const customerInfo = appointments.find(a => a.date <= newRevItem.date && (a.status === AppointmentStatus.CLOSED || a.status === AppointmentStatus.INTERESTED));
