const handleUpdateProject = async (proj: ProjectProfile, field: keyof ProjectProfile, value: any) => {
    const updated = { ...proj, [field]: value } as ProjectProfile;
    setProjects(prev => prev.map(p => p.contractCode === proj.contractCode ? updated : p));

    const changeDetail = `Thay đổi ${field} thành "${value}" cho HĐ ${proj.contractCode}`;
    await storageService.updateProject(updated, user, changeDetail);
};

const handleDeleteProject = async (contractCode: string) => {
    if (confirm(`CẢNH BÁO: Bạn có chắc chắn muốn xóa toàn bộ hồ sơ dự án của Hợp đồng ${contractCode}?\n\nDữ liệu doanh thu liên quan sẽ KHÔNG bị xóa, nhưng các thông tin chi tiết về dự án (link, hosting, ghi chú...) sẽ mất vĩnh viễn.`)) {
        try {
            await storageService.deleteProject(contractCode, user);
            await loadData();
        } catch (e: any) {
            alert("Lỗi xóa dự án: " + e.message);
        }
    }
};

