import { 
  collection, getDocs, doc, setDoc, updateDoc, deleteDoc, query, where, orderBy, addDoc 
} from "firebase/firestore"; 
import { db } from "./firebaseConfig";
import { 
  User, Department, Revenue, Appointment, Consultation, 
  Message, ProjectProfile, ActivityLog, UserRole, MonthlyTarget 
} from "../types";

const COLS = {
  USERS: 'users',
  DEPARTMENTS: 'departments',
  REVENUES: 'revenues',
  APPOINTMENTS: 'appointments',
  CONSULTATIONS: 'consultations',
  PROJECTS: 'projects',
  MESSAGES: 'messages',
  ACTIVITIES: 'activities',
  TARGETS: 'targets'
};

const logActivity = async (actor: {id: string, name: string}, action: 'TẠO' | 'CẬP NHẬT' | 'XÓA', targetType: 'HẸN' | 'TƯ VẤN' | 'DOANH THU' | 'DỰ ÁN' | 'HỆ THỐNG', targetId: string, description: string) => {
  try {
    const id = `LOG${Date.now()}`;
    await setDoc(doc(db, COLS.ACTIVITIES, id), {
      id,
      actorId: actor.id,
      actorName: actor.name,
      action,
      targetType,
      targetId,
      description,
      timestamp: new Date().toISOString()
    });
  } catch (e) {
    console.error("Error logging activity", e);
  }
};

export const storageService = {
  // --- USERS ---
  login: async (code: string, pass: string): Promise<User | null> => {
    // Simulating login by checking firestore 'users' collection
    // In real app, use firebase/auth
    const q = query(collection(db, COLS.USERS), where("id", "==", code));
    const snap = await getDocs(q);
    if (snap.empty) return null;
