  TARGETS: 'targets'
};

const logActivity = async (actor: {id: string, name: string}, action: 'TẠO' | 'CẬP NHẬT' | 'XÓA', targetType: 'HẸN' | 'TƯ VẤN' | 'DOANH THU' | 'DỰ ÁN' | 'HỆ THỐNG', targetId: string, description: string) => {
  try {
    const id = `LOG${Date.now()}`;
    await setDoc(doc(db, COLS.ACTIVITIES, id), {
      id,
      actorId: actor.id,
      actorName: actor.name,
      action,
      targetType,
      targetId,
      description,
      timestamp: new Date().toISOString()
    });
  } catch (e) {
    console.error("Error logging activity", e);
  }
};

