import React, { useState, useEffect } from 'react';
import { User, ProjectProfile, Revenue, Appointment, Consultation, RevenueType, AppointmentStatus, ConsultationType, SupportType } from '../types';
import { storageService } from '../services/storageService';
import { Card, Button, Input, Select, Badge, Modal } from '../components/ui';
import { Plus, Edit, Trash2, ChevronRight, ExternalLink, Calendar, DollarSign, MessageSquare, Briefcase, FileText, Loader2 } from 'lucide-react';
import { VIETNAM_PROVINCES } from '../constants';

interface EmployeeDashboardProps {
  user: User;
  isViewOnly?: boolean;
}

export const EmployeeDashboard: React.FC<EmployeeDashboardProps> = ({ user, isViewOnly = false }) => {
  const [activeTab, setActiveTab] = useState<'revenues' | 'appointments' | 'consultations' | 'projects'>('revenues');
  const [loading, setLoading] = useState(false);

  // Data
  const [revenues, setRevenues] = useState<Revenue[]>([]);
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [consultations, setConsultations] = useState<Consultation[]>([]);
  const [projects, setProjects] = useState<ProjectProfile[]>([]);

  // State for Project Expansion
  const [expandedProjects, setExpandedProjects] = useState<Record<string, boolean>>({});

  // Modals
  const [isRevModalOpen, setRevModalOpen] = useState(false);
  const [editingRev, setEditingRev] = useState<Partial<Revenue>>({});

  const [isAppModalOpen, setAppModalOpen] = useState(false);
  const [editingApp, setEditingApp] = useState<Partial<Appointment>>({});

  const [isConsModalOpen, setConsModalOpen] = useState(false);
  const [editingCons, setEditingCons] = useState<Partial<Consultation>>({});

  const [isProjModalOpen, setProjModalOpen] = useState(false);
  const [editingProj, setEditingProj] = useState<Partial<ProjectProfile>>({});

  const refreshData = async () => {
    setLoading(true);
    try {
        const [r, a, c, p] = await Promise.all([
            storageService.getRevenues(),
            storageService.getAppointments(),
            storageService.getConsultations(),
            storageService.getProjects()
        ]);
        setRevenues(r.filter(x => x.userId === user.id).sort((x, y) => new Date(y.date).getTime() - new Date(x.date).getTime()));
        setAppointments(a.filter(x => x.userId === user.id).sort((x, y) => new Date(y.date).getTime() - new Date(x.date).getTime()));
        setConsultations(c.filter(x => x.userId === user.id).sort((x, y) => new Date(y.date).getTime() - new Date(x.date).getTime()));
        setProjects(p.filter(x => x.userId === user.id));
    } catch (e) {
        console.error(e);
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => {
    refreshData();
  }, [user.id]);

  const toggleProject = (contractCode: string) => {
      setExpandedProjects(prev => ({ ...prev, [contractCode]: !prev[contractCode] }));
  };

  // --- Handlers: REVENUE ---
  const handleSaveRevenue = async () => {
      if (!editingRev.contractCode || !editingRev.amountCollected || !editingRev.type) return alert("Vui lòng điền đủ thông tin");
      const rev: Revenue = {
          id: editingRev.id || `REV${Date.now()}`,
          userId: user.id,
          contractCode: editingRev.contractCode,
          contractValue: editingRev.contractValue || 0,
          amountCollected: Number(editingRev.amountCollected),
          type: editingRev.type as RevenueType,
          date: editingRev.date || new Date().toISOString(),
          isApproved: editingRev.isApproved || false,
          customerName: editingRev.customerName,
          phone: editingRev.phone
      };
      if (editingRev.id) await storageService.updateRevenue(rev, user);
      else await storageService.addRevenue(rev, user);
      setRevModalOpen(false); refreshData();
  };
  const handleDeleteRevenue = async (id: string) => { if (confirm("Xóa doanh thu này?")) { await storageService.deleteRevenue(id, user); refreshData(); } };

  // --- Handlers: APPOINTMENT ---
  const handleSaveApp = async () => {
      if (!editingApp.customerName || !editingApp.phone || !editingApp.date) return alert("Vui lòng điền đủ thông tin");
      const app: Appointment = {
          id: editingApp.id || `APP${Date.now()}`,
          userId: user.id,
          companyName: editingApp.companyName || '',
          customerName: editingApp.customerName,
          phone: editingApp.phone,
          status: editingApp.status as AppointmentStatus || AppointmentStatus.NEW,
          date: editingApp.date,
          location: editingApp.location || '',
          notes: editingApp.notes || '',
          source: editingApp.source || ''
      };
      if (editingApp.id) await storageService.updateAppointment(app, user);
      else await storageService.addAppointment(app, user);
      setAppModalOpen(false); refreshData();
  };
  const handleDeleteApp = async (id: string) => { if (confirm("Xóa cuộc hẹn này?")) { await storageService.deleteAppointment(id, user); refreshData(); } };

  // --- Handlers: CONSULTATION ---
  const handleSaveCons = async () => {
      if (!editingCons.customerName || !editingCons.phone || !editingCons.type) return alert("Vui lòng điền đủ thông tin");
      const cons: Consultation = {
          id: editingCons.id || `CON${Date.now()}`,
          userId: user.id,
          customerName: editingCons.customerName,
          phone: editingCons.phone,
          type: editingCons.type as ConsultationType,
          supportType: editingCons.supportType as SupportType || SupportType.SOLO,
          date: editingCons.date || new Date().toISOString(),
          companyName: editingCons.companyName || '',
          notes: editingCons.notes || ''
      };
      if (editingCons.id) await storageService.updateConsultation(cons, user);
      else await storageService.addConsultation(cons, user);
      setConsModalOpen(false); refreshData();
  };
  const handleDeleteCons = async (id: string) => { if (confirm("Xóa tư vấn này?")) { await storageService.deleteConsultation(id, user); refreshData(); } };

  // --- Handlers: PROJECT ---
  const handleSaveProject = async () => {
      if (!editingProj.contractCode) return alert("Thiếu mã hợp đồng");
      const proj: ProjectProfile = {
          ...editingProj,
          userId: user.id,
          contractCode: editingProj.contractCode,
      };
      await storageService.updateProject(proj, {id: user.id, name: user.name});
      setProjModalOpen(false); refreshData();
  };
  const handleDeleteProject = async (code: string) => { 
      if (confirm("Xóa hồ sơ dự án này?")) { 
          await storageService.deleteProject(code, {id: user.id, name: user.name}); 
          refreshData(); 
      } 
  };

  const totalRevenue = revenues.reduce((s, r) => s + r.amountCollected, 0) + (user.initialRevenue || 0);

  return (
    <div className="space-y-6">
        {/* Header Stats */}
        {!isViewOnly && (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100">
                    <div className="text-xs font-bold text-gray-400 uppercase">Doanh thu tổng</div>
                    <div className="text-xl font-black text-green-600 mt-1">{new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(totalRevenue)}</div>
                </div>
                <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100">
                    <div className="text-xs font-bold text-gray-400 uppercase">Lịch hẹn</div>
                    <div className="text-xl font-black text-blue-600 mt-1">{appointments.length}</div>
                </div>
                <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100">
                    <div className="text-xs font-bold text-gray-400 uppercase">Tư vấn</div>
                    <div className="text-xl font-black text-teal-600 mt-1">{consultations.length}</div>
                </div>
                <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100">
                    <div className="text-xs font-bold text-gray-400 uppercase">Dự án</div>
                    <div className="text-xl font-black text-purple-600 mt-1">{projects.length}</div>
                </div>
            </div>
        )}

        {/* Tabs */}
        <div className="flex space-x-2 border-b overflow-x-auto pb-1">
            <button onClick={() => setActiveTab('revenues')} className={`px-4 py-2 text-sm font-bold uppercase whitespace-nowrap ${activeTab === 'revenues' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500'}`}>Doanh thu</button>
            <button onClick={() => setActiveTab('appointments')} className={`px-4 py-2 text-sm font-bold uppercase whitespace-nowrap ${activeTab === 'appointments' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500'}`}>Lịch hẹn</button>
            <button onClick={() => setActiveTab('consultations')} className={`px-4 py-2 text-sm font-bold uppercase whitespace-nowrap ${activeTab === 'consultations' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500'}`}>Tư vấn</button>
            <button onClick={() => setActiveTab('projects')} className={`px-4 py-2 text-sm font-bold uppercase whitespace-nowrap ${activeTab === 'projects' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500'}`}>Hồ sơ dự án</button>
        </div>

        {/* REVENUE TAB */}
        {activeTab === 'revenues' && (
            <Card title="Danh sách doanh thu">
                {!isViewOnly && (
                    <div className="mb-4 flex justify-end">
                        <Button onClick={() => { setEditingRev({ date: new Date().toISOString().split('T')[0] }); setRevModalOpen(true); }} size="sm" className="rounded-xl"><Plus size={16} className="mr-1" /> Thêm doanh thu</Button>
                    </div>
                )}
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="text-xs text-gray-500 uppercase bg-gray-50 font-bold">
                            <tr>
                                <th className="px-6 py-3">Ngày</th>
                                <th className="px-6 py-3">Khách hàng</th>
                                <th className="px-6 py-3">Loại hình</th>
                                <th className="px-6 py-3">Hợp đồng</th>
                                <th className="px-6 py-3 text-right">Giá trị</th>
                                {!isViewOnly && <th className="px-6 py-3 text-right">Thao tác</th>}
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {revenues.length === 0 ? <tr><td colSpan={6} className="p-4 text-center text-gray-400 text-xs italic">Chưa có dữ liệu</td></tr> : revenues.map(r => (
                                <tr key={r.id} className="hover:bg-gray-50">
                                    <td className="px-6 py-4 whitespace-nowrap font-medium text-gray-700">{new Date(r.date).toLocaleDateString('vi-VN')}</td>
                                    <td className="px-6 py-4">
                                        <div className="font-bold text-gray-800">{r.customerName}</div>
                                        <div className="text-xs text-gray-400">{r.phone}</div>
                                    </td>
                                    <td className="px-6 py-4"><Badge>{r.type}</Badge></td>
                                    <td className="px-6 py-4 font-mono text-xs">{r.contractCode}</td>
                                    <td className="px-6 py-4 text-right font-black text-green-600">{new Intl.NumberFormat('vi-VN').format(r.amountCollected)}</td>
                                    {!isViewOnly && (
                                        <td className="px-6 py-4 text-right">
                                            <button onClick={() => { setEditingRev(r); setRevModalOpen(true); }} className="p-2 text-blue-600 hover:bg-blue-50 rounded"><Edit size={16}/></button>
                                            <button onClick={() => handleDeleteRevenue(r.id)} className="p-2 text-red-600 hover:bg-red-50 rounded"><Trash2 size={16}/></button>
                                        </td>
                                    )}
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </Card>
        )}

        {/* APPOINTMENT TAB */}
        {activeTab === 'appointments' && (
            <Card title="Lịch hẹn khách hàng">
                {!isViewOnly && (
                    <div className="mb-4 flex justify-end">
                        <Button onClick={() => { setEditingApp({ status: AppointmentStatus.NEW, date: new Date().toISOString().split('T')[0] }); setAppModalOpen(true); }} size="sm" className="rounded-xl"><Plus size={16} className="mr-1" /> Tạo lịch hẹn</Button>
                    </div>
                )}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {appointments.map(a => (
                        <div key={a.id} className="p-4 border border-gray-200 rounded-xl hover:shadow-md transition-all bg-white">
                            <div className="flex justify-between items-start mb-2">
                                <Badge variant={a.status === AppointmentStatus.CLOSED ? 'success' : a.status === AppointmentStatus.CANCELLED ? 'error' : 'warning'}>{a.status}</Badge>
                                {!isViewOnly && (
                                    <div className="flex gap-1">
                                        <button onClick={() => { setEditingApp(a); setAppModalOpen(true); }} className="text-gray-400 hover:text-blue-600 p-1"><Edit size={14}/></button>
                                        <button onClick={() => handleDeleteApp(a.id)} className="text-gray-400 hover:text-red-600 p-1"><Trash2 size={14}/></button>
                                    </div>
                                )}
                            </div>
                            <h4 className="font-bold text-gray-800">{a.customerName}</h4>
                            <div className="text-xs text-gray-500 mb-2">{a.phone} • {a.companyName}</div>
                            <div className="flex items-center gap-2 text-xs text-gray-600 mt-2 bg-gray-50 p-2 rounded">
                                <Calendar size={14}/> {new Date(a.date).toLocaleDateString('vi-VN')}
                                <span className="text-gray-300">|</span>
                                <span>{a.location}</span>
                            </div>
                        </div>
                    ))}
                    {appointments.length === 0 && <div className="col-span-2 text-center text-gray-400 py-8 italic text-sm">Chưa có lịch hẹn nào</div>}
                </div>
            </Card>
        )}

        {/* CONSULTATION TAB */}
        {activeTab === 'consultations' && (
            <Card title="Nhật ký tư vấn">
                {!isViewOnly && (
                    <div className="mb-4 flex justify-end">
                        <Button onClick={() => { setEditingCons({ type: ConsultationType.NEW, supportType: SupportType.SOLO, date: new Date().toISOString().split('T')[0] }); setConsModalOpen(true); }} size="sm" className="rounded-xl"><Plus size={16} className="mr-1" /> Thêm tư vấn</Button>
                    </div>
                )}
                 <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="text-xs text-gray-500 uppercase bg-gray-50 font-bold">
                            <tr>
                                <th className="px-6 py-3">Ngày</th>
                                <th className="px-6 py-3">Khách hàng</th>
                                <th className="px-6 py-3">Loại hình</th>
                                <th className="px-6 py-3">Hình thức</th>
                                <th className="px-6 py-3">Ghi chú</th>
                                {!isViewOnly && <th className="px-6 py-3 text-right">Thao tác</th>}
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {consultations.map(c => (
                                <tr key={c.id} className="hover:bg-gray-50">
                                    <td className="px-6 py-4 text-gray-600">{new Date(c.date).toLocaleDateString('vi-VN')}</td>
                                    <td className="px-6 py-4 font-bold text-gray-800">{c.customerName}<div className="text-[10px] text-gray-400 font-normal">{c.phone}</div></td>
                                    <td className="px-6 py-4"><Badge variant="info">{c.type}</Badge></td>
                                    <td className="px-6 py-4 text-xs">{c.supportType}</td>
                                    <td className="px-6 py-4 text-xs text-gray-500 max-w-xs truncate" title={c.notes}>{c.notes}</td>
                                    {!isViewOnly && (
                                        <td className="px-6 py-4 text-right">
                                            <button onClick={() => { setEditingCons(c); setConsModalOpen(true); }} className="p-2 text-blue-600 hover:bg-blue-50 rounded"><Edit size={16}/></button>
                                            <button onClick={() => handleDeleteCons(c.id)} className="p-2 text-red-600 hover:bg-red-50 rounded"><Trash2 size={16}/></button>
                                        </td>
                                    )}
                                </tr>
                            ))}
                             {consultations.length === 0 && <tr><td colSpan={6} className="p-4 text-center text-gray-400 text-xs italic">Chưa có dữ liệu</td></tr>}
                        </tbody>
                    </table>
                </div>
            </Card>
        )}

        {/* PROJECTS TAB (Using the structure referenced in errors) */}
        {activeTab === 'projects' && (
            <Card title="Hồ sơ triển khai dự án">
                 {!isViewOnly && (
                    <div className="mb-4 flex justify-end">
                        <Button onClick={() => { setEditingProj({}); setProjModalOpen(true); }} size="sm" className="rounded-xl"><Plus size={16} className="mr-1" /> Thêm hồ sơ</Button>
                    </div>
                )}
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left border-collapse">
                         <thead className="text-xs text-gray-500 uppercase bg-gray-50 font-bold border-b border-gray-200">
                            <tr>
                                <th className="px-6 py-4 w-10"></th>
                                <th className="px-6 py-4">Mã HĐ</th>
                                <th className="px-6 py-4">Khách hàng / Công ty</th>
                                <th className="px-6 py-4">Lĩnh vực</th>
                                <th className="px-6 py-4 text-center">Trạng thái</th>
                                <th className="px-6 py-4 text-center">Thao tác</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {projects.map(row => (
                                <React.Fragment key={row.contractCode}>
                                    <tr className={`transition-colors cursor-pointer hover:bg-blue-50/50 ${expandedProjects[row.contractCode] ? 'bg-blue-50' : 'bg-white'}`} onClick={() => toggleProject(row.contractCode)}>
                                         <td className="px-6 py-4 text-center">
                                            <div className={`transition-transform duration-200 text-gray-400 ${expandedProjects[row.contractCode] ? 'rotate-90 text-blue-600' : ''}`}><ChevronRight size={18}/></div>
                                        </td>
                                        <td className="px-6 py-4 font-black font-mono text-gray-700">{row.contractCode}</td>
                                        <td className="px-6 py-4">
                                            <div className="font-bold text-gray-900">{row.customerName}</div>
                                            <div className="text-xs text-gray-500">{row.companyName}</div>
                                        </td>
                                        <td className="px-6 py-4 text-gray-600">{row.industry}</td>
                                        <td className="px-6 py-4 text-center"><Badge variant={row.status === 'Hoàn thành' ? 'success' : 'warning'}>{row.status || 'Đang triển khai'}</Badge></td>
                                        <td className="px-6 py-4 align-middle text-center">
                                            <div className="flex items-center justify-center gap-1">
                                                {!isViewOnly && (
                                                    <>
                                                        <button 
                                                            onClick={(e) => { e.stopPropagation(); setEditingProj(row); setProjModalOpen(true); }}
                                                            className="p-2 rounded-full hover:bg-blue-50 text-gray-400 hover:text-blue-600 transition-colors"
                                                            title="Sửa dự án"
                                                        >
                                                            <Edit size={16} />
                                                        </button>
                                                        <button 
                                                            onClick={(e) => { e.stopPropagation(); handleDeleteProject(row.contractCode); }}
                                                            className="p-2 rounded-full hover:bg-red-50 text-gray-400 hover:text-red-600 transition-colors"
                                                            title="Xóa dự án"
                                                        >
                                                            <Trash2 size={16} />
                                                        </button>
                                                    </>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                    {expandedProjects[row.contractCode] && (
                                        <tr className="bg-gray-50/50 animate-fadeIn">
                                            <td colSpan={6} className="px-6 py-6 border-b border-blue-100">
                                                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 text-sm">
                                                    <div className="space-y-3">
                                                        <h5 className="font-bold text-gray-800 uppercase text-xs tracking-wider border-b pb-1">Thông tin liên hệ</h5>
                                                        <div><span className="text-gray-500 block text-xs">Điện thoại:</span> <span className="font-medium">{row.phone}</span></div>
                                                        <div><span className="text-gray-500 block text-xs">Email:</span> <span className="font-medium">{row.email || 'N/A'}</span></div>
                                                        <div><span className="text-gray-500 block text-xs">Địa chỉ:</span> <span className="font-medium">{row.address || 'N/A'}</span></div>
                                                    </div>
                                                    <div className="space-y-3">
                                                        <h5 className="font-bold text-gray-800 uppercase text-xs tracking-wider border-b pb-1">Chi tiết kỹ thuật</h5>
                                                        <div><span className="text-gray-500 block text-xs">Gói Hosting:</span> <span className="font-medium">{row.hostingSize || 'N/A'}</span></div>
                                                        <div><span className="text-gray-500 block text-xs">Link Web:</span> {row.webLink ? <a href={row.webLink} target="_blank" className="text-blue-600 hover:underline flex items-center gap-1">{row.webLink} <ExternalLink size={10}/></a> : 'N/A'}</div>
                                                        <div><span className="text-gray-500 block text-xs">Pass Web:</span> <span className="font-mono bg-gray-100 px-1 rounded">{row.webPassword || '***'}</span></div>
                                                    </div>
                                                    <div className="space-y-3">
                                                        <h5 className="font-bold text-gray-800 uppercase text-xs tracking-wider border-b pb-1">Thông tin khác</h5>
                                                        <div><span className="text-gray-500 block text-xs">Link Design:</span> {row.designLink ? <a href={row.designLink} target="_blank" className="text-blue-600 hover:underline flex items-center gap-1">Xem Design <ExternalLink size={10}/></a> : 'N/A'}</div>
                                                        <div><span className="text-gray-500 block text-xs">Group Zalo:</span> {row.zaloGroup ? <a href={row.zaloGroup} target="_blank" className="text-blue-600 hover:underline">Tham gia nhóm</a> : 'N/A'}</div>
                                                        <div><span className="text-gray-500 block text-xs">Người ký chung:</span> <span className="font-medium">{row.jointSigner || 'Không'}</span></div>
                                                    </div>
                                                </div>
                                            </td>
                                        </tr>
                                    )}
                                </React.Fragment>
                            ))}
                             {projects.length === 0 && <tr><td colSpan={6} className="p-8 text-center text-gray-400 italic">Chưa có hồ sơ dự án nào</td></tr>}
                        </tbody>
                    </table>
                </div>
            </Card>
        )}

        {/* MODALS */}
        <Modal isOpen={isRevModalOpen} onClose={() => setRevModalOpen(false)} title="THÔNG TIN DOANH THU">
             <div className="space-y-4 p-1">
                 <div className="grid grid-cols-2 gap-4">
                     <Input label="Mã Hợp Đồng" value={editingRev.contractCode || ''} onChange={e => setEditingRev({...editingRev, contractCode: e.target.value})} placeholder="HĐ..." />
                     <Input label="Ngày ghi nhận" type="date" value={editingRev.date ? editingRev.date.substring(0,10) : ''} onChange={e => setEditingRev({...editingRev, date: e.target.value})} />
                 </div>
                 <Input label="Tên khách hàng" value={editingRev.customerName || ''} onChange={e => setEditingRev({...editingRev, customerName: e.target.value})} />
                 <Select label="Loại doanh thu" value={editingRev.type} onChange={e => setEditingRev({...editingRev, type: e.target.value as RevenueType})} options={Object.values(RevenueType).map(v => ({value: v, label: v}))} />
                 <Input label="Giá trị thu về (VND)" type="number" value={editingRev.amountCollected} onChange={e => setEditingRev({...editingRev, amountCollected: Number(e.target.value)})} />
                 <div className="flex justify-end gap-3 pt-4 border-t"><Button variant="ghost" onClick={() => setRevModalOpen(false)}>Hủy</Button><Button onClick={handleSaveRevenue} className="px-6">Lưu</Button></div>
             </div>
        </Modal>

        <Modal isOpen={isAppModalOpen} onClose={() => setAppModalOpen(false)} title="CHI TIẾT LỊCH HẸN">
            <div className="space-y-4 p-1">
                <Input label="Khách hàng" value={editingApp.customerName || ''} onChange={e => setEditingApp({...editingApp, customerName: e.target.value})} />
                <div className="grid grid-cols-2 gap-4">
                    <Input label="Số điện thoại" value={editingApp.phone || ''} onChange={e => setEditingApp({...editingApp, phone: e.target.value})} />
                    <Input label="Tên công ty" value={editingApp.companyName || ''} onChange={e => setEditingApp({...editingApp, companyName: e.target.value})} />
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <Input label="Thời gian" type="date" value={editingApp.date ? editingApp.date.substring(0,10) : ''} onChange={e => setEditingApp({...editingApp, date: e.target.value})} />
                    <Select label="Trạng thái" value={editingApp.status} onChange={e => setEditingApp({...editingApp, status: e.target.value as AppointmentStatus})} options={Object.values(AppointmentStatus).map(v => ({value: v, label: v}))} />
                </div>
                <Input label="Địa điểm / Ghi chú" value={editingApp.location || ''} onChange={e => setEditingApp({...editingApp, location: e.target.value})} />
                <div className="flex justify-end gap-3 pt-4 border-t"><Button variant="ghost" onClick={() => setAppModalOpen(false)}>Hủy</Button><Button onClick={handleSaveApp} className="px-6">Lưu</Button></div>
            </div>
        </Modal>

        <Modal isOpen={isConsModalOpen} onClose={() => setConsModalOpen(false)} title="NHẬT KÝ TƯ VẤN">
            <div className="space-y-4 p-1">
                <Input label="Khách hàng" value={editingCons.customerName || ''} onChange={e => setEditingCons({...editingCons, customerName: e.target.value})} />
                <Input label="Số điện thoại" value={editingCons.phone || ''} onChange={e => setEditingCons({...editingCons, phone: e.target.value})} />
                <div className="grid grid-cols-2 gap-4">
                    <Select label="Loại tư vấn" value={editingCons.type} onChange={e => setEditingCons({...editingCons, type: e.target.value as ConsultationType})} options={Object.values(ConsultationType).map(v => ({value: v, label: v}))} />
                    <Select label="Hình thức" value={editingCons.supportType} onChange={e => setEditingCons({...editingCons, supportType: e.target.value as SupportType})} options={Object.values(SupportType).map(v => ({value: v, label: v}))} />
                </div>
                <div className="w-full"><label className="block text-sm font-semibold text-gray-700 mb-1">Nội dung / Ghi chú</label><textarea className="w-full border border-gray-300 rounded-md p-2 text-sm" rows={3} value={editingCons.notes || ''} onChange={e => setEditingCons({...editingCons, notes: e.target.value})}></textarea></div>
                <div className="flex justify-end gap-3 pt-4 border-t"><Button variant="ghost" onClick={() => setConsModalOpen(false)}>Hủy</Button><Button onClick={handleSaveCons} className="px-6">Lưu</Button></div>
            </div>
        </Modal>

