  // State for data
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [consultations, setConsultations] = useState<Consultation[]>([]);
  const [revenues, setRevenues] = useState<Revenue[]>([]);
  const [projects, setProjects] = useState<ProjectProfile[]>([]);
  const [loading, setLoading] = useState(true);

  // Active Tab
  const [activeTab, setActiveTab] = useState<'appointments' | 'consultations' | 'revenues' | 'projects'>('appointments');

  // State for Project Expansion
  const [expandedProjects, setExpandedProjects] = useState<Record<string, boolean>>({});

  // Modals state
  const [isAppModalOpen, setAppModalOpen] = useState(false);
  const [editingApp, setEditingApp] = useState<Partial<Appointment>>({});

  const [isConsModalOpen, setConsModalOpen] = useState(false);
  const [editingCons, setEditingCons] = useState<Partial<Consultation>>({});

  const [isRevModalOpen, setRevModalOpen] = useState(false);
  const [editingRev, setEditingRev] = useState<Partial<Revenue>>({});

  const [isProjModalOpen, setProjModalOpen] = useState(false);
  const [editingProj, setEditingProj] = useState<Partial<ProjectProfile>>({});

  // Fetch Data
  const loadData = async () => {
    setLoading(true);
    try {
        const [allApps, allCons, allRevs, allProjs] = await Promise.all([
            storageService.getAppointments(),
            storageService.getConsultations(),
            storageService.getRevenues(),
            storageService.getProjects(),
        ]);

        setAppointments(allApps.filter(a => a.userId === user.id).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
        setConsultations(allCons.filter(c => c.userId === user.id).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
        setRevenues(allRevs.filter(r => r.userId === user.id).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
        setProjects(allProjs.filter(p => p.userId === user.id));

    } catch (error) {
        console.error("Error loading employee data", error);
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [user.id]);

  const toggleProject = (contractCode: string) => {
      setExpandedProjects(prev => ({ ...prev, [contractCode]: !prev[contractCode] }));
  };

  // --- Handlers ---

  // Appointments
  const handleSaveApp = async () => {
      if (!editingApp.customerName || !editingApp.phone || !editingApp.date) return alert("Thiếu thông tin bắt buộc");
      try {
          const appData = { 
              ...editingApp, 
              userId: user.id, 
              status: editingApp.status || AppointmentStatus.NEW 
          } as Appointment;

          if (!appData.id) appData.id = `APP_${Date.now()}`;

          if (editingApp.id) await storageService.updateAppointment(appData, {id: user.id, name: user.name});
          else await storageService.addAppointment(appData, {id: user.id, name: user.name});

          setAppModalOpen(false);
          loadData();
      } catch (e: any) { alert(e.message); }
  };
  const handleDeleteApp = async (id: string) => {
      if (!confirm("Xóa cuộc hẹn này?")) return;
      await storageService.deleteAppointment(id, {id: user.id, name: user.name});
      loadData();
  };

  // Consultations
  const handleSaveCons = async () => {
      if (!editingCons.customerName || !editingCons.phone || !editingCons.date) return alert("Thiếu thông tin bắt buộc");
      try {
          const consData = { 
              ...editingCons, 
              userId: user.id,
              type: editingCons.type || ConsultationType.NEW,
              supportType: editingCons.supportType || SupportType.SOLO
          } as Consultation;

          if (!consData.id) consData.id = `CONS_${Date.now()}`;

          if (editingCons.id) await storageService.updateConsultation(consData, {id: user.id, name: user.name});
          else await storageService.addConsultation(consData, {id: user.id, name: user.name});

          setConsModalOpen(false);
          loadData();
      } catch (e: any) { alert(e.message); }
  };
  const handleDeleteCons = async (id: string) => {
      if (!confirm("Xóa phiếu tư vấn này?")) return;
      await storageService.deleteConsultation(id, {id: user.id, name: user.name});
      loadData();
  };

  // Revenues
  const handleSaveRev = async () => {
      if (!editingRev.contractCode || !editingRev.amountCollected || !editingRev.date) return alert("Thiếu thông tin bắt buộc");
      try {
          const revData = { 
              ...editingRev, 
              userId: user.id, 
              type: editingRev.type || RevenueType.NEW,
              isApproved: editingRev.isApproved || false,
              contractValue: editingRev.contractValue || editingRev.amountCollected
          } as Revenue;

          if (!revData.id) revData.id = `REV_${Date.now()}`;

          if (editingRev.id) await storageService.updateRevenue(revData, {id: user.id, name: user.name});
          else await storageService.addRevenue(revData, {id: user.id, name: user.name});

          // Auto create project if new contract
          if (revData.type === RevenueType.NEW) {
              const existingProj = projects.find(p => p.contractCode === revData.contractCode);
              if (!existingProj) {
                  await storageService.addProject({
                      contractCode: revData.contractCode,
                      userId: user.id,
                      customerName: revData.customerName || '',
                      phone: revData.phone || '',
                      contractValue: revData.contractValue
                  });
              }
          }

          setRevModalOpen(false);
          loadData();
      } catch (e: any) { alert(e.message); }
  };
  const handleDeleteRev = async (id: string) => {
      if (!confirm("Xóa khoản thu này?")) return;
      await storageService.deleteRevenue(id, {id: user.id, name: user.name});
      loadData();
  };

  // Projects
  const handleSaveProject = async () => {
      if (!editingProj.contractCode) return alert("Thiếu mã hợp đồng");
      try {
          const projData = { ...editingProj, userId: user.id } as ProjectProfile;
          const exists = projects.some(p => p.contractCode === editingProj.contractCode);
          if (exists) {
              await storageService.updateProject(projData, {id: user.id, name: user.name});
          } else {
              await storageService.addProject(projData);
          }

          setProjModalOpen(false);
          loadData();
      } catch (e: any) { alert(e.message); }
  };

  const handleDeleteProject = async (contractCode: string) => {
      if (!confirm(`Bạn chắc chắn muốn xóa dự án ${contractCode}?`)) return;
      try {
          await storageService.deleteProject(contractCode, {id: user.id, name: user.name});
          setProjModalOpen(false);
          loadData();
      } catch (e: any) { alert(e.message); }
  };

  // Statistics
  const totalRevenue = revenues.reduce((sum, r) => sum + r.amountCollected, 0);
  const currentMonth = new Date().toISOString().substring(0, 7); // YYYY-MM
  const monthRevenues = revenues.filter(r => r.date.startsWith(currentMonth)).reduce((sum, r) => sum + r.amountCollected, 0);
  const monthApps = appointments.filter(a => a.date.startsWith(currentMonth)).length;
  const monthCons = consultations.filter(c => c.date.startsWith(currentMonth)).length;

  return (
    <div className="space-y-6">
      {/* Stats Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card className="bg-gradient-to-br from-blue-600 to-indigo-700 text-white border-none shadow-lg shadow-blue-200">
            <div className="flex flex-col justify-between h-full">
                <div className="flex justify-between items-start">
                    <p className="text-blue-100 text-[10px] font-bold uppercase tracking-wider">Doanh thu tổng</p>
                    <div className="bg-white/20 p-1.5 rounded-lg"><DollarSign size={16}/></div>
                </div>
                <div>
                    <h3 className="text-2xl font-black">{new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(totalRevenue + (user.initialRevenue || 0))}</h3>
                    <div className="mt-1 text-[10px] text-blue-100 font-medium opacity-80">Lifetime Total</div>
                </div>
            </div>
        </Card>

        <Card>
            <div className="flex flex-col justify-between h-full">
                <div className="flex justify-between items-start">
                    <p className="text-gray-400 text-[10px] font-bold uppercase tracking-wider">Tháng này</p>
                    <div className="bg-green-50 text-green-600 p-1.5 rounded-lg"><TrendingUp size={16}/></div>
                </div>
                 <div>
                    <h3 className="text-xl font-black text-gray-800">{new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(monthRevenues)}</h3>
                    <div className="mt-1 text-[10px] text-gray-400">Doanh thu thực tế</div>
                </div>
            </div>
        </Card>

        <Card>
            <div className="flex flex-col justify-between h-full">
                <div className="flex justify-between items-start">
                    <p className="text-gray-400 text-[10px] font-bold uppercase tracking-wider">Cuộc hẹn</p>
                    <div className="bg-orange-50 text-orange-600 p-1.5 rounded-lg"><Calendar size={16}/></div>
                </div>
                <div>
                    <h3 className="text-xl font-black text-gray-800">{monthApps}</h3>
                    <div className="mt-1 text-[10px] text-gray-400">Lịch hẹn tháng này</div>
                </div>
            </div>
        </Card>

        <Card>
            <div className="flex flex-col justify-between h-full">
                <div className="flex justify-between items-start">
                    <p className="text-gray-400 text-[10px] font-bold uppercase tracking-wider">Tư vấn</p>
                    <div className="bg-purple-50 text-purple-600 p-1.5 rounded-lg"><MessageSquare size={16}/></div>
                </div>
                <div>
                    <h3 className="text-xl font-black text-gray-800">{monthCons}</h3>
                    <div className="mt-1 text-[10px] text-gray-400">Phiếu tư vấn tháng này</div>
                </div>
            </div>
        </Card>
      </div>

      {/* Tabs & Controls */}
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-2 rounded-xl border border-gray-100 shadow-sm sticky top-0 z-10 backdrop-blur-sm bg-white/90">
          <div className="flex bg-gray-100 p-1 rounded-lg w-full md:w-auto overflow-x-auto">
              <button onClick={() => setActiveTab('appointments')} className={`flex-1 md:flex-none px-4 py-2 text-xs font-bold uppercase rounded-md transition-all whitespace-nowrap ${activeTab === 'appointments' ? 'bg-white shadow text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}>Cuộc hẹn</button>
              <button onClick={() => setActiveTab('consultations')} className={`flex-1 md:flex-none px-4 py-2 text-xs font-bold uppercase rounded-md transition-all whitespace-nowrap ${activeTab === 'consultations' ? 'bg-white shadow text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}>Tư vấn</button>
              <button onClick={() => setActiveTab('revenues')} className={`flex-1 md:flex-none px-4 py-2 text-xs font-bold uppercase rounded-md transition-all whitespace-nowrap ${activeTab === 'revenues' ? 'bg-white shadow text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}>Doanh thu</button>
              <button onClick={() => setActiveTab('projects')} className={`flex-1 md:flex-none px-4 py-2 text-xs font-bold uppercase rounded-md transition-all whitespace-nowrap ${activeTab === 'projects' ? 'bg-white shadow text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}>Dự án</button>
          </div>
          {!isViewOnly && (
             <div className="w-full md:w-auto">
                 {activeTab === 'appointments' && <Button onClick={() => { setEditingApp({ date: new Date().toISOString().slice(0, 16), status: AppointmentStatus.NEW }); setAppModalOpen(true); }} size="sm" className="w-full md:w-auto shadow-lg shadow-blue-100 font-bold"><Plus size={16} className="mr-1"/> THÊM CUỘC HẸN</Button>}
                 {activeTab === 'consultations' && <Button onClick={() => { setEditingCons({ date: new Date().toISOString().slice(0, 16), type: ConsultationType.NEW, supportType: SupportType.SOLO }); setConsModalOpen(true); }} size="sm" className="w-full md:w-auto shadow-lg shadow-blue-100 font-bold"><Plus size={16} className="mr-1"/> THÊM TƯ VẤN</Button>}
                 {activeTab === 'revenues' && <Button onClick={() => { setEditingRev({ date: new Date().toISOString().slice(0, 10), type: RevenueType.NEW }); setRevModalOpen(true); }} size="sm" className="w-full md:w-auto shadow-lg shadow-blue-100 font-bold"><Plus size={16} className="mr-1"/> THÊM DOANH THU</Button>}
                 {activeTab === 'projects' && <Button onClick={() => { setEditingProj({}); setProjModalOpen(true); }} size="sm" className="w-full md:w-auto shadow-lg shadow-blue-100 font-bold"><Plus size={16} className="mr-1"/> THÊM HỒ SƠ</Button>}
             </div>
          )}
      </div>

      {/* Content */}
      <div className="bg-transparent min-h-[400px]">
          {activeTab === 'appointments' && (
              <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
                  <table className="w-full text-sm text-left">
                      <thead className="text-xs text-gray-500 uppercase bg-gray-50 font-bold border-b border-gray-100">
                          <tr>
                              <th className="px-6 py-4 w-[160px]">Thời gian</th>
                              <th className="px-6 py-4">Khách hàng</th>
                              <th className="px-6 py-4">Thông tin liên hệ</th>
                              <th className="px-6 py-4">Trạng thái</th>
                              <th className="px-6 py-4 hidden md:table-cell">Ghi chú</th>
                              {!isViewOnly && <th className="px-6 py-4 text-right w-[100px]">#</th>}
                          </tr>
                      </thead>
                      <tbody className="divide-y divide-gray-100">
                          {appointments.map(app => (
                              <tr key={app.id} className="hover:bg-blue-50/30 transition-colors group">
                                  <td className="px-6 py-4">
                                      <div className="flex flex-col">
                                          <span className="font-bold text-gray-800 text-sm">{new Date(app.date).toLocaleDateString('vi-VN')}</span>
                                          <span className="text-xs text-blue-600 font-medium flex items-center gap-1 mt-1">
                                              <Clock size={12}/> {new Date(app.date).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit'})}
                                          </span>
                                      </div>
                                  </td>
                                  <td className="px-6 py-4">
                                      <div className="font-bold text-gray-800 text-base">{app.customerName}</div>
                                      {app.companyName && (
                                          <div className="flex items-center gap-1 mt-1 text-xs text-gray-500">
                                              <Building2 size={10}/> {app.companyName}
                                          </div>
                                      )}
                                  </td>
                                  <td className="px-6 py-4">
                                      <div className="text-sm text-gray-600 font-medium flex items-center gap-1.5">
                                          <Phone size={14} className="text-gray-400"/> {app.phone}
                                      </div>
                                      {app.location && (
                                          <div className="text-xs text-gray-500 mt-1 flex items-center gap-1.5 truncate max-w-[200px]">
                                              <MapPin size={12} className="text-gray-400"/> {app.location}
                                          </div>
                                      )}
                                  </td>
                                  <td className="px-6 py-4">
                                      <Badge variant={app.status === AppointmentStatus.CLOSED ? 'success' : app.status === AppointmentStatus.CANCELLED ? 'error' : 'warning'}>
                                          {app.status}
                                      </Badge>
                                  </td>
                                  <td className="px-6 py-4 hidden md:table-cell">
                                      {app.notes ? <span className="text-gray-500 text-xs italic truncate max-w-[200px] block">{app.notes}</span> : <span className="text-gray-300 text-xs italic">-</span>}
                                  </td>
                                  {!isViewOnly && (
                                      <td className="px-6 py-4 text-right">
                                          <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                              <button onClick={() => { setEditingApp(app); setAppModalOpen(true); }} className="p-2 text-blue-600 hover:bg-blue-100 rounded transition-all"><Edit size={16}/></button>
                                              <button onClick={() => handleDeleteApp(app.id)} className="p-2 text-red-600 hover:bg-red-100 rounded transition-all"><Trash2 size={16}/></button>
                                          </div>
                                      </td>
                                  )}
                              </tr>
                          ))}
                          {appointments.length === 0 && <tr><td colSpan={6} className="text-center py-12 text-gray-400 italic">Chưa có lịch hẹn nào</td></tr>}
                      </tbody>
                  </table>
              </div>
          )}

          {activeTab === 'consultations' && (
              <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
                <table className="w-full text-sm text-left">
                    <thead className="text-xs text-gray-500 uppercase bg-gray-50 font-bold border-b border-gray-100">
                        <tr>
                            <th className="px-6 py-4 w-[150px]">Ngày & Loại</th>
                            <th className="px-6 py-4">Khách hàng</th>
                            <th className="px-6 py-4">Hình thức & Hỗ trợ</th>
                            <th className="px-6 py-4 hidden md:table-cell">Nội dung</th>
                            {!isViewOnly && <th className="px-6 py-4 text-right w-[100px]">#</th>}
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {consultations.map(c => (
                            <tr key={c.id} className="hover:bg-purple-50/30 transition-colors group">
                                <td className="px-6 py-4">
                                    <div className="font-bold text-gray-800">{new Date(c.date).toLocaleDateString('vi-VN')}</div>
                                    <div className="mt-1"><Badge variant="info" className="text-[10px]">{c.type}</Badge></div>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-3">
                                        <div className="w-8 h-8 rounded-full bg-purple-100 text-purple-600 flex items-center justify-center font-bold text-xs">
                                            {c.customerName.charAt(0)}
                                        </div>
                                        <div>
                                            <div className="font-bold text-gray-800 text-base">{c.customerName}</div>
                                            <div className="text-xs text-gray-500 flex items-center gap-1"><Phone size={10}/> {c.phone}</div>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="text-xs font-bold uppercase text-gray-600 mb-1">{c.supportType}</div>
                                    {c.supportPersonName ? (
                                        <div className="text-[10px] text-gray-500 bg-gray-100 px-2 py-1 rounded w-fit">Hỗ trợ: <span className="font-medium">{c.supportPersonName}</span></div>
                                    ) : <span className="text-[10px] text-gray-300 italic">Không có người hỗ trợ</span>}
                                </td>
                                <td className="px-6 py-4 hidden md:table-cell">
                                    <div className="text-gray-600 text-sm truncate max-w-[250px]">{c.notes}</div>
                                </td>
                                {!isViewOnly && (
                                    <td className="px-6 py-4 text-right">
                                        <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button onClick={() => { setEditingCons(c); setConsModalOpen(true); }} className="text-blue-600 hover:bg-blue-100 p-2 rounded"><Edit size={16}/></button>
                                            <button onClick={() => handleDeleteCons(c.id)} className="text-red-600 hover:bg-red-100 p-2 rounded"><Trash2 size={16}/></button>
                                        </div>
                                    </td>
                                )}
                            </tr>
                        ))}
                        {consultations.length === 0 && <tr><td colSpan={5} className="text-center py-12 text-gray-400 italic">Chưa có dữ liệu tư vấn</td></tr>}
                    </tbody>
                </table>
              </div>
          )}

          {activeTab === 'revenues' && (
              <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
                <table className="w-full text-sm text-left">
                    <thead className="text-xs text-gray-500 uppercase bg-gray-50 font-bold border-b border-gray-100">
                        <tr>
                            <th className="px-6 py-4 w-[120px]">Thời gian</th>
                            <th className="px-6 py-4">Hợp đồng</th>
                            <th className="px-6 py-4">Khách hàng</th>
                            <th className="px-6 py-4 text-right">Giá trị</th>
                            {!isViewOnly && <th className="px-6 py-4 text-right w-[100px]">#</th>}
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {revenues.map(r => (
                            <tr key={r.id} className="hover:bg-green-50/30 transition-colors group">
                                <td className="px-6 py-4">
                                    <div className="text-gray-900 font-bold text-sm">{new Date(r.date).getDate()}</div>
                                    <div className="text-gray-500 text-xs font-medium uppercase">{new Date(r.date).toLocaleString('vi-VN', {month:'long'})}, {new Date(r.date).getFullYear()}</div>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="font-black text-indigo-600 text-sm font-mono tracking-tight">{r.contractCode}</div>
                                    <div className="mt-1"><Badge variant="success" className="text-[9px]">{r.type}</Badge></div>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="font-bold text-gray-800 text-base">{r.customerName}</div>
                                    {r.phone && <div className="text-xs text-gray-400 font-normal">{r.phone}</div>}
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <div className="font-black text-gray-800 text-base">{new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(r.amountCollected)}</div>
                                    <div className="text-[10px] text-green-600 font-medium bg-green-50 rounded px-1.5 py-0.5 inline-block mt-1">Đã thu</div>
                                </td>
                                {!isViewOnly && (
                                    <td className="px-6 py-4 text-right">
                                        <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button onClick={() => { setEditingRev(r); setRevModalOpen(true); }} className="text-blue-600 hover:bg-blue-100 p-2 rounded"><Edit size={16}/></button>
                                            <button onClick={() => handleDeleteRev(r.id)} className="text-red-600 hover:bg-red-100 p-2 rounded"><Trash2 size={16}/></button>
                                        </div>
                                    </td>
                                )}
                            </tr>
                        ))}
                        {revenues.length === 0 && <tr><td colSpan={5} className="text-center py-12 text-gray-400 italic">Chưa có doanh thu</td></tr>}
                    </tbody>
                </table>
              </div>
          )}

          {activeTab === 'projects' && (
              <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
                <table className="w-full text-sm text-left">
                     <thead className="text-xs text-gray-500 uppercase bg-gray-50 font-bold border-b border-gray-200">
                        <tr>
                            <th className="px-6 py-4 w-10"></th>
                            <th className="px-6 py-4">Dự án / HĐ</th>
                            <th className="px-6 py-4">Khách hàng</th>
                            <th className="px-6 py-4 hidden md:table-cell">Tài nguyên</th>
                            <th className="px-6 py-4 text-center">Trạng thái</th>
                            <th className="px-6 py-4 text-center">#</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {projects.map(row => (
                            <React.Fragment key={row.contractCode}>
                                <tr className={`transition-colors cursor-pointer hover:bg-blue-50/50 ${expandedProjects[row.contractCode] ? 'bg-blue-50' : 'bg-white'}`} onClick={() => toggleProject(row.contractCode)}>
                                     <td className="px-6 py-4 text-center">
                                        <div className={`transition-transform duration-200 text-gray-400 ${expandedProjects[row.contractCode] ? 'rotate-90 text-blue-600' : ''}`}><ChevronRight size={18}/></div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="font-black font-mono text-indigo-700">{row.contractCode}</div>
                                        <div className="text-xs text-gray-500 mt-1">{row.industry || 'Chưa cập nhật ngành'}</div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="font-bold text-gray-900">{row.customerName}</div>
                                        <div className="text-xs text-gray-500 flex items-center gap-1 mt-0.5"><Building2 size={10}/> {row.companyName || 'Khách lẻ'}</div>
                                    </td>
                                    {/* Resource Column - Utilizing Empty Space */}
                                    <td className="px-6 py-4 hidden md:table-cell">
                                        <div className="flex gap-2">
                                            {row.webLink ? (
                                                <a href={row.webLink} target="_blank" rel="noreferrer" onClick={e => e.stopPropagation()} className="px-2 py-1 bg-blue-50 text-blue-600 rounded border border-blue-100 text-xs font-bold flex items-center gap-1 hover:bg-blue-100"><Globe size={12}/> Web</a>
                                            ) : <span className="text-xs text-gray-300 italic">No Web</span>}
                                            {row.designLink ? (
                                                <a href={row.designLink} target="_blank" rel="noreferrer" onClick={e => e.stopPropagation()} className="px-2 py-1 bg-pink-50 text-pink-600 rounded border border-pink-100 text-xs font-bold flex items-center gap-1 hover:bg-pink-100"><Layers size={12}/> Design</a>
                                            ) : <span className="text-xs text-gray-300 italic">No Design</span>}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-center"><Badge variant={row.status === 'Hoàn thành' ? 'success' : 'warning'}>{row.status || 'Đang triển khai'}</Badge></td>
                                    <td className="px-6 py-4 align-middle text-center">
                                        {!isViewOnly && (
                                            <button 
                                                onClick={(e) => { e.stopPropagation(); setEditingProj(row); setProjModalOpen(true); }}
                                                className="p-2 rounded-full hover:bg-blue-50 text-gray-400 hover:text-blue-600 transition-colors"
                                                title="Sửa dự án"
                                            >
                                                <Edit size={16} />
                                            </button>
                                        )}
                                    </td>
                                </tr>
                                {expandedProjects[row.contractCode] && (
                                    <tr className="bg-gray-50/50 animate-fadeIn">
                                        <td colSpan={6} className="px-6 py-6 border-b border-blue-100">
                                            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 text-sm">
                                                <div className="space-y-3">
                                                    <h5 className="font-bold text-gray-800 uppercase text-xs tracking-wider border-b pb-1">Thông tin liên hệ</h5>
                                                    <div><span className="text-gray-500 block text-xs">Điện thoại:</span> <span className="font-medium text-gray-800">{row.phone}</span></div>
                                                    <div><span className="text-gray-500 block text-xs">Email:</span> <span className="font-medium text-gray-800">{row.email || 'N/A'}</span></div>
                                                    <div><span className="text-gray-500 block text-xs">Địa chỉ:</span> <span className="font-medium text-gray-800">{row.address || 'N/A'}</span></div>
                                                </div>
                                                <div className="space-y-3">
                                                    <h5 className="font-bold text-gray-800 uppercase text-xs tracking-wider border-b pb-1">Chi tiết kỹ thuật</h5>
                                                    <div><span className="text-gray-500 block text-xs">Gói Hosting:</span> <span className="font-medium text-gray-800">{row.hostingSize || 'N/A'}</span></div>
                                                    <div><span className="text-gray-500 block text-xs">Link Web:</span> {row.webLink ? <a href={row.webLink} target="_blank" className="text-blue-600 hover:underline flex items-center gap-1">{row.webLink} <ExternalLink size={10}/></a> : 'N/A'}</div>
                                                    <div><span className="text-gray-500 block text-xs">Pass Web:</span> <span className="font-mono bg-white border border-gray-200 px-1 rounded text-gray-600 select-all">{row.webPassword || '***'}</span></div>
                                                </div>
                                                <div className="space-y-3">
                                                    <h5 className="font-bold text-gray-800 uppercase text-xs tracking-wider border-b pb-1">Thông tin khác</h5>
                                                    <div><span className="text-gray-500 block text-xs">Link Design:</span> {row.designLink ? <a href={row.designLink} target="_blank" className="text-blue-600 hover:underline flex items-center gap-1">Xem Design <ExternalLink size={10}/></a> : 'N/A'}</div>
                                                    <div><span className="text-gray-500 block text-xs">Group Zalo:</span> {row.zaloGroup ? <a href={row.zaloGroup} target="_blank" className="text-blue-600 hover:underline">Tham gia nhóm</a> : 'N/A'}</div>
                                                    <div className="pt-2">
                                                         {!isViewOnly && (
                                                            <button 
                                                                onClick={() => handleDeleteProject(row.contractCode)}
                                                                className="text-red-500 hover:text-red-700 text-xs flex items-center gap-1 font-bold"
                                                            >
                                                                <Trash2 size={12} /> Xóa hồ sơ này
                                                            </button>
                                                        )}
                                                    </div>
                                                </div>
                                            </div>
                                        </td>
                                    </tr>
                                )}
                            </React.Fragment>
                        ))}
                         {projects.length === 0 && <tr><td colSpan={6} className="p-12 text-center text-gray-400 italic">Chưa có hồ sơ dự án nào</td></tr>}
                    </tbody>
                </table>
              </div>
          )}

      </div>

      {/* --- MODALS --- */}

      <Modal isOpen={isAppModalOpen} onClose={() => setAppModalOpen(false)} title="THÔNG TIN CUỘC HẸN">
          <div className="space-y-4 p-1">
              <Input label="Tên khách hàng" value={editingApp.customerName || ''} onChange={e => setEditingApp({...editingApp, customerName: e.target.value})} autoFocus />
              <div className="grid grid-cols-2 gap-4">
                   <Input label="Số điện thoại" value={editingApp.phone || ''} onChange={e => setEditingApp({...editingApp, phone: e.target.value})} />
                   <Input label="Tên công ty / Thương hiệu" value={editingApp.companyName || ''} onChange={e => setEditingApp({...editingApp, companyName: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                  <Input label="Thời gian hẹn" type="datetime-local" value={editingApp.date || ''} onChange={e => setEditingApp({...editingApp, date: e.target.value})} />
                  <Select label="Trạng thái" options={Object.values(AppointmentStatus).map(s => ({value: s, label: s}))} value={editingApp.status || AppointmentStatus.NEW} onChange={e => setEditingApp({...editingApp, status: e.target.value as AppointmentStatus})} />
              </div>
              <Combobox label="Tỉnh / Thành phố" value={editingApp.location || ''} onChange={val => setEditingApp({...editingApp, location: val})} options={VIETNAM_PROVINCES} />
              <Input label="Địa chỉ chi tiết" value={editingApp.addressDetail || ''} onChange={e => setEditingApp({...editingApp, addressDetail: e.target.value})} />
              <div className="w-full">
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Ghi chú thêm</label>
                  <textarea className="w-full border border-gray-300 rounded-md p-2 text-sm h-24" value={editingApp.notes || ''} onChange={e => setEditingApp({...editingApp, notes: e.target.value})}></textarea>
              </div>
              <div className="flex justify-end gap-3 pt-4 border-t mt-4">
                  <Button variant="ghost" onClick={() => setAppModalOpen(false)}>Hủy</Button>
                  <Button onClick={handleSaveApp} className="px-6">Lưu Cuộc Hẹn</Button>
              </div>
          </div>
      </Modal>

      <Modal isOpen={isConsModalOpen} onClose={() => setConsModalOpen(false)} title="PHIẾU TƯ VẤN KHÁCH HÀNG">
          <div className="space-y-4 p-1">
              <div className="grid grid-cols-2 gap-4">
                  <Input label="Ngày tư vấn" type="date" value={editingCons.date ? editingCons.date.substring(0, 10) : ''} onChange={e => setEditingCons({...editingCons, date: e.target.value})} />
                  <Input label="Số điện thoại" value={editingCons.phone || ''} onChange={e => setEditingCons({...editingCons, phone: e.target.value})} />
              </div>
              <Input label="Tên khách hàng" value={editingCons.customerName || ''} onChange={e => setEditingCons({...editingCons, customerName: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                  <Select label="Loại hình" options={Object.values(ConsultationType).map(t => ({value: t, label: t}))} value={editingCons.type || ConsultationType.NEW} onChange={e => setEditingCons({...editingCons, type: e.target.value as ConsultationType})} />
                  <Select label="Hình thức hỗ trợ" options={Object.values(SupportType).map(t => ({value: t, label: t}))} value={editingCons.supportType || SupportType.SOLO} onChange={e => setEditingCons({...editingCons, supportType: e.target.value as SupportType})} />
              </div>
              {editingCons.supportType !== SupportType.SOLO && (
                  <Input label="Người hỗ trợ (Tên)" value={editingCons.supportPersonName || ''} onChange={e => setEditingCons({...editingCons, supportPersonName: e.target.value})} placeholder="Nhập tên người hỗ trợ..." />
              )}
              <div className="w-full">
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Nội dung tư vấn</label>
                  <textarea className="w-full border border-gray-300 rounded-md p-2 text-sm h-24" value={editingCons.notes || ''} onChange={e => setEditingCons({...editingCons, notes: e.target.value})}></textarea>
              </div>
              <div className="flex justify-end gap-3 pt-4 border-t mt-4">
                  <Button variant="ghost" onClick={() => setConsModalOpen(false)}>Hủy</Button>
                  <Button onClick={handleSaveCons} className="px-6">Lưu Phiếu</Button>
              </div>
          </div>
      </Modal>

      <Modal isOpen={isRevModalOpen} onClose={() => setRevModalOpen(false)} title="GHI NHẬN DOANH THU">
          <div className="space-y-4 p-1">
              <div className="grid grid-cols-2 gap-4">
                  <Input label="Mã Hợp Đồng (Bắt buộc)" value={editingRev.contractCode || ''} onChange={e => setEditingRev({...editingRev, contractCode: e.target.value.toUpperCase()})} placeholder="VD: HĐ001" />
                  <Input label="Ngày thu tiền" type="date" value={editingRev.date ? editingRev.date.substring(0, 10) : ''} onChange={e => setEditingRev({...editingRev, date: e.target.value})} />
              </div>
              <Input label="Tên khách hàng / Đại diện" value={editingRev.customerName || ''} onChange={e => setEditingRev({...editingRev, customerName: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                  <Select label="Loại doanh thu" options={Object.values(RevenueType).map(t => ({value: t, label: t}))} value={editingRev.type || RevenueType.NEW} onChange={e => setEditingRev({...editingRev, type: e.target.value as RevenueType})} />
                  <Input label="Số tiền thu (VNĐ)" type="number" value={editingRev.amountCollected || 0} onChange={e => setEditingRev({...editingRev, amountCollected: Number(e.target.value)})} />
              </div>
              <div className="bg-yellow-50 p-3 rounded-lg text-xs text-yellow-700">
                  <b>Lưu ý:</b> Nếu là "Ký mới", hệ thống sẽ tự động tạo một Hồ sơ dự án tương ứng nếu chưa tồn tại. Vui lòng cập nhật chi tiết dự án sau.
              </div>
              <div className="flex justify-end gap-3 pt-4 border-t mt-4">
                  <Button variant="ghost" onClick={() => setRevModalOpen(false)}>Hủy</Button>
                  <Button onClick={handleSaveRev} className="px-6">Xác Nhận Thu</Button>
              </div>
          </div>
      </Modal>

      <Modal isOpen={isProjModalOpen} onClose={() => setProjModalOpen(false)} title="CẬP NHẬT HỒ SƠ DỰ ÁN">
            <div className="space-y-4 p-1 max-h-[70vh] overflow-y-auto pr-2">
                <div className="bg-gray-100 p-3 rounded-lg text-sm font-bold text-gray-700 flex justify-between">
                    <span>Mã Hợp Đồng: {editingProj.contractCode}</span>
                    <span className="text-green-600">Giá trị: {new Intl.NumberFormat('vi-VN', {style: 'currency', currency: 'VND'}).format(editingProj.contractValue || 0)}</span>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <Input label="Tên Khách hàng" value={editingProj.customerName || ''} onChange={e => setEditingProj({...editingProj, customerName: e.target.value})} />
                    <Input label="Số điện thoại" value={editingProj.phone || ''} onChange={e => setEditingProj({...editingProj, phone: e.target.value})} />
                </div>
                <Input label="Tên Công ty / Thương hiệu" value={editingProj.companyName || ''} onChange={e => setEditingProj({...editingProj, companyName: e.target.value})} />
                <Input label="Địa chỉ" value={editingProj.address || ''} onChange={e => setEditingProj({...editingProj, address: e.target.value})} />

                <div className="grid grid-cols-2 gap-4">
                    <Input label="Lĩnh vực kinh doanh" value={editingProj.industry || ''} onChange={e => setEditingProj({...editingProj, industry: e.target.value})} />
                    <Combobox label="Khu vực" value={editingProj.region || ''} onChange={val => setEditingProj({...editingProj, region: val})} options={VIETNAM_PROVINCES} />
                </div>

                <div className="border-t border-gray-100 pt-4 mt-2">
                    <h4 className="text-sm font-black text-gray-800 uppercase mb-3">Thông tin triển khai</h4>
                    <div className="grid grid-cols-2 gap-4 mb-3">
                         <Input label="Link Web Demo/Chính thức" value={editingProj.webLink || ''} onChange={e => setEditingProj({...editingProj, webLink: e.target.value})} placeholder="https://..." />
                         <Input label="Mật khẩu Web (nếu có)" value={editingProj.webPassword || ''} onChange={e => setEditingProj({...editingProj, webPassword: e.target.value})} />
                    </div>
                    <div className="grid grid-cols-2 gap-4 mb-3">
                         <Input label="Link Design (Figma/Image)" value={editingProj.designLink || ''} onChange={e => setEditingProj({...editingProj, designLink: e.target.value})} placeholder="https://..." />
                         <Input label="Gói Hosting (Dung lượng)" value={editingProj.hostingSize || ''} onChange={e => setEditingProj({...editingProj, hostingSize: e.target.value})} />
                    </div>
                    <Input label="Link/Tên Zalo Group hỗ trợ" value={editingProj.zaloGroup || ''} onChange={e => setEditingProj({...editingProj, zaloGroup: e.target.value})} />
                </div>

                <Input label="Người ký chung (nếu có)" value={editingProj.jointSigner || ''} onChange={e => setEditingProj({...editingProj, jointSigner: e.target.value})} />

                <div className="flex items-center justify-between pt-4 border-t mt-4">
                     {editingProj.contractCode && projects.some(p => p.contractCode === editingProj.contractCode) && !isViewOnly ? (
                        <button 
                            onClick={() => handleDeleteProject(editingProj.contractCode!)}
                            className="text-red-500 hover:text-red-700 hover:bg-red-50 p-2 rounded-lg transition-colors flex items-center gap-2 text-sm font-bold"
                            type="button"
                        >
                            <Trash2 size={18} /> <span className="hidden sm:inline">Xóa hồ sơ</span>
                        </button>
                     ) : <div></div>}
                     <div className="flex gap-3">
                        <Button variant="ghost" onClick={() => setProjModalOpen(false)}>Hủy</Button>
                        <Button onClick={handleSaveProject} className="px-6">Lưu Hồ Sơ</Button>
                     </div>
                </div>
            </div>
        </Modal>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, Appointment, Consultation, Revenue, ProjectProfile, AppointmentStatus, RevenueType, ConsultationType, SupportType } from '../types';
import { storageService } from '../services/storageService';
import { Button, Input, Select, Card, Badge, Modal, Combobox } from '../components/ui';
import { Calendar, MessageSquare, TrendingUp, Plus, Edit, Trash2, Phone, DollarSign, MapPin, Building2, ExternalLink, Clock, Layers, Globe, ChevronRight } from 'lucide-react';
import { VIETNAM_PROVINCES } from '../constants';

interface EmployeeDashboardProps {
  user: User;
  isViewOnly?: boolean;
}

export const EmployeeDashboard: React.FC<EmployeeDashboardProps> = ({ user, isViewOnly = false }) => {
  // State for data
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [consultations, setConsultations] = useState<Consultation[]>([]);
  const [revenues, setRevenues] = useState<Revenue[]>([]);
  const [projects, setProjects] = useState<ProjectProfile[]>([]);
  const [loading, setLoading] = useState(true);

  // Active Tab
  const [activeTab, setActiveTab] = useState<'appointments' | 'consultations' | 'revenues' | 'projects'>('appointments');

  // State for Project Expansion
  const [expandedProjects, setExpandedProjects] = useState<Record<string, boolean>>({});

  // Modals state
  const [isAppModalOpen, setAppModalOpen] = useState(false);
  const [editingApp, setEditingApp] = useState<Partial<Appointment>>({});

  const [isConsModalOpen, setConsModalOpen] = useState(false);
  const [editingCons, setEditingCons] = useState<Partial<Consultation>>({});

  const [isRevModalOpen, setRevModalOpen] = useState(false);
  const [editingRev, setEditingRev] = useState<Partial<Revenue>>({});

  const [isProjModalOpen, setProjModalOpen] = useState(false);
  const [editingProj, setEditingProj] = useState<Partial<ProjectProfile>>({});

  // Fetch Data
  const loadData = async () => {
    setLoading(true);
    try {
        const [allApps, allCons, allRevs, allProjs] = await Promise.all([
            storageService.getAppointments(),
            storageService.getConsultations(),
            storageService.getRevenues(),
            storageService.getProjects(),
        ]);

        // Filter for current user and sort descending by date
        setAppointments(allApps.filter(a => a.userId === user.id).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
        setConsultations(allCons.filter(c => c.userId === user.id).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
        setRevenues(allRevs.filter(r => r.userId === user.id).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
        setProjects(allProjs.filter(p => p.userId === user.id));

    } catch (error) {
        console.error("Error loading employee data", error);
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [user.id]);

  const toggleProject = (contractCode: string) => {
      setExpandedProjects(prev => ({ ...prev, [contractCode]: !prev[contractCode] }));
  };

  // --- Group Data By Date Helper ---
  const groupedData = useMemo(() => {
      const groups: Record<string, { apps: Appointment[], cons: Consultation[], revs: Revenue[] }> = {};

      const addToGroup = (dateStr: string, type: 'apps' | 'cons' | 'revs', item: any) => {
          const dateKey = dateStr.substring(0, 10);
          if (!groups[dateKey]) groups[dateKey] = { apps: [], cons: [], revs: [] };
          groups[dateKey][type].push(item);
      };

      if (activeTab === 'appointments') {
          appointments.forEach(a => addToGroup(a.date, 'apps', a));
      } else if (activeTab === 'consultations') {
          consultations.forEach(c => addToGroup(c.date, 'cons', c));
      } else if (activeTab === 'revenues') {
          revenues.forEach(r => addToGroup(r.date, 'revs', r));
      }

      // Sort dates descending
      return Object.keys(groups)
          .sort((a, b) => new Date(b).getTime() - new Date(a).getTime())
          .reduce((obj, key) => {
              obj[key] = groups[key];
              return obj;
          }, {} as typeof groups);
  }, [appointments, consultations, revenues, activeTab]);


  // --- Handlers (Keep logic same) ---
  const handleSaveApp = async () => {
      if (!editingApp.customerName || !editingApp.phone || !editingApp.date) return alert("Thiếu thông tin bắt buộc");
      try {
          const appData = { ...editingApp, userId: user.id, status: editingApp.status || AppointmentStatus.NEW } as Appointment;
          if (!appData.id) appData.id = `APP_${Date.now()}`;
          if (editingApp.id) await storageService.updateAppointment(appData, {id: user.id, name: user.name});
          else await storageService.addAppointment(appData, {id: user.id, name: user.name});
          setAppModalOpen(false); loadData();
      } catch (e: any) { alert(e.message); }
  };
  const handleDeleteApp = async (id: string) => { if (!confirm("Xóa cuộc hẹn này?")) return; await storageService.deleteAppointment(id, {id: user.id, name: user.name}); loadData(); };

  const handleSaveCons = async () => {
      if (!editingCons.customerName || !editingCons.phone || !editingCons.date) return alert("Thiếu thông tin bắt buộc");
      try {
          const consData = { ...editingCons, userId: user.id, type: editingCons.type || ConsultationType.NEW, supportType: editingCons.supportType || SupportType.SOLO } as Consultation;
          if (!consData.id) consData.id = `CONS_${Date.now()}`;
          if (editingCons.id) await storageService.updateConsultation(consData, {id: user.id, name: user.name});
          else await storageService.addConsultation(consData, {id: user.id, name: user.name});
          setConsModalOpen(false); loadData();
      } catch (e: any) { alert(e.message); }
  };
  const handleDeleteCons = async (id: string) => { if (!confirm("Xóa phiếu tư vấn này?")) return; await storageService.deleteConsultation(id, {id: user.id, name: user.name}); loadData(); };

  const handleSaveRev = async () => {
      if (!editingRev.contractCode || !editingRev.amountCollected || !editingRev.date) return alert("Thiếu thông tin bắt buộc");
      try {
          const revData = { ...editingRev, userId: user.id, type: editingRev.type || RevenueType.NEW, isApproved: editingRev.isApproved || false, contractValue: editingRev.contractValue || editingRev.amountCollected } as Revenue;
          if (!revData.id) revData.id = `REV_${Date.now()}`;
          if (editingRev.id) await storageService.updateRevenue(revData, {id: user.id, name: user.name});
          else await storageService.addRevenue(revData, {id: user.id, name: user.name});

          if (revData.type === RevenueType.NEW) {
              const existingProj = projects.find(p => p.contractCode === revData.contractCode);
              if (!existingProj) {
                  await storageService.addProject({ contractCode: revData.contractCode, userId: user.id, customerName: revData.customerName || '', phone: revData.phone || '', contractValue: revData.contractValue });
              }
          }
          setRevModalOpen(false); loadData();
      } catch (e: any) { alert(e.message); }
  };
  const handleDeleteRev = async (id: string) => { if (!confirm("Xóa khoản thu này?")) return; await storageService.deleteRevenue(id, {id: user.id, name: user.name}); loadData(); };

  const handleSaveProject = async () => {
      if (!editingProj.contractCode) return alert("Thiếu mã hợp đồng");
      try {
          const projData = { ...editingProj, userId: user.id } as ProjectProfile;
          const exists = projects.some(p => p.contractCode === editingProj.contractCode);
          if (exists) await storageService.updateProject(projData, {id: user.id, name: user.name}); else await storageService.addProject(projData);
