                  if ((window as any).confetti) {
                      const duration = 3000;
                      const end = Date.now() + duration;
                      (function frame() {
                        (window as any).confetti({
                          particleCount: 5,
                          angle: 60,
                          spread: 55,
                          origin: { x: 0 },
                          colors: ['#26ccff', '#a25afd', '#ff5e7e', '#88ff5a', '#fcff42', '#ffa62d', '#ff36ff']
                        });
                        (window as any).confetti({
                          particleCount: 5,
                          angle: 120,
                          spread: 55,
                          origin: { x: 1 },
                          colors: ['#26ccff', '#a25afd', '#ff5e7e', '#88ff5a', '#fcff42', '#ffa62d', '#ff36ff']
                        });
                        if (Date.now() < end) {
                          requestAnimationFrame(frame);
                        }
                      }());
                  }

